/* C major pentatonic, two octaves up from C5: each answer in a streak lands
   a step higher, so a run of right answers climbs like a melody */
const PENTA = [523.25, 587.33, 659.25, 783.99, 880, 1046.5, 1174.66, 1318.51, 1567.98, 1760];
const pStep = k => PENTA[Math.max(0, Math.min(PENTA.length - 1, k))];

Object.assign(snd, {
  /* a paper slip pressed onto the table: a soft wooden tok */
  select() { noise(.05, { type: 'lowpass', freq: 1100, q: .7, vol: .045, attack: .002 });
             tone(540, .07, { type: 'sine', vol: .03, to: 430 }); },
  correct(k) {
    k = k || 0;
    noise(.04, { type: 'lowpass', freq: 1500, q: .8, vol: .06, attack: .002 });   // the sticker pressed down
    const r = Math.min(k, 5);
    kalimba(pStep(r), { vol: .085, delay: .02 });
    kalimba(pStep(r + 2), { vol: .075, delay: .1 });
    kalimba(pStep(r + 4), { vol: .07, delay: .18, dur: 1.2 });
    if (k >= 2) crowd(1.6, { shape: 'cheer', vol: Math.min(.06, .022 + k * .007), delay: .08 });
    if (k >= 4) [0, 1, 2].forEach(i => kalimba(pStep(7 + i) * 2, { vol: .02, delay: .32 + i * .06, dur: .5 }));
  },
  almost() { kalimba(587.33, { vol: .075 }); kalimba(659.25, { vol: .06, delay: .12 }); },
  wrong() {                                                       // a wooden knock, and the stands groan
    tone(150, .3, { type: 'sine', vol: .11, to: 88 });
    noise(.12, { type: 'lowpass', freq: 420, q: .7, vol: .07, delay: .01 });
    crowd(1.1, { shape: 'groan', vol: .045, delay: .06 });
  },
  lock() { noise(.08, { type: 'lowpass', freq: 650, q: .6, vol: .08 });
           tone(196, .25, { type: 'sine', vol: .08 });
           pad([98, 146.83], 1.6, { vol: .022, delay: .05 }); },
  heartbeat() { tone(70, .14, { type: 'sine', vol: .1, to: 52 });
                tone(64, .12, { type: 'sine', vol: .07, to: 48, delay: .16 }); },
  tick(n) { noise(.02, { freq: n <= 3 ? 2600 : 2100, q: 2.5, vol: .09, attack: .001 });
            tone(n <= 3 ? 1320 : 990, .05, { type: 'sine', vol: .045 }); },
  whistle() { bell(392, { vol: .05, dur: 1.4 }); bell(392, { vol: .045, delay: .45, dur: 1.8 }); },   // time: the bell, twice
  /* the ladder: each rung a step higher than the last */
  rung(k) {
    k = k || 0;
    noise(.17, { type: 'highpass', freq: 600, to: 3000, q: .5, vol: .04 });
    kalimba(pStep(k % 6), { vol: .08, delay: .05 });
    kalimba(pStep(k % 6 + 2), { vol: .075, delay: .14 });
    kalimba(pStep(k % 6 + 4), { vol: .07, delay: .23, dur: 1.2 });
    pad([pStep(k % 6) / 4, pStep(k % 6 + 2) / 2], 1.4, { vol: .02, delay: .05 });
  },
  fanfare() {                                                     // the million: the whole stadium
    pad([130.81, 196, 261.63, 329.63, 392], 4, { vol: .04 });
    [0, 2, 4, 5, 7, 9].forEach((k, i) => kalimba(pStep(k), { vol: .08, delay: .1 + i * .11, dur: 1.4 }));
    crowd(4.2, { shape: 'cheer', vol: .075, delay: .15 });
    [523.25, 392, 329.63, 261.63].forEach((f, i) => bell(f, { vol: .045, delay: 1.1 + i * .38, dur: 2.6 }));   // the bells of the city
    noise(.8, { type: 'highpass', freq: 5000, q: .4, vol: .02, delay: .2 });
  },
  cash() { kalimba(783.99, { vol: .08 }); kalimba(1046.5, { vol: .08, delay: .09 });
           noise(.25, { type: 'highpass', freq: 5200, q: .5, vol: .02, delay: .1 }); },
  drop() {
    tone(300, .6, { type: 'sine', vol: .09, to: 70 });
    noise(.4, { type: 'lowpass', freq: 900, to: 180, q: .6, vol: .05 });
    crowd(1.6, { shape: 'groan', vol: .06, delay: .1 });
  },
  /* the end of a game: the bell rings the hour, and the hall answers */
  final(good) { bell(392, { vol: .05, dur: 1.6 }); bell(329.63, { vol: .05, delay: .42, dur: 1.8 }); bell(261.63, { vol: .055, delay: .84, dur: 2.6 });
                if (good) crowd(2.6, { shape: 'cheer', vol: .05, delay: .7 }); },
  count(k) { noise(.012, { freq: 2400 + k * 1600, q: 3, vol: .03, attack: .001 });
             tone(700 + k * 700, .03, { type: 'sine', vol: .016 }); },
  land() { noise(.05, { type: 'lowpass', freq: 900, q: .7, vol: .07, attack: .002 });
           kalimba(523.25, { vol: .07 }); kalimba(659.25, { vol: .06, delay: .03 }); kalimba(783.99, { vol: .06, delay: .06, dur: 1.3 }); },
  freeze() { [1568, 1244.5, 1046.5].forEach((f, i) => kalimba(f, { vol: .045, delay: i * .06, dur: .6 }));
             noise(.5, { type: 'highpass', freq: 4500, q: .6, vol: .02, attack: .1 }); },
});

