/* ═══════════════════════════════════════════════════
   FLAGS — drawn, not typed

   Flag emoji (🇧🇷 and friends) are regional-indicator pairs: Android WebView
   and Windows have no glyphs for most of them, so they degrade to the bare
   letters "BR" or to tofu boxes. The England flag is worse still — a tag
   sequence that almost nothing outside Apple renders. Every flag here is
   therefore hand-drawn SVG on a 9×6 field, which looks identical on every
   device the app can possibly run on.
═══════════════════════════════════════════════════ */
const _NORDIC = (bg, cross, inner) =>
  `<rect width="9" height="6" fill="${bg}"/>` +
  `<path d="M0 2.35h9v1.3H0z M2.45 0h1.3v6h-1.3z" fill="${cross}"/>` +
  (inner ? `<path d="M0 2.7h9v.6H0z M2.8 0h.6v6h-.6z" fill="${inner}"/>` : '');

const _VERT = (a, b, c) =>
  `<rect width="3" height="6" fill="${a}"/><rect x="3" width="3" height="6" fill="${b}"/>` +
  `<rect x="6" width="3" height="6" fill="${c}"/>`;

const _HORZ = (a, b, c) =>
  `<rect width="9" height="2" fill="${a}"/><rect y="2" width="9" height="2" fill="${b}"/>` +
  `<rect y="4" width="9" height="2" fill="${c}"/>`;

const _STAR = (cx, cy, r, fill) => {
  let d = '';
  for (let i = 0; i < 5; i++) {
    const o = -Math.PI / 2 + i * 2 * Math.PI / 5;
    const inn = o + Math.PI / 5;
    d += (i ? 'L' : 'M') + (cx + Math.cos(o) * r).toFixed(2) + ' ' + (cy + Math.sin(o) * r).toFixed(2)
       + 'L' + (cx + Math.cos(inn) * r * .4).toFixed(2) + ' ' + (cy + Math.sin(inn) * r * .4).toFixed(2);
  }
  return `<path d="${d}Z" fill="${fill}"/>`;
};

