/*@@/flags_extra@@*/

/* A drawn flag chip. `h` is the height in px; the flag keeps a 3:2 ratio. */
function flagSVG(code, h) {
  h = h || 8;
  const name = CTRY_NAME[code] || code || '';
  const art  = FLAGS[code];
  const box  = `width:${(h * 1.5).toFixed(1)}px;height:${h}px;flex-shrink:0;vertical-align:-1px;
    border-radius:1.5px;box-shadow:0 0 0 .5px rgba(0,0,0,.35);`;
  if (!art) {
    return `<span title="${name}" style="${box}display:inline-block;background:#3a4a5a;
      font-size:${(h * .78).toFixed(0)}px;line-height:${h}px;text-align:center;color:#fff;
      font-weight:800;letter-spacing:-.3px;">${(code || '?').slice(0, 2)}</span>`;
  }
  return `<svg viewBox="0 0 9 6" preserveAspectRatio="none" role="img" aria-label="${name}"
    style="${box}display:inline-block;">${art}</svg>`;
}

/* The little mark on a category chip. Most categories carry an emoji that
   every platform has a glyph for; the ones whose natural mark is a flag set
   `flag` instead and get the drawing, because a flag emoji would come out as
   the bare letters "BR". */
function catIcon(c) {
  if (!c) return '';
  if (c.flag) return flagSVG(c.flag, 10);
  return c.col ? `<span class="dot" style="background:${c.col}" aria-hidden="true"></span>` : '';
}

/* ═══════════════════════════════════════════════════
   ICONS — drawn, not typed

   ✓ ✗ ✕ ★ → and friends are *text* symbols, not emoji: Roboto has no
   glyph for most of them, so Android's WebView draws an empty box. The
   ones that are emoji but default to text presentation (✂ ❄ ⏭ 🛡 🗺)
   are just as unreliable. Everything structural in the UI is therefore
   an inline SVG path — same pixels on every device, and it inherits the
   colour we actually want instead of a vendor's.
═══════════════════════════════════════════════════ */
const _ico = (d, extra) => (c, s) =>
  `<svg viewBox="0 0 24 24" width="${s || 14}" height="${s || 14}" fill="none"
     stroke="${c || 'currentColor'}" stroke-width="2.4" stroke-linecap="round"
     stroke-linejoin="round" aria-hidden="true"
     style="display:inline-block;vertical-align:-.14em;flex-shrink:0;${extra || ''}"><path d="${d}"/></svg>`;

