function earnedMedals() { return MEDALS.filter(m => { try { return m.t(stats); } catch (e) { return false; } }); }

/* returns medals unlocked by the run that just finished */
function newMedals() {
  try { metasCheck(); } catch (e) {}   // a goal of the week met pays its stamp, and may make a medal
  const had = new Set(LS.get('medals', []));
  const now = earnedMedals().map(m => m.id);
  LS.set('medals', now);
  const fresh = MEDALS.filter(m => now.includes(m.id) && !had.has(m.id));
  /* The day each one was won, printed on its card. Only from here on: the
     ones earned before this was kept show no date rather than a made-up one. */
  if (fresh.length) {
    const at = LS.get('medalAt', {});
    const d = new Date();
    const today = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    fresh.forEach(m => { if (!at[m.id]) at[m.id] = today; });
    LS.set('medalAt', at);
  }
  return fresh;
}

/* ── How the figurinhas especiais are printed ──
   Four sets, sectioned like the album. The shape of the emblem is the set;
   the ink is the tier. */
const MEDAL_SETS = [
  { id:'campo',  n:'Em jogo',        tag:'Jogo',   shape:'seal',
    ids:['first','ten','perfect','streak5','streak10','hard','c100','c500'] },
  { id:'album',  n:'O álbum',        tag:'Álbum',  shape:'shield',
    ids:['alb25','alb60','albHalf','alb3q','albAll','albEsc','albSel','albMsc','albBook'] },
  { id:'rotina', n:'Rotina',         tag:'Rotina', shape:'hex',
    ids:['daily3','daily7','surv10','revLearn','hoje400','cronDia7','semana1','semana4'] },
  { id:'milhao', n:'Rumo ao Milhão', tag:'Milhão', shape:'coin',
    ids:['safe1','safe2','quit','million'] },
  { id:'arquivo', n:'O arquivo',     tag:'Arquivo', shape:'hex',
    ids:['fQuote','fBattle','fLine','fNews','fDuel','fMyth','fOrder','fAll'] },
  { id:'selos',  n:'Selos, anos e lugares', tag:'Selos', shape:'seal',
    ids:['selo10','selo50','seloPg','anoExato','ano700','ondeMosca','onde700','cron10','cron25'] },
];
/* How hard each one is to get, not how many people hold it — there is no
   server to count that, and a made-up percentage would be a lie. */
/* the ways a question can be asked, as the archive counts them */
const FMT_KEYS = ['quote', 'battle', 'line', 'news', 'duel', 'myth', 'order'];
const qFmt = q => !q ? '' : q.quote ? 'quote' : q.battle ? 'battle' : q.line ? 'line' : q.news ? 'news'
                : q.myth ? 'myth' : q.duel ? 'duel' : q.order ? 'order' : '';
const fmtN = (st, k) => ((st && st.fmt) || {})[k] || 0;
const MEDAL_TIER = {
  first:1, ten:1, streak5:1, alb25:1, daily3:1, safe1:1,
  perfect:2, streak10:2, c100:2, alb60:2, albHalf:2, daily7:2, safe2:2,
  hard:3, c500:3, alb3q:3, albEsc:3, albSel:3, albMsc:3, surv10:3, quit:3,
  albAll:4, albBook:4, million:4,
  fQuote:2, fBattle:2, fLine:2, fNews:2, fOrder:2, fDuel:2, fMyth:2, fAll:3,
  selo10:1, anoExato:2, selo50:2, ano700:3, seloPg:3, ondeMosca:2, onde700:3, revLearn:2,
  cron10:2, cron25:3, hoje400:2, cronDia7:2, semana1:2, semana4:3,
};
const TIER_NAME = ['', 'Comum', 'Rara', 'Épica', 'Lendária'];
const medalSet = m => MEDAL_SETS.find(s => s.ids.includes(m.id)) || MEDAL_SETS[0];

const INS_SHAPE = (() => {
  const seal = [];
  for (let i = 0; i < 40; i++) {
    const a = i / 40 * Math.PI * 2 - Math.PI / 2, r = i % 2 ? 27.6 : 30.8;
    seal.push(`${(32 + r * Math.cos(a)).toFixed(1)},${(32 + r * Math.sin(a)).toFixed(1)}`);
  }
  return {
    seal:   `<polygon points="${seal.join(' ')}"/>`,
    shield: '<path d="M32 3 57 10.5V30c0 16.5-10.5 26.5-25 31C17.5 56.5 7 46.5 7 30V10.5Z"/>',
    hex:    '<path d="M32 2.5 57.5 17.2v29.6L32 61.5 6.5 46.8V17.2Z"/>',
    coin:   '<circle cx="32" cy="32" r="30"/>',
  };
})();

function medalProgress(m) {
  if (!m.p) return null;
  try {
    const [have, need] = m.p(stats);
    return { have: Math.min(have, need), need,
             pct: Math.max(0, Math.min(100, Math.round(have / need * 100))) };
  } catch (e) { return null; }
}
const fmtDay = iso => iso ? iso.split('-').reverse().join('/') : '';

/* One figurinha especial, as printed on its own screen. */
/* The back of a figurinha especial, seen only when it is held up and turned. */
function medalBack(m, on) {
  const set = medalSet(m), tier = MEDAL_TIER[m.id] || 1;
  const pr = on ? null : medalProgress(m);
  const at = on ? LS.get('medalAt', {})[m.id] : null;
  return `<div class="ins ins-r${tier} ${on ? 'is-on' : 'is-off'} ins-back">
    <span class="ins-band"><span>${set.tag}</span><span>Nº ${String(MEDALS.indexOf(m) + 1).padStart(2, '0')}</span></span>
    <span class="insb-set">${set.n}</span>
    <span class="insb-nm">${m.n}</span>
    <span class="insb-rule"></span>
    <span class="insb-d">${m.d}</span>
    <span class="insb-st">${on ? (at ? `Conquistada em ${fmtDay(at)}` : 'Conquistada') : 'Ainda não conquistada'}</span>
    ${pr ? `<span class="insb-pr"><b>${pr.have}</b> de ${pr.need}</span>
      <span class="ins-prog"><i style="width:${pr.pct}%"></i></span>` : ''}
    <span class="ins-rar"><span class="ins-pips">${
      [1, 2, 3, 4].map(k => `<i${k <= tier ? ' class="on"' : ''}></i>`).join('')}</span>${TIER_NAME[tier]}</span>
  </div>`;
}

/* ── Held up to the light ─────────────────────────────────────
   A tap lifts the card off the page and brings it to the middle of the
   screen, big enough to read; the next tap turns it over, the one after
   turns it back. Tapping outside, the close button or Escape puts it back
   where it came from. The card is scaled rather than re-laid-out, so it is
   the same card, just closer. */
let _zoom = null;
function openZoom(src, front, back, lookFrom, opts) {
  opts = opts || {};
  if (_zoom || !src) return;
  const r = src.getBoundingClientRect();
  if (!r.width || !r.height) return;
  const vw = window.innerWidth, vh = window.innerHeight;
  const k = Math.max(1, Math.min(Math.min(vw * 0.8, 340) / r.width, (vh * 0.68) / r.height));
  /* A card built at its final size (`opts.w`) is laid out and drawn there,
     crisp; only its flight out of the pocket is scaled. Blowing the pocket
     up four times instead left Android drawing a 75px card stretched to
     340 — soft lettering, a fuzzy guilloché, a slow turn. */
  const native = !!opts.w;
  const cw = native ? opts.w : r.width, ch = native ? opts.h : r.height;
  const z = document.createElement('div');
  z.className = 'zoom';
  z.setAttribute('role', 'dialog');
  z.setAttribute('aria-modal', 'true');
  z.setAttribute('aria-label', 'Figurinha ampliada');
  z.innerHTML = `<div class="zoom-scrim"></div>
    <div class="zoom-card" tabindex="0" role="button" aria-label="Virar a figurinha"
      style="width:${cw}px;height:${ch}px">
      <div class="zoom-in">
        <div class="zoom-face zoom-front">${front}</div>
        <div class="zoom-face zoom-back">${back}</div>
      </div>
      <span class="zoom-scanline" aria-hidden="true"></span>
    </div>
    <button class="zoom-x" type="button" aria-label="Fechar">${ICON.close ? ICON.close('currentColor', 16) : '×'}</button>
    ${opts.sid ? zoomLabel(opts.sid) : ''}
    <div class="zoom-hint">Toque na figurinha para virar${opts.sid && anyCopy(opts.sid) && anyCopy(opts.sid).f > 0 ? ' · incline para ver o brilho' : ''}</div>
    ${opts.sid ? zoomActs(opts.sid) : ''}`;
  document.body.appendChild(z);
  const card = z.querySelector('.zoom-card');
  if (opts.sid) { z.classList.add('has-acts'); wireZoomActs(z, opts.sid);
    const zc = anyCopy(opts.sid); if (zc) z.dataset.f = zc.v ? 'v' : zc.f; }
  Tilt.ask();
  /* ── the light follows the finger ──
     Over a zoomed card the pointer is the lamp: the card leans towards it and
     the foil slides with it. Let go and it settles back to the phone's tilt. */
  let tiltT = 0;
  z.addEventListener('pointermove', e => {
    if (e.pointerType === 'touch' && !e.isPrimary) return;
    const rc = card.getBoundingClientRect();
    const w = rc.width / 2 || 1, h = rc.height / 2 || 1;
    const gx = Math.max(-1, Math.min(1, (e.clientX - (rc.left + rc.width / 2)) / Math.max(w, 120)));
    const gy = Math.max(-1, Math.min(1, (e.clientY - (rc.top + rc.height / 2)) / Math.max(h, 160)));
    card.style.setProperty('--gx', gx.toFixed(3));
    card.style.setProperty('--gy', gy.toFixed(3));
    z.classList.add('is-tilting');
    clearTimeout(tiltT);
    tiltT = setTimeout(() => z.classList.remove('is-tilting'), 160);
  });
  z.addEventListener('pointerleave', () => { card.style.removeProperty('--gx'); card.style.removeProperty('--gy'); Tilt.lx = 9; });
  /* the album shrinks its lettering on small pockets with container queries;
     the copy is outside that container, so it takes the sizes it had */
  if (lookFrom && !native) {
    const dst = z.querySelector('.zoom-front');
    ['.fig-band', '.fig-nm', '.fig-sub', '.fig-cap'].forEach(sel => {
      const a = lookFrom.querySelectorAll(sel), b = dst.querySelectorAll(sel);
      a.forEach((el, i) => {
        if (!b[i]) return;
        const cs = getComputedStyle(el);
        ['fontSize', 'letterSpacing', 'paddingLeft', 'paddingRight', 'display', 'height', 'lineHeight']
          .forEach(p => { b[i].style[p] = cs[p]; });
      });
    });
  }
  /* the zoom is the pocket scaled up k times, so its lettering is laid out
     at pocket size: what matters is how big it reads once scaled — 7px on the
     glass, still plain on a card this size — not how far it shrank from the
     pocket's own size */
  if (!native) try { fitFigText(z.querySelector('.zoom-front'), 7 / k, 0); } catch (e) {}
  const still = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const cx = vw / 2, cy = vh / 2;
  const at = rect => `translate(calc(-50% + ${rect.left + rect.width / 2 - cx}px), calc(-50% + ${rect.top + rect.height / 2 - cy}px)) scale(${native ? (rect.width / cw).toFixed(4) : 1})`;
  const big = native ? 'translate(-50%, -50%)' : `translate(-50%, -50%) scale(${k})`;
  card.style.transform = big;
  if (!still && card.animate) card.animate([{ transform: at(r) }, { transform: big }],
    { duration: 380, easing: 'cubic-bezier(.2,.8,.2,1)' });
  src.style.visibility = 'hidden';
  const turnOver = () => { z.classList.remove('is-tilting'); z.classList.toggle('is-turned'); snd.swipe(); };
  const onKey = e => {
    if (e.key === 'Escape') { e.preventDefault(); close(); }
    else if ((e.key === 'Enter' || e.key === ' ') && document.activeElement === card) { e.preventDefault(); turnOver(); }
  };
  const close = () => {
    if (!_zoom) return;
    _zoom = null;
    document.removeEventListener('keydown', onKey);
    const done = () => { z.remove(); src.style.visibility = '';
      if (z.dataset.dirty && sc === 'vitrine') go(); };
    z.classList.add('is-closing');
    z.classList.remove('is-turned');
    const home = src.isConnected ? src.getBoundingClientRect() : r;
    if (!still && card.animate) {
      const a = card.animate([{ transform: big }, { transform: at(home) }],
        { duration: 300, easing: 'cubic-bezier(.4,0,.6,1)', fill: 'forwards' });
      a.onfinish = done;
      setTimeout(done, 600);
    } else done();
  };
  card.addEventListener('click', turnOver);
  z.querySelector('.zoom-scrim').addEventListener('click', close);
  z.querySelector('.zoom-x').addEventListener('click', close);
  document.addEventListener('keydown', onKey);
  _zoom = { close };
  snd.swipe();
  try { card.focus({ preventScroll: true }); } catch (e) {}
}

function medalCard(m, on) {
  const set = medalSet(m), tier = MEDAL_TIER[m.id] || 1;
  const shape = INS_SHAPE[set.shape];
  const pr = on ? null : medalProgress(m);
  const at = on ? LS.get('medalAt', {})[m.id] : null;
  const sub = on ? (at ? `Conquistada ${fmtDay(at)}` : 'Conquistada')
            : m.d;
  return `<div class="ins ins-r${tier} ${on ? 'is-on' : 'is-off'}" data-medal="${m.id}" role="img"
      aria-label="${m.n}: ${on ? 'conquistada' : 'ainda não'}. ${m.d}. ${TIER_NAME[tier]}.">
    <span class="ins-band"><span>${set.tag}</span><span>Nº ${String(MEDALS.indexOf(m) + 1).padStart(2, '0')}</span></span>
    <span class="ins-emb">
      ${on && tier === 4 ? '<span class="ins-rays"></span>' : ''}
      <svg class="ins-svg" viewBox="0 0 64 64" aria-hidden="true">
        <g class="ins-shape">${shape}</g>
        ${on ? `<g fill="none" stroke="currentColor" stroke-width="1.3" opacity=".5"
                  transform="translate(32 32) scale(.8) translate(-32 -32)">${shape}</g>` : ''}
        ${on && set.shape === 'coin' ? `<circle cx="32" cy="32" r="28.6" fill="none" stroke="currentColor"
                  stroke-width="2.2" stroke-dasharray="1 2.3" opacity=".35"/>` : ''}
      </svg>
      ${(ICON[m.ic] || ICON.medal)('currentColor', 22)}
    </span>
    <span class="ins-perf"></span>
    <span class="ins-nm">${m.n}</span>
    <span class="ins-sub">${sub}</span>
    ${pr ? `<span class="ins-prog"><i style="width:${pr.pct}%"></i></span>` : ''}
    <span class="ins-rar"><span class="ins-pips">${
      [1, 2, 3, 4].map(k => `<i${k <= tier ? ' class="on"' : ''}></i>`).join('')}</span>${TIER_NAME[tier]}</span>
  </div>`;
}

/* ═══════════════════════════════════════════════════
   SURVIVAL — one mistake and the run is over
═══════════════════════════════════════════════════ */
let isSurv = false;

function startSurvival() {
  isSurv = true; isDaily = false; isMil = false; isRev = false; _seed = null; runSeed = null;
  diffKey = 'moderado';
  cat = buildGame('moderado');
  cat.name = 'Mata-mata';
  // a long queue; the run ends on the first mistake, not on length
  const extra = buildGame('dificil');
  cat.qs = cat.qs.concat(extra.qs);
  qi = 0; sel.clear(); pts = 0; prevPts = 0; streak = 0;
  nCorrect = 0; nPartial = 0; bestStreak = 0; lastGain = 0; runLog = []; runNew = 0; runNewIds = []; runPulls = []; runSelos = []; runPackOpened = false; gameN++;
  resetLifes();
  sc = 'quiz'; tMax = qTime(); tLeft = tMax; lastMsg = '';
  disp = getDisp(cat.qs[0]);
  startTmr();
  go();
}

/* ═══════════════════════════════════════════════════
   RUMO AO MILHÃO — the prize ladder

   The headline mode. Sixteen questions, one per rung, each worth
   more than the last and each drawn from a harder pool with a shorter
   clock and nastier distractors. Two rungs are checkpoints: clear one
   and that money is yours whatever happens afterwards. Miss a question
   and the run ends at your last checkpoint — so every rung above one is
   a bet, and "PARAR" is always on the table.
═══════════════════════════════════════════════════ */
/* Sixteen rungs across five tiers, so the climb is a climb. The two safe
   rungs sit at the top of a tier — you bank at the end of a plateau, then the
   questions step up. */
const LADDER = [
  { v:      1000, tier: 1, time: 45 },
  { v:      2000, tier: 1, time: 45 },
  { v:      3000, tier: 1, time: 42 },
  { v:      5000, tier: 1, time: 40, safe: true },
  { v:     10000, tier: 2, time: 38 },
  { v:     15000, tier: 2, time: 36 },
  { v:     20000, tier: 2, time: 34 },
  { v:     30000, tier: 3, time: 32 },
  { v:     50000, tier: 3, time: 30, safe: true },
  { v:     75000, tier: 3, time: 30 },
  { v:    100000, tier: 4, time: 28 },
  { v:    150000, tier: 4, time: 26 },
  { v:    250000, tier: 4, time: 24 },
  { v:    400000, tier: 5, time: 22 },
  { v:    600000, tier: 5, time: 20 },
  { v:   1000000, tier: 5, time: 20 },
];

let isMil  = false;
let rung   = 0;       // index into LADDER — the question being played for
let banked = 0;       // guaranteed by the last checkpoint cleared
let cashed = false;   // player pressed PARAR instead of falling
let ladderOpen = false;   // the ladder sheet is up; the clock waits

const RUNG    = () => LADDER[Math.min(rung, LADDER.length - 1)];
const isFinal = () => rung === LADDER.length - 1;

/* R$ 1.000.000 — pt-BR grouping without leaning on Intl in old WebViews */
function money(v) {
  return 'R$ ' + String(v).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

/* the money you walk away with if you get this one wrong */
function safetyNet() {
  let v = 0;
  for (let i = 0; i < rung; i++) if (LADDER[i].safe) v = LADDER[i].v;
  return v;
}

/* seconds on the clock and distractor strictness for the current question */
/* Seconds on the clock. A carta especial is read, not skimmed — four clues,
   or four events to put in order — so it gets a floor instead of the squeeze
   its tier would normally apply. R$ 600.000 is a hard enough thing to ask
   without twenty seconds to sort four decades in. */
function qTime() {
  if (isRev) return 40;                  // a review is for remembering, not for racing
  if (!isMil) return DCFG().time;
  const q = cat && cat.qs && cat.qs[qi];
  if (q && q._special) return Math.max(RUNG().time, q.order ? 50 : 45);
  return RUNG().time;
}
function qStrict() { return isMil ? Math.min(1, (_dealQi == null ? rung : _dealQi) / (LADDER.length - 1) * 1.15) : DCFG().strict; }

/* One question per rung, each matched to that rung's tier. Built in one pass
   so a question can never repeat inside a run. */
function buildMilhao() {
  let all = CATS.flatMap(c => c.qs.map(q => ({ ...q, _cat: c })));
  if (typeof GEN_QS === 'function') {
    all = all.concat(GEN_QS(1)).concat(GEN_QS(2)).concat(GEN_QS(3));
  }
  all.forEach(q => { q._d = qTier(q); });

  const seen = new Set();
  const pool = shuf(all).filter(q => { if (seen.has(q.t)) return false; seen.add(q.t); return true; });

  const used = new Set();
  const usedA = new Set();
  const byCat = {}, byShape = {};
  let prevCat = null, prevShape = null;
  const genTarget = Math.round(LADDER.length * 0.3);
  let genN = 0;

  /* ── Why the same climb twice ──────────────────────────────────
     The weights below were deterministic apart from a ±3 jitter, and the tier
     term is ±10 per step, so among the dozens of questions that fit a rung the
     same one won every single time. Rung one was always "de que estado é este
     clube?", rung two was always the goalkeeper question. Sixteen right
     answers in the same order is still a recipe.

     Two things change that, and neither touches the ramp. A standing
     preference per shape family, drawn once per climb, so this climb likes
     what the last one passed over. And the pick is made at random from
     everything scoring within a hair of the best rather than from the best
     alone — the margin is under the tier step, so a question from the wrong
     tier can never win it. */
  const bias = {};
  const biasOf = k => (bias[k] !== undefined ? bias[k] : (bias[k] = (rnd() - 0.5) * 9));
  const PICK_MARGIN = 7;

  const pickFor = step => {
    /* The shortlist is kept as we go and pruned whenever the bar rises, rather
       than scoring the whole pool into an array and filtering it afterwards:
       that was a couple of thousand throwaway objects per rung, and a climb is
       built sixteen times over. */
    let bestW = -1e9;
    let near = [];
    for (let i = 0; i < pool.length; i++) {
      if (used.has(i) || usedA.has(ansKey(pool[i]))) continue;
      const cid   = (pool[i]._cat && pool[i]._cat.id) || '?';
      const shape = qShape(pool[i]);
      const w = -Math.abs(pool[i]._d - step.tier) * 10 + rnd() * 3
              + (String(cid).startsWith('g_') ? 0 : 5)   // prefer a written question
              + biasOf(shape)
              - (byCat[cid] || 0) * 5
              - (byShape[shape] || 0) * 12
              - (cid === prevCat ? 8 : 0)
              - (shape === prevShape ? 14 : 0)
              + (String(cid).startsWith('g_') && genN < genTarget ? 16 : 0);
      if (w > bestW) {
        bestW = w;
        near = near.filter(c => c.w >= bestW - PICK_MARGIN);
        near.push({ i, w });
      } else if (w >= bestW - PICK_MARGIN) {
        near.push({ i, w });
      }
    }
    if (!near.length) return null;
    const best = near[Math.floor(rnd() * near.length)].i;
    used.add(best);
    const q = pool[best];
    usedA.add(ansKey(q));
    const cid = (q._cat && q._cat.id) || '?';
    byCat[cid] = (byCat[cid] || 0) + 1;
    byShape[qShape(q)] = (byShape[qShape(q)] || 0) + 1;
    if (String(cid).startsWith('g_')) genN++;
    prevCat = cid; prevShape = qShape(q);
    return q;
  };
  const qs = LADDER.map(pickFor).filter(Boolean);
  /* and a second for every rung, for Pular: a skipped question is swapped for its rung's spare, so the climb never runs
     a question short, and a friend sent the same climb sees the same questions on every rung they did not skip */
  const spare = LADDER.map(pickFor);

  /* Four of the sixteen rungs stop being a written question here and become
     a card dealt from the album's own data. It is the same climb; it just
     stops being sixteen of the same shape. */
  dealSpecials(qs);

  return { id:'milhao', name:'Rumo ao Milhão', emoji:'💰',
           tag:'Uma pergunta por degrau', col:'#FFD700', diff:'Show', qs, spare };
}

function startMilhao() {
  isMil = true; isDaily = false; isSurv = false; isRev = false;
  diffKey = 'moderado';                  // only used for the score multiplier
  /* seeded, so the climb can be sent to a friend as a challenge (js/desafio.js) */
  runSeed = chalSeed('m');
  seedFrom(runSeed);
  cat = buildMilhao();
  rung = 0; banked = 0; cashed = false;
  qi = 0; sel.clear(); pts = 0; prevPts = 0; streak = 0;
  nCorrect = 0; nPartial = 0; bestStreak = 0; lastGain = 0; runLog = []; runNew = 0; runNewIds = []; runPulls = []; runSelos = []; runPackOpened = false; gameN++;
  resetLifes();
  sc = 'quiz'; tMax = qTime(); tLeft = tMax; lastMsg = '';
  disp = dealDisp(0);
  startTmr();
  go();
}

/* PARAR — take the money on the table and stop. Always a win. */
function cashOut() {
  if (!isMil || sc !== 'quiz') return;
  clearInterval(tmr);
  cashed = true;
  banked = rung > 0 ? LADDER[rung - 1].v : 0;
  snd.cash();
  finishRun();
  go();
}

function milBest() { return LS.get('milBest', 0); }

/* ═══════════════════════════════════════════════════
   HELPERS
═══════════════════════════════════════════════════ */

/*@@art@@*/
/* ═══════════════════════════════════════════════════
   ART — drawn, flat, and a little bit of an old schoolbook
   The vignettes a question can carry when it is not about a face, a crest
   or a flag. Screen-printed scenes in the album's inks — ochre, burgundy,
   verdigris, parchment — with the one heavy outline, no gradients, no gloss.
═══════════════════════════════════════════════════ */
const NUM = i => String((i || 0) + 1).padStart(2, '0');
