      const puff = (cs, c, o) => { const d = cs.map(([x, y, r]) => `<circle cx="${x}" cy="${y}" r="${r}"/>`).join(''); return `<g stroke="${o}" stroke-width="2">${d}</g><g fill="${c}">${d}</g>`; };
