        + `<g transform="translate(-13 -6)">` + SCH.g(`<path d="M30 84V14" fill="none" stroke="${SCK.wood}" stroke-width="2"/><path d="M18 16h24v18l-12 6-12-6z" fill="${SCK.red}"/><path d="M28 12h4v4h-4z" fill="${SCK.gold}" stroke-width="1"/>`, 1.4)
