      for (let x = 18; x <= 102; x += 12) { lights += `M${x - 2.4} 71a2.4 2 0 0 1 4.8 0z`; glow += `<circle cx="${x}" cy="70" r="4" fill="${SCK.goldHi}" opacity=".3"/>`; }
      const drape = `<path d="M12 3H34C31 18 26 30 21 40C25 47 23 56 25 64H12Z" fill="${SCK.red}"/>`;
