/* ═══════════════════════════════════════════════════
   O ATLAS — the album drawn as an old mapa-múndi
   The engraver's shop for the album's maps: the world in two hemispheres,
   a chart for each part of the world, and the little chart at the foot of
   a country's page. Drawn the way the atlases of the 1600s were: the coasts
   water-lined (the rings an engraver cut along every shore), the sea
   ruled with little waves, the borders dotted, the graticule and the
   tropics, rhumb lines out of a compass rose, ships and monsters at sea, a
   cartouche for the title — and the lands washed in watercolour by hand.
   Here the hand is the player's: a country is uncoloured engraving until
   its stickers are stuck, and the wash deepens with every one, to a full
   wash with a gilt edge when its page is complete.
   ALB_MAP (the maps' lines) and ATLAS_ART (the engraved pieces) are above.
═══════════════════════════════════════════════════ */
const ATL_INK = '#2E2116', ATL_INK2 = '#5B4A33';
/* the colourist's pots: rose madder, ochre, sap green, lilac, carmine, orange, gamboge (album_map.json's `ink` picks one per
   country). Nothing blue or blue-green: on a map such a land reads as water */
const ATL_WASH = ['#C47A66', '#D6A84F', '#8C9A44', '#9B82B6', '#C2606F', '#D48745', '#D9C060'];
let _atlN = 0;
const _f = v => (Math.round(v * 100) / 100).toString();

/* ── what every map shares ──
   A drawing is drawn in its own map units; X = { u: the prefix of its ids, k: how many map units make a pixel,
   ve: true when the map is stretched unevenly (a page's little chart), so its lines are drawn in pixels instead } */
const _sw = (X, px) => `stroke-width="${_f(X.ve ? px : px * X.k)}"${X.ve ? ' vector-effect="non-scaling-stroke"' : ''}`;
const _ve = X => X.ve ? ' vector-effect="non-scaling-stroke"' : '';
/* the patterns and the hill, in map units */
function _atlDefs(X) {
  const { u } = X, K = v => _f(v * X.k);
  return `
  <pattern id="${u}-wave" width="${K(30)}" height="${K(17)}" patternUnits="userSpaceOnUse">
    <path d="M${K(2)} ${K(5)}q${K(2.2)} ${K(-2)} ${K(4.4)} 0t${K(4.4)} 0M${K(17)} ${K(13.5)}q${K(2.2)} ${K(-2)} ${K(4.4)} 0t${K(4.4)} 0"
      fill="none" stroke="${ATL_INK2}" stroke-width="${K(.5)}" stroke-linecap="round" opacity=".5"/></pattern>
  <pattern id="${u}-hatch" width="${K(3.2)}" height="${K(3.2)}" patternUnits="userSpaceOnUse" patternTransform="rotate(-45)">
    <path d="M0 0V${K(3.2)}" stroke="${ATL_INK2}" stroke-width="${K(.45)}" opacity=".32"/></pattern>
  <symbol id="${u}-hill" viewBox="-6 -5 12 6" overflow="visible">
    <path d="M-5.6 0C-3.6-.6-1.6-4.6 0-4.6S3.6-.6 5.6 0" fill="#F3E8CB" fill-opacity=".85" stroke="${ATL_INK}" stroke-width=".55" stroke-linecap="round"/>
    <path d="M.6-3.6L1.3-.3M1.7-2.9L2.6-.3M2.8-2L3.7-.3M3.9-1.2L4.6-.2" stroke="${ATL_INK}" stroke-width=".38" stroke-linecap="round"/></symbol>`;
}
/* the land's outline and the album's countries, once, for everything else to refer to */
function _atlShapes(X, land, shapes, cs) {
  const { u } = X;
  return `<path id="${u}-land" d="${land}"${_ve(X)}/>` + cs.filter(c => shapes[c])
    .map(c => `<path id="${u}-s-${c}" d="${shapes[c]}"${_ve(X)}/><clipPath id="${u}-k-${c}"><use href="#${u}-s-${c}"/></clipPath>`).join('');
}
/* the rings an engraver cut along every coast, fading out to sea: a mask of
   nested strokes of the land's outline, each cut back by a thinner one */
/* the rings for a map's scale: fewer and closer where the coasts are drawn small */
const ATL_RINGS = { world: [[6.4, .26], [4.4, .48], [2.7, .72], [1.3, 1]], chart: [[7.4, .22], [5.1, .4], [3.1, .64], [1.5, .95]], inset: [[4.6, .3], [2.9, .55], [1.4, .9]] };
function _atlCoast(X, box) {
  const { u } = X, rings = ATL_RINGS[X.rings || 'chart'];
  let m = '';
  for (const [o, a] of rings) {
    const g = Math.round(a * 255);
    m += `<use href="#${u}-land" fill="none" stroke="rgb(${g},${g},${g})" ${_sw(X, 2 * o)} stroke-linejoin="round"/>`
       + `<use href="#${u}-land" fill="none" stroke="#000" ${_sw(X, 2 * (o - .6))} stroke-linejoin="round"/>`;
  }
  const [x, y, w, h] = box.map(_f);
  return `<mask id="${u}-coast" maskUnits="userSpaceOnUse" x="${x}" y="${y}" width="${w}" height="${h}">
    <rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#000"/>${m}<use href="#${u}-land" fill="#000"/></mask>`;
}
/* the sea: a cool wash over the paper, ruled with little waves, the coasts water-lined */
function _atlSea(X, box) {
  const { u } = X, [x, y, w, h] = box.map(_f), r = `x="${x}" y="${y}" width="${w}" height="${h}"`;
  return `<rect ${r} fill="#8FA89A" fill-opacity=".26"/><rect ${r} fill="url(#${u}-wave)"/>
    <rect ${r} fill="${ATL_INK}" fill-opacity=".85" mask="url(#${u}-coast)"/>`;
}
/* thirty-two rhumb lines out of a rose, as on a portolan chart: the eight winds in ink, the half-winds green, the quarter-winds red */
function _atlRhumbs(X, cx, cy, len) {
  let a = '', b = '', c = '';
  for (let i = 0; i < 32; i++) {
    const t = i / 32 * Math.PI * 2, seg = `M${_f(cx)} ${_f(cy)}L${_f(cx + Math.cos(t) * len)} ${_f(cy + Math.sin(t) * len)}`;
    if (i % 4 === 0) a += seg; else if (i % 2 === 0) b += seg; else c += seg;
  }
  return `<g fill="none"><path d="${a}" stroke="${ATL_INK}" stroke-opacity=".34" ${_sw(X, .55)}/>
    <path d="${b}" stroke="#4E7F62" stroke-opacity=".38" ${_sw(X, .55)}/><path d="${c}" stroke="#A8442E" stroke-opacity=".3" ${_sw(X, .55)}/></g>`;
}
/* the graticule, the tropics dashed and the equator ruled black and white like a scale */
function _atlGrat(X, o) {
  const L = o.lines || {}, K = v => _f(v * (X.ve ? 1 : X.k)), circles = (L.tropN || '') + (L.tropS || '') + (L.polN || '') + (L.polS || '');
  return `<path d="${o.grat}" fill="none" stroke="${ATL_INK2}" ${_sw(X, .45)} stroke-opacity=".34"/>
    ${circles ? `<path d="${circles}" fill="none" stroke="${ATL_INK2}" ${_sw(X, .7)} stroke-opacity=".5" stroke-dasharray="${K(4)} ${K(2.5)}"/>` : ''}
    ${L.eq ? `<path d="${L.eq}" fill="none" stroke="${ATL_INK}" ${_sw(X, 2.6)} stroke-opacity=".55"/>
      <path d="${L.eq}" fill="none" stroke="#F1E5C4" ${_sw(X, 1.5)} stroke-dasharray="${K(5)} ${K(5)}"/>` : ''}`;
}
/* the lands: paper a shade lighter than the sea, and hills where the mountains are */
function _atlLand(X, hills, hs, gilt) {
  const { u, k } = X, h = (hs || 1) * 12;
  return `<use href="#${u}-land" fill="${gilt ? '#EBD39A' : '#FBF3DC'}" fill-opacity="${gilt ? '.7' : '.62'}"/>` + (hills || []).map(([x, y, s]) =>
    `<use href="#${u}-hill" x="${_f(x - h / 2 * s * k)}" y="${_f(y - h * 5 / 12 * s * k)}" width="${_f(h * s * k)}" height="${_f(h / 2 * s * k)}"/>`).join('');
}
/* a country washed by how much of it is in the album: none is the engraving's own hatching,
   some is a thin wash with its border coloured deeper (the colourist's way), all is a full wash with a gilt edge */
function _atlWash(X, c, f, fresh) {
  const { u } = X, id = `${u}-s-${c}`, col = ATL_WASH[(ALB_MAP.ink || {})[c] || 0];
  if (f <= 0) return `<use href="#${id}" fill="url(#${u}-hatch)" class="atl-c" data-place="${c}"/>`;
  /* a great state was coloured along its borders and only lightly within, or it would flood the sheet */
  const a = (ALB_MAP.area || {})[c] || 0, big = a > .1 ? .4 : a > .03 ? .6 : 1;
  return `<g class="atl-c${fresh ? ' is-fresh' : ''}${f >= 1 ? ' is-done' : ''}" data-place="${c}">
    <use href="#${id}" fill="${col}" fill-opacity="${_f((.12 + .34 * f) * big)}" class="atl-wash"/>
    <use href="#${id}" fill="none" stroke="${col}" ${_sw(X, 5.5)} stroke-opacity="${_f(.42 + .5 * f)}" clip-path="url(#${u}-k-${c})"/>
    ${f >= 1 ? `<use href="#${id}" fill="none" stroke="#A97A22" ${_sw(X, 1.3)} stroke-opacity=".9"/>` : ''}</g>`;
}
/* the borders dotted, the coast a firm line */
function _atlLines(X, borders) {
  const K = v => _f(v * (X.ve ? 1 : X.k));
  return `<path d="${borders}" fill="none" stroke="${ATL_INK}" ${_sw(X, 1)} stroke-opacity=".7" stroke-linecap="round" stroke-dasharray="${K(.05)} ${K(2.1)}"/>
    <use href="#${X.u}-land" fill="none" stroke="${ATL_INK}" ${_sw(X, .95)} stroke-linejoin="round" stroke-opacity=".92"/>`;
}
/* the lettering: the seas in italic, the parts of the world in spaced capitals, with a halo of paper */
function _atlLabels(X, labels) {
  return (labels || []).map(([t, x, y, size, kind, rot]) => {
    const s = size * X.k * (X.ls || 1), big = kind === 'big';
    return `<text x="${_f(x)}" y="${_f(y)}"${rot ? ` transform="rotate(${_f(rot)} ${_f(x)} ${_f(y)})"` : ''} font-size="${_f(s)}"
      class="atl-t atl-t-${kind}" letter-spacing="${_f(s * (big ? .42 : kind === 'land' ? .18 : .06))}" stroke-width="${_f(2.2 * X.k * (X.ls || 1))}">${_esc(t)}</text>`;
  }).join('');
}
/* an engraved piece, centred on x, y, `w` map units wide */
function _atlPiece(n, x, y, w, flip) {
  const a = ATLAS_ART[n];
  if (!a) return '';
  const [vx, vy, vw, vh] = a.vb.split(/\s+/).map(Number), h = w * vh / vw;
  return `<svg x="${_f(x - w / 2)}" y="${_f(y - h / 2)}" width="${_f(w)}" height="${_f(h)}" viewBox="${a.vb}" overflow="visible" class="atl-p atl-p-${n}">${
    flip ? `<g transform="matrix(-1 0 0 1 ${_f(2 * vx + vw)} 0)">${a.svg}</g>` : a.svg}</svg>`;
}
/* the cartouche with its title */
function _atlCartouche(x, y, w, title, sub) {
  const a = ATLAS_ART.cartela;
  if (!a) return '';
  const [, , vw, vh] = a.vb.split(/\s+/).map(Number), s = w / vw, h = vh * s;
  const [bx, by, bw, bh] = a.box || [46, 26, 148, 60];
  const tx = x - w / 2 + (bx + bw / 2) * s, ty = y - h / 2 + (by + bh / 2) * s;
  const fs = Math.min(bh * s * (sub ? .4 : .5), bw * s / (title.length * .46));
  const ss = Math.min(bh * s * .19, bw * s * .92 / (sub ? sub.length * .48 : 1));
  const two = sub && ss >= 8.5;
  return `${_atlPiece('cartela', x, y, w)}
    <text x="${_f(tx)}" y="${_f(two ? ty - bh * s * .12 : ty)}" font-size="${_f(fs)}" class="atl-t atl-title">${_esc(title)}</text>
    ${two ? `<text x="${_f(tx)}" y="${_f(ty + bh * s * .27)}" font-size="${_f(ss)}" class="atl-t atl-sub">${_esc(sub)}</text>` : ''}`;
}
/* the neatline round a sheet: a double rule with a band ruled black and white between */
function _atlNeat(X, x, y, w, h) {
  const k = X.k, b = 5 * k, r = (i, sw) => `<rect x="${_f(x + i)}" y="${_f(y + i)}" width="${_f(w - 2 * i)}" height="${_f(h - 2 * i)}" stroke-width="${_f(sw)}"`;
  return `<g fill="none">${r(b / 2, b)} stroke="#F1E5C4" stroke-opacity=".85"/>
    ${r(b / 2, b * .5)} stroke="${ATL_INK}" stroke-opacity=".55" stroke-dasharray="${_f(.6 * k)} ${_f(3.4 * k)}"/>
    ${r(.6 * k, 1.2 * k)} stroke="${ATL_INK}"/>${r(b, .6 * k)} stroke="${ATL_INK}"/></g>`;
}
const _atlFill = c => { const a = placeAll(c); return a ? placeGot(c) / a : 0; };

/* ── the world, in two hemispheres, on a sheet W × H px ── */
function atlasWorld(W, H, fresh) {
  const u = 'atw' + (++_atlN), M = ALB_MAP.hemi, cs = albPlaces().order;
  const fr = 9, ins = fr + 6, iw = W - 2 * ins, ih = H - 2 * ins;
  const dRow = Math.min(iw / 2, ih), dCol = Math.min(iw, ih / 2);
  const row = dRow >= dCol, D = Math.max(dRow, dCol) * .985, Rt = D / 2, band = Math.max(5, Rt * .065), R = Rt - band;
  const cx = ins + iw / 2, cy = ins + ih / 2;
  const C = { W: row ? [cx - Rt, cy] : [cx, cy - Rt], E: row ? [cx + Rt, cy] : [cx, cy + Rt] };
  const sc = R / M.r, kk = 1 / sc, bu = band / sc, rr = M.r + bu / 2;
  let defs = '', body = '';
  for (const h of ['W', 'E']) {
    const o = M[h], [hx, hy] = C[h], X = { u: u + h, k: kk, rings: 'world', ls: Math.max(.72, Math.min(1, R / 170)) };
    defs += _atlDefs(X) + _atlShapes(X, o.land, o.shapes, cs) + _atlCoast(X, [-M.r, -M.r, 2 * M.r, 2 * M.r])
         + `<clipPath id="${X.u}-disc"><circle r="${M.r}"/></clipPath>`;
    const rose = o.deco.find(d => d[0] === 'rosa');
    body += `<g transform="translate(${_f(hx)} ${_f(hy)}) scale(${_f(sc)})" class="atl-hemi" data-hemi="${h}">
      <g clip-path="url(#${X.u}-disc)">
        ${_atlSea(X, [-M.r, -M.r, 2 * M.r, 2 * M.r])}
        ${rose ? _atlRhumbs(X, rose[1], rose[2], M.r * 2.2) : ''}
        ${_atlGrat(X, o)}
        ${_atlLand(X, o.hills, .8, cs.every(c => _atlFill(c) >= 1))}
        ${Object.keys(o.shapes).filter(c => cs.includes(c)).map(c => _atlWash(X, c, _atlFill(c), fresh.has(c))).join('')}
        ${_atlLines(X, o.borders)}
        ${o.deco.map(([n, x, y, f]) => _atlPiece(n, x, y, f * 2 * M.r * (n === 'rosa' ? .9 : 1), n === 'caravela' && h === 'W')).join('')}
        ${_atlLabels(X, o.labels)}
      </g>
      <circle r="${_f(rr)}" fill="none" stroke="#F1E5C4" stroke-width="${_f(bu)}"/>
      <circle r="${_f(M.r + bu * .72)}" fill="none" stroke="${ATL_INK}" stroke-width="${_f(bu * .3)}" stroke-dasharray="${_f(Math.PI * 2 * (M.r + bu * .72) / 72)}"/>
      <circle r="${_f(M.r + bu * .57)}" fill="none" stroke="${ATL_INK}" stroke-width="${_f(kk * .4)}"/>
      <circle r="${_f(M.r + bu * .28)}" fill="none" stroke="${ATL_INK}" stroke-width="${_f(bu * .3)}" stroke-opacity=".7" stroke-dasharray="${_f(kk * .45)} ${_f(Math.PI * 2 * (M.r + bu * .28) / 180 - kk * .45)}"/>
      <circle r="${M.r}" fill="none" stroke="${ATL_INK}" stroke-width="${_f(kk * .9)}"/>
      <circle r="${_f(M.r + bu)}" fill="none" stroke="${ATL_INK}" stroke-width="${_f(kk * 1.3)}"/>
    </g>`;
  }
  /* the title over the meeting of the two worlds, the armillary sphere where there is room */
  const cw = Math.min(row ? Rt * 1.2 : D * .64, 260), ch = cw * .46;
  const tY = row ? Math.max(ins + ch / 2 + 2, cy - Rt * .84) : cy;
  const title = _atlCartouche(cx, tY, cw, 'Mapa-Múndi', 'nova e exata descrição de toda a Terra');
  const side = row ? 0 : (iw - D) / 2;
  const sph = row ? _atlPiece('esfera', cx, Math.min(H - ins - Rt * .3, cy + Rt * .72), Rt * .44)
            : side > 54 ? _atlPiece('esfera', ins + side / 2, cy - Rt * 1.3, Math.min(70, side * .82))
            : _atlPiece('esfera', cx - Rt * .9, cy - Rt * 1.78, Rt * .34);
  const rose2 = !row && side > 54 ? _atlPiece('rosa', W - ins - side / 2, cy + Rt * 1.3, Math.min(64, side * .8)) : '';
  return { row, C, R, sc,
    svg: `<svg class="atl-svg" viewBox="0 0 ${_f(W)} ${_f(H)}" width="${_f(W)}" height="${_f(H)}" aria-hidden="true">
      <defs>${defs}</defs>${body}${sph}${rose2}${title}${_atlNeat({ k: 1 }, 0, 0, W, H)}</svg>` };
}

/* ── a part of the world, on a sheet W × H px: the chart widens or heightens to fill it ── */
const ATL_CHART_TITLE = { EU: 'Europa', AS: 'Ásia', AF: 'África', AM: 'América' };
/* Is this spot of a chart at sea? The land's outline, read once from its path (d3 writes only M, L and Z),
   and an even-odd test against all its rings */
const _atlRings = {};
function _atlAtSea(key, x, y) {
  const rings = _atlRings[key] || (_atlRings[key] = ALB_MAP.charts[key].land.split('M').filter(Boolean).map(r =>
    r.replace(/Z/g, '').split('L').map(q => q.split(',').map(Number))));
  let inside = false;
  for (const ring of rings) for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i], [xj, yj] = ring[j];
    if ((yi > y) !== (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) inside = !inside;
  }
  return !inside;
}
function atlasChart(key, W, H, fresh) {
  const o = ALB_MAP.charts[key], u = 'atc' + (++_atlN);
  const [cx0, cy0, cw, ch] = o.core, [ex, ey, ew, eh] = o.ext, A = W / H;
  const cs = albPlaces().order, own = Object.entries(o.pins).filter(([c]) => cs.includes(c));
  let vw = cw * 1.04, vh = ch * 1.04;
  if (vw / vh < A) vw = vh * A; else vh = vw / A;
  if (vw > ew) { vw = ew; vh = vw / A; }
  if (vh > eh) { vh = eh; vw = vh * A; }
  /* centred on the pins, as far as the whole part of the world still fits */
  const qx = own.map(([, q]) => q[0]), qy = own.map(([, q]) => q[1]);
  let vx = (own.length ? (Math.min(...qx) + Math.max(...qx)) / 2 : cx0 + cw / 2) - vw / 2;
  let vy = (own.length ? (Math.min(...qy) + Math.max(...qy)) / 2 : cy0 + ch / 2) - vh / 2;
  if (vw >= cw) vx = Math.min(cx0, Math.max(cx0 + cw - vw, vx));
  if (vh >= ch) vy = Math.min(cy0, Math.max(cy0 + ch - vh, vy));
  vx = Math.max(ex, Math.min(ex + ew - vw, vx)); vy = Math.max(ey, Math.min(ey + eh - vh, vy));
  const s = W / vw, X = { u, k: 1 / s }, k = X.k, box = [vx, vy, vw, vh];
  const pins = _amapSpread(own.map(([c, [x, y]]) => ({ c, x: (x - vx) * s, y: (y - vy) * s })), W, H, 31);
  /* everything that is lettered or drawn claims its room, in pixels: the pins first, then the scale,
     the cartouche, the pieces and the names, each only where nothing is yet */
  const taken = pins.map(p => [p.x, p.y, 17, 17]);
  const hit = (bx, by, hw, hh) => taken.some(([ax, ay, aw, ah]) => Math.abs(ax - bx) < aw + hw && Math.abs(ay - by) < ah + hh);
  const fits = (bx, by, hw, hh) => bx - hw > 9 && bx + hw < W - 9 && by - hh > 9 && by + hh < H - 9;
  const lg = o.deg / 17.5, bar = 100 * lg * s;                 // a hundred Portuguese leagues, 17½ to a degree, in px
  const showScale = bar < W * .42 && bar > 30;
  if (showScale) taken.push([16 + bar / 2, H - 24, bar / 2 + 6, 13]);
  const cwPx = Math.min(W * .5, 210), chPx = cwPx * .46;
  let cart = null;
  /* a stretch of open sea for a w × h px piece: the chart's own spots first, then anywhere on the sheet, nearest the edges first */
  const seaFor = (spots, hw, hh) => {
    const sea = (bx, by) => { let n = 0, t = 0;
      for (let i = -2; i <= 2; i++) for (let j = -1; j <= 1; j++) { t++; if (_atlAtSea(key, vx + (bx + i * hw / 2) * k, vy + (by + j * hh) * k)) n++; }
      return n / t >= .8; };
    const scan = [];
    for (let j = 0; j < 9; j++) for (let i = 0; i < 5; i++) scan.push([hw + 10 + (W - 2 * hw - 20) * i / 4, hh + 10 + (H - 2 * hh - 20) * (j % 2 ? 8 - (j >> 1) : j >> 1) / 8]);
    for (const [bx, by] of spots.map(([x, y]) => [(x - vx) * s, (y - vy) * s]).concat(scan))
      if (fits(bx, by, hw, hh) && !hit(bx, by, hw + 4, hh + 4) && sea(bx, by)) return [bx, by];
    return null;
  };
  let cartW = cwPx;
  for (const f of [1, .84, .7]) {
    cartW = Math.max(118, cwPx * f);
    if ((cart = seaFor(o.cart || [], cartW / 2, cartW * .23))) break;
  }
  if (cart) taken.push([cart[0], cart[1], cartW / 2, cartW * .23]);
  const deco = [];
  for (const d of o.deco) {
    const [n, x, y, f] = d, bx = (x - vx) * s, by = (y - vy) * s, r = f * W / 2;
    const hw = r * .8, hh = r * (n === 'rosa' ? .8 : .5);
    if (deco.some(e => e[0] === n) || !fits(bx, by, hw, hh) || hit(bx, by, hw, hh)) continue;
    deco.push(d); taken.push([bx, by, hw, hh]);
  }
  if (!deco.some(d => d[0] === 'rosa')) {
    const r = Math.min(W, H) * .085, at = seaFor([], r, r);
    if (at) { deco.push(['rosa', vx + at[0] * k, vy + at[1] * k, r * 2 / .9 / W]); taken.push([at[0], at[1], r, r]); }
  }
  const rose = deco.find(d => d[0] === 'rosa');
  /* a sea's or a land's name never sits under a pin, a piece or the frame; the cartouche names the part of the world itself */
  const labels = [];
  for (const [t, x, y, size, kind, rot] of o.labels) {
    if (cart && kind === 'big') continue;
    const bx = (x - vx) * s, by = (y - vy) * s, hw = t.length * size * (kind === 'big' ? .62 : .3) + 5, hh = size * .6 + 4;
    /* where it is meant to go, or a little above, below or to either side, if that is clear */
    const at = [[0, 0], [0, hh * 1.7], [0, -hh * 1.7], [hw * .5, 0], [-hw * .5, 0], [0, hh * 3]].find(([dx, dy]) =>
      fits(bx + dx, by + dy, hw, hh) && !hit(bx + dx, by + dy, hw, hh));
    if (!at) continue;
    taken.push([bx + at[0], by + at[1], hw, hh]);
    labels.push([t, x + at[0] * k, y + at[1] * k, size, kind, rot]);
  }
  const defs = _atlDefs(X) + _atlShapes(X, o.land, o.shapes, cs) + _atlCoast(X, box)
    + `<clipPath id="${u}-frame"><rect x="${_f(vx)}" y="${_f(vy)}" width="${_f(vw)}" height="${_f(vh)}"/></clipPath>`;
  const bu = bar * k, bx = vx + 16 * k, by = vy + vh - 20 * k;
  const scale = showScale ? `<g class="atl-scale"><rect x="${_f(bx - 5 * k)}" y="${_f(by - 14 * k)}" width="${_f(bu + 10 * k)}" height="${_f(21 * k)}" fill="#F4EBD2" fill-opacity=".75" stroke="${ATL_INK}" stroke-width="${_f(.6 * k)}"/>
    ${[0, 1, 2, 3, 4].map(i => `<rect x="${_f(bx + i * bu / 5)}" y="${_f(by)}" width="${_f(bu / 5)}" height="${_f(3 * k)}" fill="${i % 2 ? '#F1E5C4' : ATL_INK}" stroke="${ATL_INK}" stroke-width="${_f(.5 * k)}"/>`).join('')}
    <text x="${_f(bx + bu / 2)}" y="${_f(by - 4 * k)}" font-size="${_f(8 * k)}" class="atl-t atl-t-sea">100 léguas</text></g>` : '';
  const done = own.length && own.every(([c]) => _atlFill(c) >= 1);
  const svg = `<svg class="atl-svg" viewBox="${_f(vx)} ${_f(vy)} ${_f(vw)} ${_f(vh)}" width="${_f(W)}" height="${_f(H)}" aria-hidden="true">
    <defs>${defs}</defs>
    <g clip-path="url(#${u}-frame)">
      ${_atlSea(X, box)}
      ${rose ? _atlRhumbs(X, rose[1], rose[2], Math.hypot(vw, vh)) : ''}
      ${_atlGrat(X, o)}
      ${_atlLand(X, o.hills, 1, done)}
      ${Object.keys(o.shapes).filter(c => cs.includes(c)).map(c => _atlWash(X, c, _atlFill(c), fresh.has(c))).join('')}
      ${_atlLines(X, o.borders)}
      ${deco.map(([n, x, y, f]) => _atlPiece(n, x, y, f * vw * (n === 'rosa' ? .9 : 1), false)).join('')}
      ${_atlLabels(X, labels)}
      ${scale}
      ${cart ? _atlCartouche(vx + cart[0] * k, vy + cart[1] * k, cartW * k, ATL_CHART_TITLE[key], 'nova e exata descrição') : ''}
    </g>
    ${_atlNeat(X, vx, vy, vw, vh)}</svg>`;
  return { svg, pins, s, box };
}

/* ── the little chart at the foot of a country's page: where it is, its neighbours round it ── */
function atlasInset(c, W, H, plateW) {
  const M = ALB_MAP, X = { u: 'ati' + (++_atlN), ve: true, rings: 'inset' };
  const [x0, y0, x1, y1] = M.bbox[c] || [0, 0, 360, 134];
  const p = M.pins[c] || [(x0 + x1) / 2, (y0 + y1) / 2];
  const lat = 78 - (y0 + y1) / 2;
  /* an equirectangular map squashes the north: drawn here as tall as an atlas would print it */
  const st = Math.min(1.7, 1 / Math.cos(Math.max(-70, Math.min(70, lat)) * Math.PI / 180));
  let vw = Math.max(14, (x1 - x0) * 1.8), vh = Math.max(7, (y1 - y0) * 1.8);
  const A = W / H * st;                     // the room's shape in map units
  if (vw / vh < A) vw = vh * A; else vh = vw / A;
  if (vw > 360) { vw = 360; vh = vw / A; }
  /* the page's name plate takes a corner of the chart: the country is set off to the other side of it, in the middle
     of the room the plate leaves; where there is too little room the plate gives way (the page's title names it) */
  const pw = (plateW || 150) + 16, tall = H > W * .8 && H > 150;
  const plate = tall ? 'bottom' : W - pw >= 70 ? 'left' : 'none';
  const fx = plate === 'left' ? (pw + (W - pw) / 2) / W : .5, fy = tall ? .4 : .5;
  const vx = Math.max(0, Math.min(360 - vw, p[0] - vw * fx)), vy = Math.max(-25, Math.min(159 - vh, p[1] - vh * fy));
  X.k = vw / W;
  const box = [vx, vy, vw, vh];
  /* the graticule, every five degrees */
  let g = '';
  for (let lo = Math.ceil((vx - 170) / 5) * 5; lo + 170 <= vx + vw; lo += 5) g += `M${lo + 170} ${_f(vy)}V${_f(vy + vh)}`;
  for (let la = Math.ceil((78 - vy - vh) / 5) * 5; 78 - la >= vy; la += 5) g += `M${_f(vx)} ${78 - la}H${_f(vx + vw)}`;
  const o = { grat: g, lines: {} };
  if (vy < 78 && vy + vh > 78) o.lines.eq = `M${_f(vx)} 78H${_f(vx + vw)}`;
  const near = Object.keys(M.shapes).filter(n => { const b = M.bbox[n]; return b && b[2] > vx && b[0] < vx + vw && b[3] > vy && b[1] < vy + vh; });
  if (M.shapes[c] && !near.includes(c)) near.push(c);
  const col = ATL_WASH[(M.ink || {})[c] || 0], f = _atlFill(c), u = X.u;
  const pc = q => [(q[0] - vx) / vw * 100, (q[1] - vy) / vh * 100];
  const pin = pc(p);
  const svg = `<svg class="atl-svg" viewBox="${_f(vx)} ${_f(vy)} ${_f(vw)} ${_f(vh)}" width="${_f(W)}" height="${_f(H)}" preserveAspectRatio="none" aria-hidden="true">
    <defs>${_atlDefs(X)}${_atlShapes(X, M.land, M.shapes, near)}${_atlCoast(X, box)}</defs>
    ${_atlSea(X, box)}
    ${_atlGrat(X, o)}
    ${_atlLand(X, (M.hills || []).filter(([x, y]) => x > vx && x < vx + vw && y > vy && y < vy + vh), .8)}
    ${near.filter(n => n !== c).map(n => _atlFill(n) > 0 ? `<use href="#${u}-s-${n}" fill="${ATL_WASH[(M.ink || {})[n] || 0]}" fill-opacity=".16"/>` : '').join('')}
    ${M.shapes[c] ? (f > 0 ? `<use href="#${u}-s-${c}" fill="${col}" fill-opacity="${_f(.3 + .45 * f)}"/>
      <use href="#${u}-s-${c}" fill="none" stroke="${col}" ${_sw(X, 5)} stroke-opacity=".85" clip-path="url(#${u}-k-${c})"/>`
      : `<use href="#${u}-s-${c}" fill="url(#${u}-hatch)"/>`)
      + `<use href="#${u}-s-${c}" fill="none" stroke="${f > 0 ? '#A97A22' : ATL_INK}" ${_sw(X, f > 0 ? 1.4 : 1.1)}/>` : ''}
    ${_atlLines(X, M.borders)}
    </svg>`;
  /* the lettering, in pixels: the neighbours by size, then the seas, none on another, on the pin or under the plate */
  const pr = plate === 'bottom' ? [W / 2, H - 25, pw / 2, 25] : plate === 'left' ? [pw / 2, H - 25, pw / 2, 25] : [-99, -99, 0, 0];
  const taken = [pr, [pin[0] * W / 100, pin[1] * H / 100, 13, 13], [W - 22, 22, 20, 20]];
  const keep = (list, size, max, wide) => list.filter(([t, x, y]) => {
    const bx = x * W / 100, by = y * H / 100, hw = t.length * size * wide + 4, hh = size * .7;
    if (bx - hw < 5 || bx + hw > W - 5 || by - hh < 5 || by + hh > H - 5) return false;
    if (taken.some(([ax, ay, aw, ah]) => Math.abs(ax - bx) < aw + hw && Math.abs(ay - by) < ah + hh)) return false;
    taken.push([bx, by, hw, hh]);
    return true;
  }).slice(0, max);
  const [bx0, by0, bx1, by1] = M.bbox[c] || [0, 0, 0, 0];
  const own = (x, y) => x > bx0 && x < bx1 && y > by0 && y < by1;
  const names = (M.names || []).filter(([t, x, y]) => x > vx && x < vx + vw && y > vy && y < vy + vh && !own(x, y) && t !== placeName(c))
    .sort((a, b) => b[3] - a[3]).map(([t, x, y]) => [t, ...pc([x, y])]);
  const seas = (M.labels || []).map(([t, x, y]) => [t, ...pc([x, y])]);
  /* where it lies, as an old chart would say it: degrees north or south, east (leste) or west (oeste) */
  const la = Math.round(78 - p[1]), lo = Math.round(p[0] - 170);
  const coord = `${Math.abs(la)}° ${la >= 0 ? 'N' : 'S'} · ${Math.abs(lo)}° ${lo >= 0 ? 'L' : 'O'}`;
  return { svg, pin, plate, coord, names: keep(names, 9.5, 4, .38), seas: keep(seas, 11, 2, .3) };
}

/* ═══════════════════════════════════════════════════
   O MAPA-MÚNDI — the album is a map of the world
   Every sticker lives somewhere: a figure in the country they were born
   in, a state's brasão where its seat was, a monument where it stands, a
   nation's flag in that nation. The album opens on an old mapa-múndi in
   two hemispheres (js/atlas.js draws it), each country an uncoloured
   engraving until its stickers come, and washed in watercolour as they
   do; a tap on a country opens the chart of its part of the world, where
   each country's pin opens its page of pockets (the album's own: flip,
   zoom, copies), with the country's own little chart at the foot of it.
   ALB_MAP (tools/history/album_map.json, from tools/history/albmapgen.mjs)
   is above this line.
═══════════════════════════════════════════════════ */
const AMAP_CONT = [['EU', 'Europa'], ['AS', 'Ásia'], ['AF', 'África e Oriente Médio'], ['AM', 'Américas']];
const AMAP_TAB = { EU: 'Europa', AS: 'Ásia', AF: 'África', AM: 'Américas' };
const AMAP_PLACE_CONT = {
  POR: 'EU', ESP: 'EU', FRA: 'EU', NED: 'EU', BEL: 'EU', GER: 'EU', ENG: 'EU', SCO: 'EU', IRL: 'EU', ITA: 'EU', CHE: 'EU',
  AUT: 'EU', CZE: 'EU', POL: 'EU', HUN: 'EU', DEN: 'EU', NOR: 'EU', SWE: 'EU', SRB: 'EU', CRO: 'EU', MKD: 'EU', GRC: 'EU',
  BUL: 'EU', UKR: 'EU', RUS: 'EU', VAT: 'EU',
  TUR: 'EU',
  IND: 'AS', NPL: 'AS', CHN: 'AS', MNG: 'AS', JPN: 'AS', VNM: 'AS', UZB: 'AS', KHM: 'AS',
  EGY: 'AF', TUN: 'AF', MAR: 'AF', MLI: 'AF', ETH: 'AF', AGO: 'AF', ZAF: 'AF',
  ISR: 'AF', SYR: 'AF', JOR: 'AF', IRQ: 'AF', IRN: 'AF',
  USA: 'AM', MEX: 'AM', CUB: 'AM', HAI: 'AM', VEN: 'AM', COL: 'AM', PER: 'AM', CHI: 'AM', URU: 'AM', PAR: 'AM', ARG: 'AM', BRA: 'AM',
};
/* the places with no figure of their own: only a state or a monument stands there */
const AMAP_EXTRA = { SYR: 'Síria', KHM: 'Camboja', SWE: 'Suécia', JOR: 'Jordânia', VAT: 'Vaticano' };
/* where each state had its seat */
const POLITY_AT = {
  egito_antigo: 'EGY', babilonia: 'IRQ', assiria: 'IRQ', persia: 'IRN', israel_antigo: 'ISR', atenas: 'GRC', esparta: 'GRC',
  macedonia: 'GRC', cartago: 'TUN', republica_romana: 'ITA', imperio_romano: 'ITA', bizancio: 'TUR', hunos: 'HUN', han: 'CHN',
  maurya: 'IND', axum: 'ETH', maia: 'MEX', francos: 'FRA', sacro_imperio: 'GER', califado_omiada: 'SYR', califado_abassida: 'IRQ',
  tang: 'CHN', imperio_mongol: 'MNG', ming: 'CHN', qing: 'CHN', khmer: 'KHM', mali: 'MLI', songai: 'MLI', inglaterra: 'ENG',
  francia: 'FRA', republica_florentina: 'ITA', veneza: 'ITA', portugal: 'POR', espanha: 'ESP', imperio_otomano: 'TUR',
  safavida: 'IRN', mogol: 'IND', tokugawa: 'JPN', asteca: 'MEX', inca: 'PER', imperio_espanhol: 'ESP', imperio_portugues: 'POR',
  holanda: 'NED', suecia: 'SWE', prussia: 'GER', reino_unido: 'ENG', imperio_russo: 'RUS', austria_hungria: 'AUT',
  franca_revolucionaria: 'FRA', imperio_frances: 'FRA', estados_unidos: 'USA', haiti: 'HAI', gran_colombia: 'COL',
  imperio_britanico: 'ENG', imperio_brasil: 'BRA', brasil_colonia: 'BRA', brasil_republica: 'BRA', imperio_alemao: 'GER',
  imperio_japones: 'JPN', italia_fascista: 'ITA', alemanha_nazista: 'GER', urss: 'RUS', china_popular: 'CHN', india: 'IND',
  turquia: 'TUR', cuba: 'CUB', africa_do_sul: 'ZAF', dinastia_qin: 'CHN', ayubida: 'EGY',
};
/* where each monument stands */
const MONUMENT_AT = {
  coliseu: 'ITA', panteao: 'ITA', forum_romano: 'ITA', muralha_adriano: 'ENG', aqueduto_segovia: 'ESP', pompeia: 'ITA',
  partenon: 'GRC', piramide_queops: 'EGY', esfinge: 'EGY', abu_simbel: 'EGY', karnak: 'EGY', portao_ishtar: 'IRQ',
  persepolis: 'IRN', petra: 'JOR', muralha_china: 'CHN', cidade_proibida: 'CHN', taj_mahal: 'IND', angkor_wat: 'KHM',
  himeji: 'JPN', machu_picchu: 'PER', chichen_itza: 'MEX', moai: 'CHI', santa_sofia: 'TUR', mesquita_azul: 'TUR',
  alhambra: 'ESP', stonehenge: 'ENG', torre_londres: 'ENG', notre_dame: 'FRA', versalhes: 'FRA', arco_triunfo: 'FRA',
  torre_eiffel: 'FRA', escorial: 'ESP', torre_belem: 'POR', jeronimos: 'POR', duomo_florenca: 'ITA', torre_pisa: 'ITA',
  sao_pedro: 'VAT', sao_marcos: 'ITA', sagrada_familia: 'ESP', kremlin: 'RUS', palacio_inverno: 'RUS', brandemburgo: 'GER',
  muro_berlim: 'GER', estatua_liberdade: 'USA', capitolio: 'USA', monte_rushmore: 'USA', cristo_redentor: 'BRA',
  museu_ipiranga: 'BRA', ouro_preto: 'BRA', museu_imperial: 'BRA', catedral_brasilia: 'BRA',
};
/* the old album printed each country's name in all its languages across the band */
const AMAP_LANGS = {
  BRA: 'Brazil · Brasilien · Brésil · Brasile', ARG: 'Argentina · Argentinien · Argentine',
  ITA: 'Italy · Italien · Italie · Italia', GER: 'Germany · Deutschland · Allemagne',
  ENG: 'England · Angleterre · Inghilterra', FRA: 'France · Frankreich · Francia',
  ESP: 'Spain · Spanien · Espagne · Spagna', POR: 'Portugal · Portogallo',
  NED: 'Holland · Niederlande · Pays-Bas', URU: 'Uruguay',
  USA: 'United States · Vereinigte Staaten', GRC: 'Greece · Griechenland · Grèce · Grecia',
  RUS: 'Russia · Russland · Russie', EGY: 'Egypt · Ägypten · Égypte · Egitto',
  CHN: 'China · Chine · Cina', AUT: 'Austria · Österreich · Autriche',
  IRQ: 'Iraq · Irak', TUR: 'Turkey · Türkei · Turquie · Turchia',
  IRN: 'Iran · Irán', POL: 'Poland · Polen · Pologne · Polonia',
  JPN: 'Japan · Japon · Giappone', IND: 'India · Indien · Inde', MEX: 'Mexico · Mexiko · Mexique',
};
const placeName = c => CTRY_NAME[c] || AMAP_EXTRA[c] || c;

let albView = 'map';        // 'map' or 'place'
let amapView = 'WORLD';     // which part of the world the map shows

/* Every page of the album and what is in it, numbered as the album always
   numbered them: the figures first, then the brasões, the nations and the
   monuments. */
let _places = null;
function albPlaces() {
  if (_places) return _places;
  const items = {}, lost = [];
  const add = (c, it) => { if (!c || !ALB_MAP.pins[c]) { lost.push(it); return; } (items[c] = items[c] || []).push(it); };
  PL.forEach((p, i) => add(p.ctry, { p, n: i + 1 }));
  let nx = PL.length;
  ESCUDOS.forEach(id => add(POLITY_AT[id], { sid: SK.esc(id), n: ++nx }));
  SELECOES.forEach(c => add(c, { sid: SK.sel(c), n: ++nx }));
  MASCOTES.forEach(id => add(MONUMENT_AT[id], { sid: SK.msc(id), n: ++nx }));
  const order = Object.keys(items).sort((a, b) =>
    a === 'BRA' ? -1 : b === 'BRA' ? 1 : items[b].length - items[a].length || placeName(a).localeCompare(placeName(b), 'pt'));
  return (_places = { items, order, lost });
}
const _sidOf = g => g.sid || g.p.id;
const placeGot = c => (albPlaces().items[c] || []).filter(g => album.has(_sidOf(g))).length;
const placeAll = c => (albPlaces().items[c] || []).length;
/* the place a sticker belongs to */
function placeOf(sid) {
  const P = albPlaces();
  return P.order.find(c => P.items[c].some(g => _sidOf(g) === sid)) || null;
}

/* what a page of stickers that are not people holds, said as it is: 'Nação e brasões', 'Monumento', … */
function _kindsLabel(its) {
  const n = k => its.filter(g => g.sid && g.sid.startsWith(k)).length;
  const parts = [[n('s:'), 'Nação', 'Nações'], [n('e:'), 'Brasão', 'Brasões'], [n('m:'), 'Monumento', 'Monumentos']]
    .filter(([c]) => c).map(([c, one, many], i) => (c === 1 ? one : many).toLowerCase());
  const t = parts.length > 1 ? parts.slice(0, -1).join(', ') + ' e ' + parts[parts.length - 1] : parts[0] || '';
  return t.charAt(0).toUpperCase() + t.slice(1);
}
/* a place's pages: its people by age, then its nation, its states, its monuments */
function placePages(c) {
  const its = albPlaces().items[c] || [];
  const era = g => g.p.era ? g.p.era[0] : 1800;
  const figs = its.filter(g => g.p).sort((a, b) => era(a) - era(b) || a.n - b.n);
  const rank = g => ({ 's:': 0, 'e:': 1, 'm:': 2 }[g.sid.slice(0, 2)] ?? 3);
  const ext = its.filter(g => !g.p).sort((a, b) => rank(a) - rank(b) || a.n - b.n);
  const all = figs.concat(ext), pages = [];
  for (let i = 0; i < all.length; i += ALB_PER) {
    const pgIts = all.slice(i, i + ALB_PER), ds = pgIts.filter(g => g.p).map(era);
    /* a page that is mostly brasões and monuments is named for them, not for the one figure on it */
    const extra = pgIts.length - ds.length;
    pages.push(ds.length && extra * 2 <= pgIts.length
      ? { from: ds[0], to: ds[ds.length - 1], main: ds[Math.floor(ds.length / 2)], items: pgIts }
      : { from: 1800, to: 1800, main: 1800, items: pgIts, label: _kindsLabel(pgIts) });
  }
  return pages.length ? pages : [{ from: 1800, to: 1800, main: 1800, items: [], label: '' }];
}

/* the badge a place wears on the map and on its page: its flag, or the brasão of its first state */
function placeBadge(c, h) {
  if (FLAGS[c]) return flagSVG(c, h);
  const pol = Object.keys(POLITY_AT).find(id => POLITY_AT[id] === c);
  return pol ? `<span class="amap-crest" style="width:${h * 1.3}px;height:${h * 1.3}px">${clubArt(pol, '', false)}</span>` : ICON.column('#6E5836', h);
}

/* pins pushed apart until none sits on another, in pixels on the map as drawn, and never far from their country */
function _amapSpread(pins, W, H, min) {
  pins.forEach(p => { p.x0 = p.x; p.y0 = p.y; });
  for (let it = 0; it < 90; it++) {
    let moved = false;
    for (let i = 0; i < pins.length; i++) for (let j = i + 1; j < pins.length; j++) {
      const a = pins[i], b = pins[j];
      let dx = b.x - a.x, dy = b.y - a.y, d = Math.hypot(dx, dy);
      if (d >= min) continue;
      if (d < 1e-6) { dx = 1; dy = 0; d = 1; }
      const push = (min - d) / 2;
      a.x -= dx / d * push; a.y -= dy / d * push; b.x += dx / d * push; b.y += dy / d * push;
      moved = true;
    }
    pins.forEach(p => {
      const dx = p.x - p.x0, dy = p.y - p.y0, d = Math.hypot(dx, dy);
      if (d > 46) { p.x = p.x0 + dx / d * 46; p.y = p.y0 + dy / d * 46; }
      p.x = Math.max(24, Math.min(W - 24, p.x)); p.y = Math.max(24, Math.min(H - 24, p.y));
    });
    if (!moved) break;
  }
  return pins;
}

function albMapHtml() {
  const P = albPlaces(), total = ALL_STICKERS.length;
  const contStat = id => {
    const cs = P.order.filter(c => AMAP_PLACE_CONT[c] === id);
    return [cs.reduce((a, c) => a + placeGot(c), 0), cs.reduce((a, c) => a + placeAll(c), 0)];
  };
  const pct = albumPct();
  const shown = amapView === 'WORLD' ? P.order : P.order.filter(c => AMAP_PLACE_CONT[c] === amapView);
  /* the pages begun and nearest to finished, to send the player back for the last few */
  const near = shown.map(c => [c, placeGot(c), placeAll(c)]).filter(([, g, t]) => g > 0 && g < t)
    .sort((a, b) => (a[2] - a[1]) - (b[2] - b[1]) || b[1] / b[2] - a[1] / a[2]).slice(0, 3);
  const [sg, st] = amapView === 'WORLD' ? [album.size, total] : contStat(amapView);
  const strip = album.size === 0
    ? `<div class="amap-first"><span>Cada acerto cola uma figurinha e pinta o país dela no mapa.</span>
        <button id="amap-play" class="btn btn-brass btn-sm" type="button">${ICON.play('currentColor', 12)} Jogar</button></div>`
    : sg >= st
    ? `<div class="amap-done" role="status">${ICON.star('currentColor', 13)} ${({ WORLD: `Álbum completo! ${total} figurinhas em ${P.order.length} lugares`,
        EU: 'Europa completa!', AS: 'Ásia completa!', AF: 'África e Oriente Médio completos!', AM: 'Américas completas!' })[amapView]}</div>`
    : near.length ? `<div class="amap-near" role="group" aria-label="Falta pouco">
      <span class="amap-near-h" aria-hidden="true">Falta pouco</span>
      ${near.map(([c, g, t]) => `<button class="amap-nr" data-place="${c}" type="button" aria-label="${_esc(placeName(c))}: falta${t - g > 1 ? 'm' : ''} ${t - g}">
        <span class="amap-flag">${placeBadge(c, 12)}</span><span><b>${_esc(placeName(c))}</b><small>falta${t - g > 1 ? 'm' : ''} ${t - g}</small></span></button>`).join('')}
    </div>` : '';
  return `
  <div class="pg alb-pg amap-pg">
    <div class="alb-top">
      ${topbar('Álbum')}
      <div class="alb-head">
        <button id="balbvit" class="alb-vit" type="button">${ICON.star('currentColor', 12)} Vitrine</button>
        <button id="balbselo" class="alb-vit" type="button">${ICON.stamp('currentColor', 12)} Selos</button>
        <span class="display" style="font-size:20px;">${album.size}<span class="muted" style="font-size:13px;"> / ${total}</span></span>
      </div>
    </div>
    <div class="alb-bar"><i style="width:${Math.max(1, pct)}%"></i></div>
    <div class="amap-tabs" id="amap-tabs" aria-label="Partes do mundo">
      <button class="amap-tab${amapView === 'WORLD' ? ' is-on' : ''}" data-view="WORLD" type="button" aria-pressed="${amapView === 'WORLD'}">Mundo<small>${album.size}/${total}</small></button>
      ${AMAP_CONT.map(([id, n]) => { const [g, t] = contStat(id);
        return `<button class="amap-tab${amapView === id ? ' is-on' : ''}" data-view="${id}" type="button" aria-pressed="${amapView === id}" aria-label="${n}, ${g} de ${t}">${AMAP_TAB[id]}<small>${g}/${t}</small></button>`; }).join('')}
    </div>
    <div class="amap-wrap" id="amap-wrap">
      <div class="amap" id="amap" role="group" aria-label="${amapView === 'WORLD' ? 'O mapa-múndi: toque num continente para abrir o mapa dele'
        : `Carta: ${AMAP_CONT.find(c => c[0] === amapView)[1]}`}"></div>
    </div>
    ${strip}
    <p class="amap-hint small muted">${amapView === 'WORLD' ? (album.size ? 'Cada figurinha pinta o seu país. Toque num continente para abrir o mapa.' : 'Toque num continente para abrir o mapa.')
      : `${shown.length} lugares · toque num país para abrir a página`}</p>
  </div>`;
}

/* a place's page: the album's own spread, with the way back to the map */
function albPlaceHtml() {
  const P = albPlaces();
  if (!albCtry || !P.items[albCtry]) { albView = 'map'; return albMapHtml(); }
  const pages = placePages(albCtry);
  albPage = Math.max(0, Math.min(albPage, pages.length - 1));
  const spread = pages[albPage];
  const got = placeGot(albCtry), all = placeAll(albCtry);
  const label = spread.label || (pages.length === 1 && spread.items.some(g => g.p) ? 'Todas as épocas' : decLabel(spread));
  const nm = placeName(albCtry);
  return `
  <div class="pg alb-pg">
    <div class="alb-top">
      ${topbar('Álbum', 'amap-back')}
      <div class="alb-head">
        <button id="amap-back2" class="alb-vit" type="button">${ICON.globe('currentColor', 12)} Mapa</button>
        <span class="display" style="font-size:20px;">${got}<span class="muted" style="font-size:13px;"> / ${all}</span></span>
      </div>
    </div>
    <div class="alb-bar"><i style="width:${Math.max(1, Math.round(got / Math.max(1, all) * 100))}%"></i></div>
    <div class="alb-book ${decStyle(pages.length === 1 ? spread.to : spread.main)}" id="alb-book">
      ${(() => {
        const px = n => Math.min(9, n) * 1.6;
        const edge = (side, n) => n <= 0 ? '' : `<span class="alb-edge alb-edge-${side}" aria-hidden="true" style="width:${px(n)}px"></span>`;
        return edge('l', albPage) + edge('r', pages.length - 1 - albPage);
      })()}
      <div class="alb-band">
        <span class="crest-box" style="width:30px;flex:none;">${placeBadge(albCtry, 20)}</span>
        <span style="min-width:0;flex:1;">
          <span class="t">${_esc(nm)}</span>
          ${AMAP_LANGS[albCtry] ? `<span class="langs">${AMAP_LANGS[albCtry]}</span>` : ''}
        </span>
        <span class="alb-dec">${label}</span>
      </div>
      <div class="alb-sheet scroll-y${albTurning ? ' turn-' + albTurning : ''}">
        <div class="alb-grid">
          ${spread.items.map(it => {
            const { p, n } = it;
            const sid = it.sid || p.id;
            const has = album.has(sid);
            const name = p ? p.n : (stk(sid) || {}).n || '';
            const cp = has ? copyOf(sid) : null;
            const front = p
              ? figurinha(p, 'lg', { sub: (p.clubs && p.clubs[0]) ? clubName(p.clubs[0]) : POS_NAME[p.pos], noYear: true, copy: cp })
              : figExtra(sid, 'lg', { copy: cp });
            const back = p ? figurinhaBack(p, n) : figExtraBack(sid, n);
            return `<div class="alb-slot${has ? ' alb-turn' : ' empty'}${runNewIds.includes(sid) ? ' alb-fresh' : ''}"${
              has ? ` data-fig="${sid}" role="button" tabindex="0" aria-label="${name}${copyAria(cp)} — toque para ampliar"` : ''}>
              <span class="alb-n">${String(n).padStart(3, '0')}</span>
              ${has
                ? `<span class="flip"><span class="flip-in"><span class="flip-face flip-front">${front}</span><span class="flip-face flip-back">${back}</span></span></span>`
                : p && p.img
                ? `<span class="ph ph-face" aria-hidden="true"><img src="${p.img}" alt="" loading="lazy" draggable="false"></span><span class="nm-who">${_esc(name)}</span><span class="nm">a colar</span>`
                : `<span class="ph" aria-hidden="true">${albGhost(p ? 'player' : (stk(sid) || {}).kind)}</span>${name ? `<span class="nm-who">${_esc(name)}</span>` : ''}<span class="nm">a colar</span>`}
            </div>`;
          }).join('')}
          ${(() => {
            const left = ALB_PER - spread.items.length;
            if (left <= 0) return '';
            const used = Math.ceil(spread.items.length / ALB_COLS), rows = ALB_PER / ALB_COLS - used;
            return Array.from({ length: left }, () => '<div class="alb-slot alb-blank" aria-hidden="true"></div>').join('')
              /* the rest of the page: the country's own chart, cut from the old mapa-múndi */
              + (rows > 0 ? `<div class="alb-colo alb-colo-map${rows <= 2 ? '' : ' is-tall'}" style="grid-row:${used + 1} / span ${rows}" aria-hidden="true">
                  <span class="alb-inset" data-inset="${albCtry}"></span>
                  <span class="alb-colo-txt"><span class="alb-colo-t">${_esc(nm)}</span><span class="alb-colo-s"></span></span>
                </div>` : '');
          })()}
        </div>
      </div>
      <div class="alb-foot">
        <button id="alb-prev" class="alb-arrow" ${albPage === 0 ? 'disabled' : ''} aria-label="Página anterior">${ICON.back('currentColor', 14)}</button>
        <div class="alb-foot-mid">
          <div class="alb-pips" aria-hidden="true">${pages.map((pg, i) => `<span class="alb-pip${i === albPage ? ' is-on' : ''}${
            pg.items.every(g => album.has(_sidOf(g))) ? ' is-full' : ''}"></span>`).join('')}</div>
          <span class="alb-folio">${album.size === 0 ? 'cada acerto cola uma figurinha'
            : !LS.get('albFlipped', false) ? 'toque numa figurinha para ampliá-la'
            : `pág. ${albPage + 1} de ${pages.length} · ${got} de ${all}`}</span>
        </div>
        <button id="alb-next" class="alb-arrow alb-fwd" ${albPage >= pages.length - 1 ? 'disabled' : ''} aria-label="Próxima página">${ICON.back('currentColor', 14)}</button>
      </div>
    </div>
  </div>`;
}

/* A run that just stuck something in opens the album on that sticker's
   page, once: the reward is the reason they came here. Coming back to the
   album later in the same run's wake finds the map where it was left. */
let _albJumped = -1, _amapFreshAt = -1;
function albumHtml() {
  if (runNewIds.length && movedScreen && _albJumped !== gameN) {
    const c = placeOf(runNewIds[0]);
    _albJumped = gameN;
    if (c) {
      albView = 'place'; albCtry = c; amapView = AMAP_PLACE_CONT[c] || 'WORLD';
      const i = placePages(c).findIndex(pg => pg.items.some(g => _sidOf(g) === runNewIds[0]));
      albPage = i < 0 ? 0 : i;
    }
  }
  return albView === 'place' ? albPlaceHtml() : albMapHtml();
}

/* the countries the last run coloured in glow, the first time the map is drawn after it */
function _amapFresh() {
  if (!runNewIds.length || _amapFreshAt === gameN) return new Set();
  _amapFreshAt = gameN;
  return new Set(runNewIds.map(placeOf).filter(Boolean));
}
/* the map drawn to the room left for it, filling it */
function fitAlbMap() {
  const w = document.getElementById('amap-wrap'), m = document.getElementById('amap');
  if (!w || !m) return;
  let W = Math.floor(w.clientWidth), H = Math.floor(w.clientHeight);
  if (W < 60 || H < 60) return;
  /* a chart is drawn for rooms from a little taller than wide to twice as wide as tall; beyond that it is centred */
  if (amapView !== 'WORLD') { if (W > H * 2) W = Math.floor(H * 2); if (H > W / .62) H = Math.floor(W / .62); }
  m.style.left = Math.floor((w.clientWidth - W) / 2) + 'px'; m.style.top = Math.floor((w.clientHeight - H) / 2) + 'px';
  const key = `${W}x${H}:${amapView}:${album.size}`;
  if (m.dataset.drawn === key) return;
  const fresh = m.dataset.drawn ? new Set() : _amapFresh();
  m.dataset.drawn = key;
  if (_amapArrive) { m.classList.add(_amapArrive === 'out' ? 'is-arriving-out' : 'is-arriving-in'); _amapArrive = null; }
  m.style.width = W + 'px'; m.style.height = H + 'px';
  if (amapView === 'WORLD') {
    const wd = atlasWorld(W, H, fresh);
    m._world = wd;
    m.innerHTML = wd.svg;
    return;
  }
  const ch = atlasChart(amapView, W, H, fresh);
  const pins = ch.pins;                    // already spread apart, in pixels, by the chart
  const lead = pins.filter(p => Math.hypot(p.x - p.x0, p.y - p.y0) > 13);
  m.innerHTML = ch.svg
    + (lead.length ? `<svg class="amap-lead" viewBox="0 0 ${W} ${H}" aria-hidden="true">${lead.map(p =>
        `<path d="M${p.x0.toFixed(1)} ${p.y0.toFixed(1)}L${p.x.toFixed(1)} ${p.y.toFixed(1)}"/><circle cx="${p.x0.toFixed(1)}" cy="${p.y0.toFixed(1)}" r="2.2"/>`).join('')}</svg>` : '')
    + pins.sort((a, b) => a.y - b.y || a.x - b.x).map(p => {
      const g = placeGot(p.c), t = placeAll(p.c);
      return `<button class="amap-pin${g === t ? ' is-done' : ''}${g ? '' : ' is-empty'}${fresh.has(p.c) ? ' is-fresh' : ''}" data-place="${p.c}" type="button"
          style="left:${p.x.toFixed(1)}px;top:${p.y.toFixed(1)}px;--f:${(g / Math.max(1, t) * 100).toFixed(1)}%"
          aria-label="${_esc(placeName(p.c))}: ${g} de ${t} figurinhas" title="${_esc(placeName(p.c))} · ${g}/${t}">
          <span class="amap-flag">${placeBadge(p.c, 14)}</span></button>`;
    }).join('');
}
/* the little chart at the foot of a page, drawn to the room the page leaves */
function fitAlbInsets() {
  document.querySelectorAll('.alb-inset[data-inset]').forEach(el => {
    const W = Math.floor(el.clientWidth), H = Math.floor(el.clientHeight);
    if (W < 40 || H < 30 || el.dataset.drawn === W + 'x' + H) return;
    el.dataset.drawn = W + 'x' + H;
    const txt = el.closest('.alb-colo') && el.closest('.alb-colo').querySelector('.alb-colo-txt');
    const c = el.dataset.inset, d = atlasInset(c, W, H, txt ? txt.offsetWidth : 150);
    const at = (x, y) => `left:${x.toFixed(1)}%;top:${y.toFixed(1)}%`;
    el.innerHTML = d.svg
      + d.seas.map(([t, x, y]) => `<span class="alb-inset-sea" style="${at(x, y)}">${_esc(t)}</span>`).join('')
      + d.names.map(([t, x, y]) => `<span class="alb-inset-nm" style="${at(x, y)}">${_esc(t)}</span>`).join('')
      + (ATLAS_ART.rosa ? `<svg class="alb-inset-rose" viewBox="${ATLAS_ART.rosa.vb}" aria-hidden="true">${ATLAS_ART.rosa.svg}</svg>` : '')
      + (d.pin ? `<span class="alb-inset-pin" style="${at(d.pin[0], d.pin[1])}">${placeBadge(c, 12)}</span>` : '');
    /* the name plate stands where the little chart left room for it, with where the country lies */
    const box = el.closest('.alb-colo');
    if (box) {
      box.classList.toggle('plate-left', d.plate === 'left');
      box.classList.toggle('plate-none', d.plate === 'none');
      const sub = box.querySelector('.alb-colo-s');
      if (sub) sub.textContent = d.coord;
    }
  });
}
/* from the world into a part of it: the map leans in towards the spot tapped and the chart comes up out of it;
   back to the world, the chart draws away and the world comes back from afar */
let _amapArrive = null;
function _amapFly(id, x, y) {
  const m = document.getElementById('amap');
  snd.page();
  if (!m || FX_STILL) { amapView = id; go(); return; }
  const out = id === 'WORLD';
  if (x == null) { x = m.clientWidth / 2; y = m.clientHeight / 2; }
  m.style.transformOrigin = `${x.toFixed(0)}px ${y.toFixed(0)}px`;
  m.classList.add(out ? 'is-leaving-out' : 'is-leaving-in');
  setTimeout(() => { if (sc !== 'album') return; amapView = id; _amapArrive = out ? 'out' : 'in'; go(); }, 230);
}
function _amapOpen(c) {
  snd.swipe();
  albCtry = c;
  /* the first page that still has a pocket to fill */
  const i = placePages(c).findIndex(pg => pg.items.some(g => !album.has(_sidOf(g))));
  albPage = Math.max(0, i);
  albView = 'place';
  go();
}
function wireAlbMap() {
  const refit = () => { if (sc !== 'album') return; if (albView === 'map') fitAlbMap(); else fitAlbInsets(); };
  if (albView === 'map') refit();          // a page's inset waits for the page's own layout, a frame later
  requestAnimationFrame(refit);
  if (!window._amapRs) { window._amapRs = true; window.addEventListener('resize', refit); }
  const on = (id, fn) => document.getElementById(id)?.addEventListener('click', fn);
  const toMap = () => { snd.swipe(); albView = 'map'; go(); };
  on('amap-back', toMap);
  on('amap-back2', toMap);
  on('amap-play', () => { snd.select(); startMilhao(); });
  document.querySelectorAll('[data-view]').forEach(b => b.addEventListener('click', () => {
    if (b.dataset.view === amapView) return;
    _amapFly(b.dataset.view);
  }));
  document.querySelectorAll('.amap-nr').forEach(b => b.addEventListener('click', () => _amapOpen(b.dataset.place)));
  const m = document.getElementById('amap');
  if (!m) return;
  m.addEventListener('click', e => {
    const pin = e.target.closest('.amap-pin');
    if (pin) { _amapOpen(pin.dataset.place); return; }
    const hit = e.target.closest('[data-place]'), c = hit && hit.dataset.place;
    if (amapView !== 'WORLD') { if (c && placeAll(c)) _amapOpen(c); return; }
    /* on the world, a tap opens the chart of the part of the world under the finger: the country's own,
       or, at sea, the nearest part of the hemisphere tapped */
    let id = c ? AMAP_PLACE_CONT[c] : null;
    const wd = m._world;
    if (!id && wd) {
      const r = m.getBoundingClientRect(), x = e.clientX - r.left, y = e.clientY - r.top;
      const h = ['W', 'E'].find(k => Math.hypot(x - wd.C[k][0], y - wd.C[k][1]) <= wd.R * 1.05);
      if (h) {
        const ux = (x - wd.C[h][0]) / wd.sc, uy = (y - wd.C[h][1]) / wd.sc, an = ALB_MAP.hemi[h].anchors;
        id = Object.keys(an).sort((a, b) => Math.hypot(an[a][0] - ux, an[a][1] - uy) - Math.hypot(an[b][0] - ux, an[b][1] - uy))[0];
      }
    }
    if (id) { const r = m.getBoundingClientRect(); _amapFly(id, e.clientX - r.left, e.clientY - r.top); }
  });
}

