  if (px == null) { px = box.W / 2; py = box.H / 2; }
  const mx = c.vx + px / c.sx, my = c.vy + py / c.sy;
  const n = { z: Math.max(1, Math.min(ONDE_ZMAX, v.z * f)), cx: v.cx, cy: v.cy };
  const c2 = ondeCam(n, box);
