/* the pin is a [lat, lon] */
function ondeSetPin(ll) {
  if (!ll) return;
  onde.pin = [Math.max(-89.9, Math.min(89.9, ll[0])), _wrap(ll[1])];
  const b = document.getElementById('onde-go');
  if (b) b.disabled = false;
  const tip = document.getElementById('onde-tip');
  if (tip) tip.remove();
  const el = document.getElementById('onde-pin');
  if (el) { el.classList.remove('is-drop'); void el.offsetWidth; el.classList.add('is-drop'); }
  ondeApply();
}

function ondeCommit() {
  if (!onde.pin || onde.phase !== 'guess') return;
  const q = onde.qs[onde.i], e = q.e;
  const d = ondeKm(onde.pin, [q.at[0], q.at[1]]), p = ondePts(d);
  const selo = p >= 80 && e.pic && e.pic.scene && awardSelo(e.pic.scene) ? e.pic.scene : null;
  onde.log.push({ e, at: q.at, pin: onde.pin, d, p, selo });
  if (p === 100) { stats.ondeExact = (stats.ondeExact || 0) + 1; LS.set('stats', stats); }
  try { onde.medals = (onde.medals || []).concat(newMedals()); } catch (err) {}
  onde.pts += p;
  onde.phase = 'reveal';
  if (p === 100) snd.fanfare(); else if (p >= 80) snd.correct(0); else if (p >= 50) snd.almost(); else snd.wrong();
  go();
  requestAnimationFrame(() => ondeFitBoth());
  if (p >= 80) try { burst(p === 100 ? 28 : 14); } catch (err) {}
}
function ondeNext() {
  if (!onde || onde.phase !== 'reveal') return;
  if (onde.i >= onde.qs.length - 1) {
    onde.phase = 'end';
    stats.ondeGames = (stats.ondeGames || 0) + 1;
    LS.set('stats', stats);
    onde.isBest = onde.pts > LS.get('ondeBest', 0);
    if (onde.isBest) LS.set('ondeBest', onde.pts);
    /* the day's map is kept, once: the first time it is played today */
    if (onde.dia) { LS.set('ondeDia', { day: dayIndex(), pts: onde.pts }); stats.ondeDias = (stats.ondeDias || 0) + 1; LS.set('stats', stats); onde.dia = false; onde.diaDone = true; }
    window._newMedals = (onde.medals || []).concat(newMedals());
    setTimeout(() => snd.final(onde.pts >= 500), 200);
  } else {
    onde.i++;
    onde.pin = null;
    onde.phase = 'guess';
    onde.v = { cx: 0, cy: 0, z: 1 };
  }
  go();
}

function wireOnde() {
  const on = (id, fn) => document.getElementById(id)?.addEventListener('click', fn);
  const ready = tapArmed();   // js/ano.js: a double tap's second half is not an answer
  on('onde-go', () => { if (ready()) ondeCommit(); });
  on('onde-next', () => { if (ready()) { snd.swipe(); ondeNext(); } });
  on('onde-again', () => { snd.select(); startOnde(); });
  on('onde-share', () => {
    const txt = ondeShareText();
    if (navigator.share) navigator.share({ text: txt }).catch(() => {});
    else if (navigator.clipboard) navigator.clipboard.writeText(txt).then(() => {
      const b = document.getElementById('onde-share'); if (b) { b.dataset.l = b.dataset.l || b.textContent; b.textContent = 'Copiado!'; setTimeout(() => { b.textContent = b.dataset.l; }, 1600); } }).catch(() => {});
  });
  /* the results' little map takes the room the page leaves it, and stands down when that is too little to read */
  const rm = document.querySelector('.onde-res-map');
  if (rm && rm.clientHeight < 96) rm.classList.add('is-tiny');
  const m = document.getElementById('onde-map');
  if (!m) return;
  ondeApply();
  if (window.ResizeObserver) { const ro = new ResizeObserver(() => { if (document.body.contains(m)) ondeApply(); else ro.disconnect(); }); ro.observe(m); }
  const guessing = () => onde.phase === 'guess';
  document.querySelectorAll('[data-zoom]').forEach(b => b.addEventListener('click', ev => {
    ev.stopPropagation(); snd.tap();
    const k = b.dataset.zoom;
    if (k === 'world') ondeFly({ cx: 0, cy: 0, z: 1 });
    else if (onde.pin && k === 'in') { const c = ondeCam(onde.v), [x, y] = ondeToPx(c, ondeXY(onde.pin[0], onde.pin[1])), box = ondeBox();
      ondeZoomAt(2, Math.max(0, Math.min(box.W, x)), Math.max(0, Math.min(box.H, y)), true); }
    else ondeZoomAt(k === 'in' ? 2 : 0.5, null, null, true);
  }));
  /* touch and mouse: a tap marks, a drag looks around, two fingers zoom */
  const pts = new Map();
  let g = null;
  const rel = ev => { const r = m.getBoundingClientRect(); return [ev.clientX - r.left, ev.clientY - r.top]; };
  m.addEventListener('pointerdown', ev => {
    if (ev.target.closest('.onde-zoom')) return;
    try { m.setPointerCapture(ev.pointerId); } catch (e) {}
    pts.set(ev.pointerId, rel(ev));
    _ondeAnim++;
    if (pts.size === 1) g = { p0: rel(ev), v0: Object.assign({}, onde.v), moved: false, pinch: false };
    else if (pts.size === 2 && g) {
      const [a, b] = [...pts.values()];
      g.pinch = true; g.moved = true;
      g.d0 = Math.hypot(a[0] - b[0], a[1] - b[1]) || 1; g.z0 = onde.v.z;
      const mid = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2], c = ondeCam(onde.v);
      g.anchor = [c.vx + mid[0] / c.sx, c.vy + mid[1] / c.sy];
    }
  });
  m.addEventListener('pointermove', ev => {
    if (!g || !pts.has(ev.pointerId)) return;
    pts.set(ev.pointerId, rel(ev));
    const box = ondeBox();
    if (g.pinch && pts.size >= 2) {
      const [a, b] = [...pts.values()];
      const d = Math.hypot(a[0] - b[0], a[1] - b[1]) || 1, mid = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2];
      const n = { z: Math.max(1, Math.min(ONDE_ZMAX, g.z0 * d / g.d0)), cx: onde.v.cx, cy: onde.v.cy };
      const c = ondeCam(n, box);
      n.cx = g.anchor[0] - mid[0] / c.sx + c.vw / 2; n.cy = g.anchor[1] - mid[1] / c.sy + c.vh / 2;
      Object.assign(onde.v, ondeClamp(n, box)); ondeApply();
      return;
    }
    const p = rel(ev), dx = p[0] - g.p0[0], dy = p[1] - g.p0[1];
    if (!g.moved && Math.hypot(dx, dy) < 7) return;
    g.moved = true;
    const c = ondeCam(g.v0, box);
    Object.assign(onde.v, ondeClamp({ z: g.v0.z, cx: g.v0.cx - dx / c.sx, cy: g.v0.cy - dy / c.sy }, box));
    ondeApply();
  });
  const up = ev => {
    if (!pts.has(ev.pointerId)) return;
    const p = rel(ev);
    pts.delete(ev.pointerId);
    if (!g) return;
    if (pts.size === 0) {
      const tap = !g.moved && ev.type === 'pointerup';
      g = null;
      if (!tap || !guessing()) return;
      const c = ondeCam(onde.v), x = c.vx + p[0] / c.sx, y = c.vy + p[1] / c.sy, ll = ondeLL([x, y]);
      if (!ll) return;                 // between the two worlds, or past their rims
      try { snd.pin(); } catch (e) { snd.tap(); }
      ondeSetPin(ll);
      /* the first tap on the whole world zooms in there, to place it finer */
      if (onde.v.z < 2.5) ondeFly(ondeClamp({ z: 4, cx: x, cy: y }, ondeBox()));
    } else if (pts.size === 1 && g.pinch) {
      /* one finger left after a pinch: carry on as a drag from here */
      g = { p0: [...pts.values()][0], v0: Object.assign({}, onde.v), moved: true, pinch: false };
    }
  };
  m.addEventListener('pointerup', up);
  m.addEventListener('pointercancel', up);
  m.addEventListener('wheel', ev => {
    ev.preventDefault();
    const p = rel(ev);
    ondeZoomAt(Math.pow(1.2, -Math.sign(ev.deltaY)), p[0], p[1], false);
  }, { passive: false });
  /* the keyboard: arrows move the pin (or the map, before there is one), + and − zoom, Enter marks the centre */
  m.addEventListener('keydown', ev => {
    const k = ev.key, c = ondeCam(onde.v), box = ondeBox();
    const mv = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] }[k];
    if (mv) {
      ev.preventDefault();
      const step = (ev.shiftKey ? 60 : 16);
      if (onde.pin && guessing()) { const q = ondeXY(onde.pin[0], onde.pin[1]); ondeSetPin(ondeLL([q[0] + mv[0] * step / c.sx, q[1] + mv[1] * step / c.sy])); }
      else { Object.assign(onde.v, ondeClamp({ z: onde.v.z, cx: onde.v.cx + mv[0] * step * 2 / c.sx, cy: onde.v.cy + mv[1] * step * 2 / c.sy }, box)); ondeApply(); }
    } else if (k === '+' || k === '=') { ev.preventDefault(); ondeZoomAt(2, null, null, true); }
    else if (k === '-' || k === '_') { ev.preventDefault(); ondeZoomAt(0.5, null, null, true); }
    /* Space marks the centre of the view; Enter marks it too, or nails in a pin already there */
    else if ((k === 'Enter' || k === ' ') && guessing()) {
      ev.preventDefault();
      if (onde.pin && k === 'Enter') ondeCommit(); else ondeSetPin(ondeLL([onde.v.cx, onde.v.cy]));
    }
  });
}

/* ═══════════════════════════════════════════════════
   NO RASTRO DO LADRÃO — a relic stolen, and a thief who runs from city to
   city. At each stop the witnesses leave clues to the next one: something
   that happened there (one of the Que ano? events, with its year), what
   the thief bought or wore, a photograph left behind. Three places are on
   the map; the player flies to one. The right one and the trail goes on;
   a wrong one and the trail is cold there, and the way back costs hours.
   The clock is the case's: when it runs out, the thief is gone. The map is
   Onde foi?'s two hemispheres (js/onde.js), drawn small, its camera
   following the chase.
═══════════════════════════════════════════════════ */
const LR_STOPS = 5;                 // the cities the thief runs to after the theft
const LR_RELICS = ['a coroa de ferro da Lombardia', 'o elmo de Sutton Hoo', 'a máscara de Agamenon', 'o astrolábio de Vasco da Gama',
  'a luneta de Galileu', 'o diamante Koh-i-Noor', 'o caderno de anotações de Leonardo', 'o cetro de D. Pedro II', 'o tinteiro de Machado de Assis',
  'a pena de Shakespeare', 'o violino Stradivarius “Messias”', 'o relógio de bolso de Santos Dumont', 'o cálice de Ardagh', 'o mapa de Piri Reis',
  'a espada de Carlos Magno', 'o selo imperial de Qin Shi Huang'];
const LR_THIEVES = [['a Raposa do Tempo', 'capa xadrez e luvas de veludo'], ['o Barão do Sumiço', 'chapéu-coco e bigode encerado'],
  ['a Condessa das Relíquias', 'chapéu de plumas e um leque de marfim'], ['o Mestre dos Disfarces', 'uma barba que muda de cor a cada cidade'],
  ['a Sombra de Veneza', 'máscara de carnaval e sapatos sem barulho'], ['o Gato das Catedrais', 'botas de alpinista e uma corda de seda']];
/* a country's flag, from the name at the end of a place */
const LR_FLAG_EXTRA = { 'Países Baixos': 'NED', 'Suécia': 'SWE', 'Coreia do Sul': 'KOR', 'Gana': 'GHA', 'Senegal': 'SEN', 'Nigéria': 'NGA',
  'Argélia': 'ALG', 'Romênia': 'ROU', 'País de Gales': 'WAL', 'Costa do Marfim': 'CIV', 'Camarões': 'CMR', 'Libéria': 'LBR', 'Reino Unido': 'ENG',
  'República Tcheca': 'CZE', 'Escócia': 'SCO', 'Irlanda do Norte': 'NIR', 'Síria': 'SYR', 'Bolívia': 'BOL', 'Lituânia': 'LTU',
  'Bahamas': 'BHS', 'Cazaquistão': 'KAZ', 'Bósnia e Herzegovina': 'BIH', 'Equador': 'ECU', 'Vaticano': 'VAT', 'Arábia Saudita': 'SAU', 'Canadá': 'CAN' };
let _lrFlagOf = null;
function lrFlag(place) {
  if (!_lrFlagOf) { _lrFlagOf = Object.assign({}, LR_FLAG_EXTRA); Object.entries(CTRY_NAME).forEach(([c, n]) => { _lrFlagOf[n] = c; }); }
  const c = _lrFlagOf[place.split(', ').pop().split('/')[0]];   // 'França/Itália': the first
  return c && FLAGS[c] ? c : null;
}
/* the places of the events, one stop each, with the events that happened there */
let _lrPlaces = null;
function lrPlaces() {
  if (_lrPlaces) return _lrPlaces;
  const by = {};
  ANO_EVENTS.forEach(e => { const a = ONDE_AT[e.id]; if (!a) return;
    (by[a[2]] = by[a[2]] || { name: a[2], at: [a[0], a[1]], evs: [] }).evs.push(e); });
  return (_lrPlaces = Object.values(by));
}
const lrHours = km => Math.round(2 + km / 900);

let lr = null;   // { seed, relic, thief, chain: [place], stop, at, opts, wrong, hours, max, phase, log, cam, fly }

/* the case: a chain of cities far apart, each with its three choices */
function lrNew(seed) {
  if (seed == null) seed = (Math.random() * CHAL_SEED_MAX) | 0;
  seedFrom(seed);
  const P = shuf(lrPlaces().slice()), far = (a, b, km) => ondeKm(a.at, b.at) >= km;
  const chain = [P[0]];
  for (const p of P) {
    if (chain.length > LR_STOPS) break;
    const last = chain[chain.length - 1];
    if (!chain.includes(p) && far(p, last, 1800) && (chain.length < 2 || ondeReg(p.at) !== ondeReg(last.at) || rnd() < .35)) chain.push(p);
  }
  for (const p of P) { if (chain.length > LR_STOPS) break; if (!chain.includes(p) && far(p, chain[chain.length - 1], 900)) chain.push(p); }
  /* the time the case allows: the flights it takes, and room for two wrong turns */
  let ideal = 0;
  for (let i = 1; i < chain.length; i++) ideal += lrHours(ondeKm(chain[i - 1].at, chain[i].at));
  const th = LR_THIEVES[Math.floor(rnd() * LR_THIEVES.length)];
  lr = { seed, relic: LR_RELICS[Math.floor(rnd() * LR_RELICS.length)], thief: th[0], looks: th[1], chain, stop: 0, at: chain[0],
    hours: ideal + 26, max: ideal + 26, phase: 'brief', log: [], wrong: [], n: 1000 + (seed % 9000) };
  lr.clues = chain.map((p, i) => i ? lrClues(p, i) : null);
  lr.opts = chain.map((p, i) => i ? lrOpts(p, i) : null);
  _seed = null;
}
/* the three places on the map for a stop: the right one and two far from it and from each other; from the third
   stop on, the wrong ones are sought in the same part of the world, so the clue has to be known */
function lrOpts(ans, i) {
  const P = shuf(lrPlaces().filter(p => p !== ans && !lr.chain.slice(0, i).includes(p)));
  const reg = ondeReg(ans.at), out = [ans];
  const ok = p => out.every(o => ondeKm(o.at, p.at) >= 1300);
  if (i >= 3) for (const p of P) { if (out.length >= 3) break; if (ondeReg(p.at) === reg && ok(p)) out.push(p); }
  for (const p of P) { if (out.length >= 3) break; if (ok(p)) out.push(p); }
  return shuf(out);
}
/* what the witnesses saw: something that happened at the next city, with its year; what the thief bought or wore
   for its weather; and, sometimes, a photograph left behind */
/* the note the thief dropped has the place itself smudged out — "Batalha de ▒▒▒▒▒▒" — or the clue would name the answer */
function lrBlot(t, place) {
  /* word by word, without accents: a word is smudged when it starts as one of the place's names does (Chernobyl
     for Chernobil, babilônicos for Babilônia) — four letters for a short name, five for a longer one */
  const bare = w => w.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
  const keys = place.split(/[^\p{L}]+/u).filter(w => w.length >= 4 && !/^(perto|della|ocidentais)$/i.test(w)).map(w => bare(w).slice(0, w.length > 4 ? 5 : 4));
  return t.replace(/\p{L}+/gu, w => w.length >= 4 && keys.some(k => bare(w).startsWith(k)) ? '▒'.repeat(Math.min(9, w.length)) : w);
}
function lrClues(p, i) {
  const e = p.evs[Math.floor(rnd() * p.evs.length)], [la, lo] = p.at, et = lrBlot(e.t, p.name);
  const ev = [`Deixou cair um bilhete com uma data e um rabisco: «${et}», ${e.c ? 'c. ' : ''}${anoYear(e.y)}.`,
    `Perguntou ao porteiro como chegar ao lugar onde aconteceu isto: «${et}» (${e.c ? 'c. ' : ''}${anoYear(e.y)}).`,
    `Comprou um livro de História aberto na página: «${et}», ${e.c ? 'c. ' : ''}${anoYear(e.y)}.`][Math.floor(rnd() * 3)];
  const wx = Math.abs(la) < 23.4 ? 'Levou chapéu de palha e protetor solar: ia para os trópicos.'
    : la > 49 ? 'Comprou um casaco de lã grosso e luvas para o frio.'
    : la < -23.4 ? 'Disse que ia para o sul, para baixo do Trópico de Capricórnio.'
    : lo < -30 ? 'Trocou dinheiro por moedas das Américas.' : 'Levava um guarda-chuva e uma capa leve, de meia-estação.';
  const pic = e.pic && (e.pic.scene || e.pic.face) ? e : null;
  return { e, ev, wx, pic };
}

function startLadrao(seed) {
  isDaily = false; isSurv = false; isMil = false; isRev = false;
  runSelos = [];
  lrNew(seed);
  sc = 'ladrao';
  go();
}

/* ── the map: the two hemispheres side by side, drawn once; a camera on the viewBox follows the chase ── */
const _lrE = OM_R + OM_B, _lrD = _lrE + OM_G / 2, LR_C = { W: [-_lrD, 0], E: [_lrD, 0] };
const LR_BOX = [-_lrD - _lrE - 4, -_lrE - 4, 2 * (_lrD + _lrE + 4), 2 * (_lrE + 4)];
const lrXY = ([la, lo]) => { const h = ondeHemi(lo), [x, y] = ondeProj(h, la, lo); return [x + LR_C[h][0], y + LR_C[h][1]]; };
let _lrSvg = null;
function lrMapSvg() {
  if (!_lrSvg) { const d = _ondeDiscs('lr');
    _lrSvg = `<defs>${d.defs}</defs><g transform="translate(${LR_C.W[0]} 0)">${d.body.W}</g><g transform="translate(${LR_C.E[0]} 0)">${d.body.E}</g>`; }
  return `<svg class="lr-svg" id="lr-svg" viewBox="${LR_BOX.join(' ')}" preserveAspectRatio="xMidYMid meet" aria-hidden="true">${_lrSvg}</svg>`;
}
/* the view that holds these points, with a margin, shaped like the box it is drawn in */
function lrFit(pts, box) {
  const xs = pts.map(p => p[0]), ys = pts.map(p => p[1]), A = box.W / Math.max(1, box.H);
  let w = Math.max(70, Math.max(...xs) - Math.min(...xs) + 46), h = Math.max(46, Math.max(...ys) - Math.min(...ys) + 40);
  if (w / h < A) w = h * A; else h = w / A;
  if (w > LR_BOX[2]) { w = LR_BOX[2]; h = w / A; }
  if (h > LR_BOX[3] && h / A > LR_BOX[2]) { h = LR_BOX[3]; w = h * A; }
  const cx = (Math.min(...xs) + Math.max(...xs)) / 2, cy = (Math.min(...ys) + Math.max(...ys)) / 2;
  const clampC = (c, s, a, b) => s >= b ? a + b / 2 : Math.max(a + s / 2, Math.min(a + b - s / 2, c));
  return { x: clampC(cx, w, LR_BOX[0], LR_BOX[2]) - w / 2, y: clampC(cy, h, LR_BOX[1], LR_BOX[3]) - h / 2, w, h };
}
const lrBox = () => { const m = document.getElementById('lr-map'); return m ? { W: m.clientWidth, H: m.clientHeight } : { W: 340, H: 200 }; };
/* where the camera should look in this phase: the city, the three choices, the flight */
function lrWant() {
  const pts = [lrXY(lr.at.at)];
  if (lr.phase === 'clue') lr.opts[lr.stop + 1].forEach(p => pts.push(lrXY(p.at)));
  if (lr.phase === 'fly' || lr.phase === 'cold') pts.push(lrXY(lr.to.at));
  if (lr.phase === 'end') lr.chain.slice(0, lr.stop + 1).forEach(p => pts.push(lrXY(p.at)));
  return lrFit(pts, lrBox());
}
function lrPlaceOverlay() {
  const svg = document.getElementById('lr-svg'), box = lrBox(), c = lr.cam;
  if (!svg || !c) return;
  svg.setAttribute('viewBox', `${c.x.toFixed(2)} ${c.y.toFixed(2)} ${c.w.toFixed(2)} ${c.h.toFixed(2)}`);
  const s = box.W / c.w, px = q => [(q[0] - c.x) * s, (q[1] - c.y) * s];
  document.querySelectorAll('#lr-map [data-ll]').forEach(el => {
    const [x, y] = px(lrXY(el.dataset.ll.split(',').map(Number)));
    el.style.transform = `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px)`;
  });
  /* the trail flown so far, and the flight under way, drawn in pixels */
  const ov = document.getElementById('lr-ov');
  if (ov) {
    ov.setAttribute('viewBox', `0 0 ${box.W} ${box.H}`);
    const seg = (a, b) => { const [x1, y1] = px(lrXY(a)), [x2, y2] = px(lrXY(b)), mx = (x1 + x2) / 2, my = (y1 + y2) / 2 - Math.hypot(x2 - x1, y2 - y1) * .18;
      return `M${x1.toFixed(1)} ${y1.toFixed(1)}Q${mx.toFixed(1)} ${my.toFixed(1)} ${x2.toFixed(1)} ${y2.toFixed(1)}`; };
    const trail = lr.chain.slice(0, lr.stop + 1).map((p, i, a) => i ? seg(a[i - 1].at, p.at) : '').join('');
    const fly = lr.to && (lr.phase === 'fly' || lr.phase === 'cold') ? seg(lr.at.at, lr.to.at) : '';
    const t = document.getElementById('lr-trail'), f = document.getElementById('lr-fly');
    if (t) t.setAttribute('d', trail);
    if (f) f.setAttribute('d', fly);
  }
}
function lrCamTo(want, ms, done) {
  const from = lr.cam || want, t0 = performance.now(), id = (lr.camId = (lr.camId || 0) + 1);
  if (!ms || FX_STILL) { lr.cam = want; lrPlaceOverlay(); requestAnimationFrame(lrRemask); if (done) done(); return; }
  const step = now => {
    if (!lr || lr.camId !== id) return;
    const k = Math.min(1, (now - t0) / ms), e = k < .5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    lr.cam = { x: from.x + (want.x - from.x) * e, y: from.y + (want.y - from.y) * e, w: from.w * Math.pow(want.w / from.w, e), h: from.h * Math.pow(want.h / from.h, e) };
    lrPlaceOverlay();
    if (k < 1) requestAnimationFrame(step); else { lrRemask(); if (done) done(); }
  };
  requestAnimationFrame(step);
}
/* the coasts' water-lining is a mask, kept at the scale it was first drawn: a fresh copy once the camera has settled */
function lrRemask() { ['lrW-coast', 'lrE-coast'].forEach(id => { const m = document.getElementById(id); if (m) m.replaceWith(m.cloneNode(true)); }); }

/* ── the moves ── */
function lrGo(i) {
  if (!lr || lr.phase !== 'clue') return;
  const to = lr.opts[lr.stop + 1][i];
  if (!to || lr.wrong.includes(to)) return;
  const h = lrHours(ondeKm(lr.at.at, to.at));
  lr.to = to; lr.phase = 'fly'; lr.flyH = h;
  try { snd.swipe(); } catch (e) {}
  go();
  /* the plane crosses the map while the clock spends the hours */
  const plane = document.getElementById('lr-plane'), path = document.getElementById('lr-fly'), clock = document.getElementById('lr-h');
  const h0 = lr.hours, ms = FX_STILL ? 0 : 1500, t0 = performance.now();
  const tick = now => {
    if (!lr || lr.phase !== 'fly') return;
    const k = ms ? Math.min(1, (now - t0) / ms) : 1;
    if (plane && path && path.getTotalLength) {
      const L = path.getTotalLength(), a = path.getPointAtLength(L * k), b = path.getPointAtLength(Math.min(L, L * k + 1));
      plane.style.transform = `translate(${a.x.toFixed(1)}px, ${a.y.toFixed(1)}px) rotate(${(Math.atan2(b.y - a.y, b.x - a.x) * 180 / Math.PI).toFixed(0)}deg)`;
    }
    if (clock) clock.textContent = Math.max(0, Math.round(h0 - h * k));
    if (k < 1) requestAnimationFrame(tick); else lrLand();
  };
  requestAnimationFrame(tick);
}
function lrLand() {
  lr.hours -= lr.flyH;
  const right = lr.to === lr.chain[lr.stop + 1];
  lr.log.push({ from: lr.at, to: lr.to, ok: right, h: lr.flyH });
  if (right) {
    lr.stop++; lr.at = lr.to; lr.to = null; lr.wrong = [];
    if (lr.stop >= lr.chain.length - 1) return lrEnd(true);
    if (lr.hours <= 0) return lrEnd(false);
    lr.phase = 'clue'; lr.hot = true;
    try { snd.correct(lr.stop - 1); } catch (e) {}
  } else {
    lr.wrong.push(lr.to);
    if (lr.hours <= 0) return lrEnd(false);
    lr.phase = 'cold';
    try { snd.wrong(); haptic([28, 45, 28]); } catch (e) {}
  }
  go();
}
/* from a cold trail, back to the city the clues were found in */
function lrBack() {
  if (!lr || lr.phase !== 'cold') return;
  const h = lrHours(ondeKm(lr.to.at, lr.at.at));
  lr.hours -= h;
  lr.log.push({ from: lr.to, to: lr.at, back: true, h });
  lr.to = null;
  if (lr.hours <= 0) return lrEnd(false);
  lr.phase = 'clue'; lr.hot = false;
  try { snd.swipe(); } catch (e) {}
  go();
}
function lrEnd(caught) {
  lr.phase = 'end'; lr.caught = caught; lr.hours = Math.max(0, lr.hours);
  stats.lrCases = (stats.lrCases || 0) + 1;
  if (caught) { stats.lrCaught = (stats.lrCaught || 0) + 1; stats.lrBest = Math.max(stats.lrBest || 0, lr.hours); }
  LS.set('stats', stats);
  window._newMedals = newMedals();
  go();
  setTimeout(() => { try { if (caught) { snd.fanfare(); fx.rain(60, ['#8E1F1C', '#E0B968', '#F3EEDE']); } else snd.final(false); } catch (e) {} }, 300);
}
const LR_RANKS = [[30, 'Inspetor-chefe'], [16, 'Detetive de primeira'], [6, 'Detetive'], [0, 'Agente novato']];

/* ── the screens ── */
function ladraoHtml() {
  if (!lr) lrNew();
  if (lr.phase === 'brief') return lrBriefHtml();
  if (lr.phase === 'end') return lrEndHtml();
  const next = lr.stop + 1, c = lr.clues[next], opts = lr.opts[next], low = lr.hours <= 12;
  const pin = (p, cls, k) => `<span class="lr-pin ${cls}" data-ll="${p.at[0]},${p.at[1]}"${k != null ? ` data-k="${k}"` : ''}>${k != null ? `<b>${k + 1}</b>` : '<i></i>'}</span>`;
  return `
  <div class="pg lr-pg">
    ${topbar('No rastro do ladrão')}
    <div class="lr-head">
      <span class="lr-case">Caso nº ${lr.n} · <b>${_esc(lr.relic)}</b></span>
      <span class="lr-clock${low ? ' is-low' : ''}" title="Horas que restam">${ICON.clock('currentColor', 13)} <b class="num" id="lr-h">${lr.hours}</b> h</span>
    </div>
    <div class="lr-map" id="lr-map">
      ${lrMapSvg()}
      <svg class="lr-ov" id="lr-ov" aria-hidden="true"><path id="lr-trail" class="lr-trail"/><path id="lr-fly" class="lr-flyp"/></svg>
      ${lr.chain.slice(0, lr.stop).map(p => pin(p, 'lr-been')).join('')}
      ${lr.phase === 'clue' ? opts.map((p, k) => lr.wrong.includes(p) ? pin(p, 'lr-cold') : pin(p, 'lr-cho', k)).join('') : ''}
      ${lr.to ? pin(lr.to, lr.phase === 'cold' ? 'lr-cold' : 'lr-dest') : ''}
      ${pin(lr.at, 'lr-here')}
      ${lr.phase === 'fly' ? `<span class="lr-plane" id="lr-plane" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M21 16v-2l-8-5V3.5a1.5 1.5 0 0 0-3 0V9l-8 5v2l8-2.5V19l-2 1.5V22l3.5-1 3.5 1v-1.5L13 19v-5.5z" fill="#2A1D10" stroke="#F7F1E2" stroke-width=".8" transform="rotate(90 12 12)"/></svg></span>` : ''}
    </div>
    ${lr.phase === 'cold' ? `
    <div class="lr-file lr-cold-file" role="status">
      <span class="lr-stamp is-cold">Pista fria</span>
      <p class="lr-at">${_esc(lr.to.name)}</p>
      <p class="lr-note">Ninguém por aqui viu ${_esc(lr.thief)}. O rastro ficou em ${_esc(lr.at.name.split(', ')[0])}.</p>
      <button id="lr-back" class="btn btn-brass" type="button">Voltar para ${_esc(lr.at.name.split(', ')[0])} · ${lrHours(ondeKm(lr.to.at, lr.at.at))} h</button>
    </div>`
    : lr.phase === 'fly' ? `
    <div class="lr-file"><p class="lr-at">Voando para ${_esc(lr.to.name)}…</p><p class="lr-note">${lr.flyH} horas de viagem.</p></div>`
    : `
    <div class="lr-file">
      ${lr.hot ? `<span class="lr-stamp is-hot">${lr.stop ? 'Pista quente!' : 'Início do rastro'}</span>` : ''}
      <p class="lr-at">${ICON.map('currentColor', 12)} Em ${_esc(lr.at.name)}${lr.stop ? ` · parada ${lr.stop} de ${LR_STOPS}` : ''}</p>
      <div class="lr-clues">
        ${c.pic ? `<span class="lr-photo">${anoPic(c.pic)}</span>` : ''}
        <p class="lr-clue">${_esc(c.ev)}</p>
        <p class="lr-clue lr-wx">${_esc(c.wx)}</p>
      </div>
    </div>
    <div class="lr-opts">${opts.map((p, k) => { const f = lrFlag(p.name), off = lr.wrong.includes(p), h = lrHours(ondeKm(lr.at.at, p.at));
      return `<button class="lr-opt${off ? ' is-off' : ''}" data-o="${k}" type="button"${off ? ' disabled' : ''}>
        <b class="lr-k">${k + 1}</b>${f ? `<span class="lr-flag">${flagSVG(f, 14)}</span>` : ''}
        <span class="lr-nm">${_esc(p.name)}</span><small>${off ? 'pista fria' : h + ' h'}</small></button>`; }).join('')}</div>`}
  </div>`;
}
function lrBriefHtml() {
  return `
  <div class="pg pg-center lr-pg lr-brief">
    ${topbar('No rastro do ladrão')}
    <div class="lr-poster">
      <span class="lr-poster-k">Interpol do Tempo · caso nº ${lr.n}</span>
      <span class="lr-mug">${LR_MUG}</span>
      <span class="lr-poster-h">Procura-se</span>
      <b class="lr-poster-n">${_esc(lr.thief)}</b>
      <small>visto pela última vez com ${_esc(lr.looks)}</small>
    </div>
    <p class="lr-brief-p">Roubou <b>${_esc(lr.relic)}</b> em <b>${_esc(lr.at.name)}</b> e fugiu. Siga as pistas por ${LR_STOPS} cidades e prenda o ladrão em menos de <b>${lr.hours} horas</b>.</p>
    <button id="lr-start" class="btn btn-brass btn-lg" type="button">${ICON.map('currentColor', 13)} Começar a caçada</button>
    ${stats.lrCaught ? `<p class="small muted">Ladrões presos: ${stats.lrCaught}</p>` : ''}
  </div>`;
}
/* the wanted man: a silhouette in a hat and coat */
const LR_MUG = `<svg viewBox="0 0 100 110" aria-hidden="true"><rect width="100" height="110" fill="#E9DDC1"/>
  ${[20, 40, 60, 80, 100].map(y => `<path d="M0 ${y}H100" stroke="#B8A27A" stroke-width=".8"/>`).join('')}
  <path d="M50 30c-9 0-15 7-15 17 0 7 3 12 7 15l-1 6c-14 3-24 12-26 42h70c-2-30-12-39-26-42l-1-6c4-3 7-8 7-15 0-10-6-17-15-17z" fill="#2E2116"/>
  <path d="M28 33c4-2 9-3 22-3s18 1 22 3l-3-14c-2-6-8-9-19-9s-17 3-19 9z" fill="#1A120A"/><path d="M22 33c8 3 20 4 28 4s20-1 28-4" stroke="#1A120A" stroke-width="4" fill="none" stroke-linecap="round"/>
  <path d="M38 56c4 3 8 4 12 4s8-1 12-4" stroke="#E9DDC1" stroke-width="2" fill="none" stroke-linecap="round" opacity=".55"/>
  <circle cx="44" cy="47" r="2" fill="#E9DDC1"/><circle cx="56" cy="47" r="2" fill="#E9DDC1"/></svg>`;
function lrEndHtml() {
  const rank = lr.caught ? LR_RANKS.find(r => lr.hours >= r[0])[1] : null, ok = lr.log.filter(l => l.ok).length, bad = lr.log.filter(l => !l.ok && !l.back).length;
  return `
  <div class="pg pg-center lr-pg lr-end">
    <div class="eyebrow">No rastro do ladrão · caso nº ${lr.n}</div>
    <div class="lr-poster${lr.caught ? ' is-caught' : ' is-gone'}">
      <span class="lr-poster-k">${lr.caught ? `Preso em ${_esc(lr.at.name.split(', ')[0])}` : 'Caso arquivado'}</span>
      <span class="lr-mug">${LR_MUG}</span>
      <b class="lr-poster-n">${_esc(lr.thief)}</b>
      <span class="lr-stamp-big">${lr.caught ? 'Preso!' : 'Escapou'}</span>
    </div>
    <div class="display" style="font-size:24px;"><em>${lr.caught ? `${rank}!` : 'O ladrão escapou desta vez'}</em></div>
    <p class="small muted" style="margin:0;">${lr.caught ? `${_esc(lr.relic).replace(/^./, m => m.toUpperCase())} voltou ao museu, com <b>${lr.hours} h</b> de sobra.` : `O relógio parou com ${ok} de ${LR_STOPS} cidades no rastro.`} ${bad ? `${bad} ${bad === 1 ? 'pista fria' : 'pistas frias'}.` : 'Nenhuma pista fria!'}</p>
    <div class="lr-map lr-map-end" id="lr-map">${lrMapSvg()}<svg class="lr-ov" id="lr-ov" aria-hidden="true"><path id="lr-trail" class="lr-trail"/><path id="lr-fly" class="lr-flyp"/></svg>
      ${lr.chain.slice(0, lr.stop + 1).map((p, i) => `<span class="lr-pin ${i === lr.stop ? 'lr-here' : 'lr-been'}" data-ll="${p.at[0]},${p.at[1]}"><b>${i ? i : '★'}</b></span>`).join('')}</div>
    ${medalChips()}
    <div class="foot-row" style="margin-top:6px;">
      <button id="lr-share" class="btn btn-ghost btn-sm" type="button">Compartilhar</button>
      <button id="lr-again" class="btn btn-brass" type="button">Novo caso</button>
      <button id="bhome" class="btn btn-ghost btn-sm" type="button">Início</button>
    </div>
  </div>`;
}
const lrShareText = () => `🕵️ No rastro do ladrão · History Quiz\n${lr.caught ? `Prendi ${lr.thief} em ${lr.at.name.split(', ')[0]} com ${lr.hours} h de sobra!` : `${lr.thief.replace(/^./, m => m.toUpperCase())} escapou…`}\n${lr.log.filter(l => !l.back).map(l => l.ok ? '✈️' : '❄️').join('')}${lr.caught ? '🚔' : '💨'}\n${CHAL_URL}`;

function wireLadrao() {
  if (!lr) return;
  const on = (id, fn) => document.getElementById(id)?.addEventListener('click', fn);
  const ready = tapArmed();
  on('lr-start', () => { if (!ready()) return; snd.page(); lr.phase = 'clue'; lr.hot = true; go(); });
  on('lr-back', () => { if (ready()) lrBack(); });
  on('lr-again', () => { snd.select(); startLadrao(); });
  on('lr-share', () => {
    const txt = lrShareText();
    if (navigator.share) navigator.share({ text: txt }).catch(() => {});
    else if (navigator.clipboard) navigator.clipboard.writeText(txt).then(() => {
      const b = document.getElementById('lr-share'); if (b) { b.dataset.l = b.dataset.l || b.textContent; b.textContent = 'Copiado!'; setTimeout(() => { b.textContent = b.dataset.l; }, 1600); } }).catch(() => {});
  });
  document.querySelectorAll('.lr-opt').forEach(b => b.addEventListener('click', () => { if (ready()) lrGo(+b.dataset.o); }));
  document.querySelectorAll('.lr-pin.lr-cho').forEach(b => b.addEventListener('click', () => { if (ready()) lrGo(+b.dataset.k); }));
  if (!document.getElementById('lr-map')) return;
  /* the camera: from where it was to where this phase wants it */
  const want = lrWant();
  lrCamTo(want, lr.cam ? 700 : 0);
  if (lr.hot && lr.phase === 'clue') { lr.hot = false; requestAnimationFrame(() => { try { fx.splash(document.querySelector('.lr-pin.lr-here'), '#8E1F1C', 8); } catch (e) {} }); }
}
/* the keyboard: 1, 2, 3 fly there; Enter goes back from a cold trail */
document.addEventListener('keydown', ev => {
  if (sc !== 'ladrao' || !lr || ev.altKey || ev.ctrlKey || ev.metaKey) return;
  if (lr.phase === 'clue' && /^[123]$/.test(ev.key)) { ev.preventDefault(); lrGo(+ev.key - 1); }
  else if (lr.phase === 'cold' && ev.key === 'Enter') { ev.preventDefault(); lrBack(); }
});

/* ═══════════════════════════════════════════════════
   O DESAFIO — a link that deals a friend the very same game
   Every run is dealt from a seed (O BARALHO DA RODADA): the same seed deals
   the same questions, in the same order, with the same tiles, on any phone.
   So a result can travel as a link, ?d=<game>.<seed>.<score>[.<more>] in
   base 36. Whoever opens it is shown what they are up against, plays that
   game, and is told at the end who won; their own share sends it back.
═══════════════════════════════════════════════════ */
const CHAL_URL = 'https://tdosreis.github.io/history-quiz/';
const CHAL_GAMES = {
  tf: { n: 'Treino · Fácil', diff: 'facil', ic: 'check' },
  tm: { n: 'Treino · Moderado', diff: 'moderado', ic: 'bolt' },
  td: { n: 'Treino · Difícil', diff: 'dificil', ic: 'flame' },
  m:  { n: 'Rumo ao Milhão', ic: 'crown' },
  a:  { n: 'Que ano?', ic: 'hourglass' },
  o:  { n: 'Onde foi?', ic: 'globe' },
  c:  { n: 'Cronologia', ic: 'timeline' },
  d:  { n: 'Antes ou depois?', ic: 'hourglass' },
  f:  { n: 'Mito ou fato?', ic: 'stamp' },
};
const CHAL_SEED_MAX = 2147483647;
let chal = null;           // a challenge received: { g, seed, score, more, code, used }

/* The game a seed deals depends on the questions and events the app has: a link made with one version of them
   and opened with another would deal a different game. So a link carries two characters that fingerprint them,
   and a link from another version is still played, but no winner is called. */
let _chalVer = null;
function chalVer() {
  if (_chalVer) return _chalVer;
  let h = 5381;
  const add = s => { for (let i = 0; i < s.length; i++) h = (h * 33 + s.charCodeAt(i)) | 0; };
  CATS.forEach(c => { add(c.id); c.qs.forEach(q => add(q.t)); });
  ANO_EVENTS.forEach(e => add(e.id)); MF.forEach(c => add(c.id + c.v)); Object.keys(ONDE_AT).forEach(add); PL.forEach(p => add(p.id)); add(String(LADDER.length));
  return (_chalVer = ((h >>> 0) % 1296).toString(36).padStart(2, '0'));
}
function chalCode(c) {
  return [c.g, c.seed.toString(36), Math.max(0, Math.round(c.score)).toString(36),
    c.more != null ? Math.max(0, Math.round(c.more)).toString(36) : '', c.ver || chalVer()].join('.');
}
const chalLink = c => CHAL_URL + '?d=' + chalCode(c);
function chalParse(s) {
  const m = /^(tf|tm|td|m|a|o|c|d|f)\.([0-9a-z]{1,6})\.([0-9a-z]{1,6})\.([0-9a-z]{0,3})\.([0-9a-z]{2})$/.exec(String(s || '').trim().toLowerCase());
  if (!m) return null;
  const seed = parseInt(m[2], 36), score = parseInt(m[3], 36), more = m[4] ? parseInt(m[4], 36) : null;
  if (!(seed >= 0 && seed <= CHAL_SEED_MAX)) return null;
  const cap = m[1] === 'm' ? 1000000 : m[1][0] === 't' ? 99999 : m[1] === 'c' || m[1] === 'd' ? ANO_EVENTS.length : m[1] === 'f' ? MF.length : 1000;
  if (!(score <= cap)) return null;
  if (m[1] === 'm' && !(more != null && more <= LADDER.length)) return null;
  if (m[1][0] === 't' && more != null && more > 50) return null;
  return { g: m[1], seed, score, more, code: m[0], ver: m[5], old: m[5] !== chalVer() };
}

/* the seed a new game is dealt from: the challenge's, the first time that game is started after accepting it */
function chalSeed(g) {
  if (chal && chal.accepted && !chal.used && chal.g === g) { chal.used = true; return chal.seed; }
  return (Math.random() * CHAL_SEED_MAX) | 0;
}

/* the game that just ended, as a challenge to send */
function chalMine() {
  if (sc === 'ano' && ano && ano.phase === 'end' && ano.seed != null) return { g: 'a', seed: ano.seed, score: ano.pts };
  if (sc === 'onde' && onde && onde.phase === 'end' && onde.seed != null) return { g: 'o', seed: onde.seed, score: onde.pts };
  if (sc === 'cron' && cron && cron.phase === 'end' && cron.seed != null) return { g: 'c', seed: cron.seed, score: cron.score };
  if (sc === 'aod' && aod && aod.phase === 'end' && aod.seed != null) return { g: 'd', seed: aod.seed, score: aod.score };
  if (sc === 'mito' && mf && mf.phase === 'end' && mf.seed != null) return { g: 'f', seed: mf.seed, score: mf.score };
  if (sc !== 'end' || runSeed == null || isDaily || isSurv || (typeof isRev !== 'undefined' && isRev)) return null;
  if (isMil) return { g: 'm', seed: runSeed, score: banked, more: rung };
  const g = 't' + String(diffKey)[0];
  return CHAL_GAMES[g] ? { g, seed: runSeed, score: pts, more: nCorrect } : null;
}
/* is this the very game the friend was challenged with? */
const chalIsThis = mine => !!(mine && chal && chal.used && chal.g === mine.g && chal.seed === mine.seed);
/* better, worse or the same: the money first on the ladder, then how far up */
const chalCmp = (a, b) => a.g === 'm' ? (a.score - b.score) || ((a.more || 0) - (b.more || 0)) : a.score - b.score;
function chalScoreTxt(c) {
  if (c.g === 'm') return `${money(c.score)} · degrau ${c.more || 0}`;
  if (c.g === 'c') return `${c.score} na linha`;
  if (c.g === 'd') return `${c.score} ${c.score === 1 ? 'acerto seguido' : 'acertos seguidos'}`;
  if (c.g === 'f') return `${c.score} ${c.score === 1 ? 'acerto' : 'acertos'}`;
  return `${c.score} pts`;
}

/* the line the share card ends on */
function chalShareTail(mine) {
  if (!mine) return CHAL_URL;
  let head = '';
  if (chalIsThis(mine) && !chal.old) {
    const r = chalCmp(mine, chal);
    head = `Desafio: ${chalScoreTxt(mine)} × ${chalScoreTxt(chal)} — ${r > 0 ? 'venci! 🏆' : r < 0 ? 'perdi, desta vez' : 'empate'}\n`;
  }
  return `${head}${mine.g === 'm' ? 'Encara as mesmas 16 perguntas?' : mine.g === 'a' || mine.g === 'o' ? 'Encara os mesmos 10 eventos?' : mine.g === 'c' ? 'Encara a mesma linha do tempo?' : mine.g === 'd' ? 'Encara a mesma sequência de eventos?' : 'Encara as mesmas perguntas?'} ${chalLink(mine)}`;
}

/* on the results: who won */
function chalBanner() {
  const mine = chalMine();
  if (!chalIsThis(mine)) return '';
  /* a link from another version of the game dealt a different game: no winner is called */
  const r = chal.old ? 0 : chalCmp(mine, chal), say = chal.old ? 'outra versão do jogo' : r > 0 ? 'Você venceu!' : r < 0 ? 'Não foi dessa vez' : 'Empate!';
  /* on the ladder the money decides, and the rung when the money is the same — then the rung is said too */
  const tie = mine.g === 'm' && mine.score === chal.score;
  const n = c => c.g === 'm' ? money(c.score) + (tie ? ` · degrau ${c.more || 0}` : '') : c.score + (c.g[0] === 't' ? ' pts' : '');
  return `<div class="chal-res ${r > 0 ? 'is-win' : r < 0 ? 'is-lose' : 'is-tie'}" role="status"
      aria-label="Desafio: você ${chalScoreTxt(mine)}, seu amigo ${chalScoreTxt(chal)}. ${say}.">
    <span class="chal-res-k" aria-hidden="true">${ICON.sword('currentColor', 11)} Desafio</span>
    <span class="chal-res-v" aria-hidden="true"><small>você</small> <b>${n(mine)}</b> <i>×</i> <b>${n(chal)}</b> <small>amigo</small></span>
    <em aria-hidden="true">${say}</em></div>`;
}

/* ── the screen a challenge link opens on ── */
function chalHtml() {
  const c = chal, G = c && CHAL_GAMES[c.g];
  if (!G) { sc = 'home'; return html(); }
  const what = c.g === 'm' ? 'As mesmas 16 perguntas da escada até o milhão, com as mesmas alternativas.'
             : c.g === 'a' ? 'Os mesmos 10 eventos, na mesma régua de anos.'
             : c.g === 'o' ? 'Os mesmos 10 eventos, para achar no mapa.'
             : c.g === 'c' ? 'Os mesmos eventos, na mesma ordem, para pôr na linha do tempo. Três vidas.'
             : c.g === 'd' ? 'Os mesmos eventos, na mesma ordem: o próximo veio antes ou depois? Até errar um.'
             : c.g === 'f' ? 'As mesmas cartas, na mesma ordem: mito ou fato? Três vidas.'
             : `As mesmas ${(DIFFS.find(d => d.key === G.diff) || DIFFS[0]).n} perguntas, na mesma ordem, com as mesmas alternativas.`;
  const more = c.g[0] === 't' && c.more != null ? `${c.more} ${c.more === 1 ? 'acerto' : 'acertos'}` : '';
  return `
  <div class="pg pg-center chal-pg">
    <div class="eyebrow">Desafio recebido</div>
    <span class="chal-ic mode-disc mode-${c.g === 'm' ? 'album' : c.g === 'a' ? 'ano' : c.g === 'o' ? 'onde' : c.g === 'c' ? 'cron' : c.g === 'd' ? 'aod' : c.g === 'f' ? 'mito' : 'train'}">${(ICON[G.ic] || ICON.sword)('currentColor', 26)}</span>
    <div class="display" style="font-size:31px;"><em>Um amigo te desafiou!</em></div>
    <p class="chal-g">${G.n}</p>
    <div class="chal-card"><small>Placar a bater</small><b class="num">${chalScoreTxt(c)}</b>${more ? `<span>${more}</span>` : ''}</div>
    <p class="small muted" style="max-width:30ch;">${c.old ? 'Este desafio veio de outra versão do jogo: as perguntas podem não ser as mesmas.' : what}</p>
    <button id="chal-go" class="btn btn-brass btn-lg">${ICON.sword('currentColor', 15)} Aceitar o desafio</button>
    <button id="chal-no" class="btn btn-ghost btn-sm">Agora não</button>
  </div>`;
}
function chalAccept() {
  if (!chal) return;
  chal.accepted = true;
  LS.set('chal', null);
  const G = CHAL_GAMES[chal.g];
  if (chal.g[0] === 't') { diffKey = G.diff; startGame(); }
  else if (chal.g === 'm') startMilhao();
  else if (chal.g === 'a') startAno();
  else if (chal.g === 'o') startOnde();
  else if (chal.g === 'c') startCron();
  else if (chal.g === 'd') startAod();
  else if (chal.g === 'f') startMito();
}
function wireChal() {
  document.getElementById('chal-go')?.addEventListener('click', () => { snd.select(); chalAccept(); });
  document.getElementById('chal-no')?.addEventListener('click', () => { snd.swipe(); sc = 'home'; go(); });
}
/* the cover's line for a challenge put off for later */
function chalNews() {
  if (!chal || chal.accepted) return '';
  const G = CHAL_GAMES[chal.g];
  return `<button id="bchal" class="home-news" type="button">
    <span class="hn-ic">${ICON.sword('currentColor', 13)}</span>
    <span>Desafio de um amigo · <b>${G.n}</b> · ${chalScoreTxt(chal)}</span></button>`;
}

/* At start: a link with a challenge opens on it (and leaves the address
   clean, so a reload is not a second challenge); one put off waits on the cover. */
function chalBoot() {
  let code = null;
  try {
    const q = new URLSearchParams(location.search).get('d');
    if (q !== null) {
      code = q;
      const u = new URL(location.href); u.searchParams.delete('d');
      history.replaceState(history.state, '', u.pathname + (u.search || '') + u.hash);
    }
  } catch (e) {}
  const fresh = code !== null ? chalParse(code) : null;
  if (fresh) { chal = fresh; LS.set('chal', fresh.code); sc = 'desafio'; return; }
  const kept = chalParse(LS.get('chal', null));
  if (kept) chal = kept;
}

/* ═══════════════════════════════════════════════════
   REVISAR — the questions you got wrong, again, spaced out
   A written question missed in any game goes into a box to come back to.
   The boxes are a Leitner file: right on review, a question comes back a
   day later, then three, then seven, and after that it is learned and
   leaves; missed again, it starts over. Knowing it before it is due proves
   little, so that does not move it. The game is a round of up to ten of
   those that are due, with a slower clock than training.
═══════════════════════════════════════════════════ */
const REV_N = 10;
const REV_GAPS = [0, 1, 3, 7];      // days until a question comes back, by box
const REV_MAX = 300;                // the file keeps the most recent misses
let _revPool = null;
/* A question is known by all of it, not by its line: a fifth of them share a line ("Quem disse esta frase?",
   "Quem sou eu?") and differ only in the quote, the clues or the answer. The key is a short hash of the
   question as written (a copy made for a game carries the same fields, and its own underscored ones are left out). */
const _revHash = s => { let h = 5381; for (let i = 0; i < s.length; i++) h = (h * 33 + s.charCodeAt(i)) | 0; return (h >>> 0).toString(36); };
const revKey = q => _revHash(JSON.stringify(q, (k, v) => (k && k[0] === '_' ? undefined : v)));
/* the written questions — the only ones that stay the same from one game to the next — by key */
function revPool() {
  if (_revPool) return _revPool;
  _revPool = new Map();
  CATS.forEach(c => c.qs.forEach(q => { const k = revKey(q); if (!_revPool.has(k)) _revPool.set(k, { q, c }); }));
  return _revPool;
}
/* the file of misses; anything in it the pool no longer knows (an older file's keys, a question since removed) is let go */
function revFile() {
  const r = LS.get('rev', {});
  if (!r || typeof r !== 'object' || Array.isArray(r)) return {};
  if (!Object.keys(r).length) return r;   // nothing filed: the questions need not be counted (it costs the cover's first draw)
  const pool = revPool(), gone = Object.keys(r).filter(k => !pool.has(k));
  if (gone.length) { gone.forEach(k => delete r[k]); LS.set('rev', r); }
  return r;
}
/* an answer, from any game: a miss is filed, a right answer to a due one moves it on */
function revNote(q, p) {
  if (!q || !q.t) return;
  const key = revKey(q);
  if (!revPool().has(key)) return;
  const R = revFile(), now = dayIndex(), e = R[key];
  if (p !== 3) { delete R[key]; R[key] = [0, now]; }
  else if (e && e[1] <= now) {
    const box = e[0] + 1;
    if (box >= REV_GAPS.length) { delete R[key]; stats.revLearned = (stats.revLearned || 0) + 1; LS.set('stats', stats); }
    else R[key] = [box, now + REV_GAPS[box]];
  } else return;
  const ks = Object.keys(R);
  ks.slice(0, Math.max(0, ks.length - REV_MAX)).forEach(k => delete R[k]);
  LS.set('rev', R);
}
const revDue = () => { const R = revFile(), now = dayIndex(); return Object.keys(R).filter(t => R[t][1] <= now && revPool().has(t)); };
/* how many days until the next one is due (or null, with none filed) */
function revWait() {
  const R = revFile(), now = dayIndex(), ds = Object.keys(R).filter(t => revPool().has(t)).map(t => R[t][1] - now);
  return ds.length ? Math.max(0, Math.min(...ds)) : null;
}
function revTail() {
  const n = revDue().length;
  if (n) return `${n} ${n === 1 ? 'pendente' : 'pendentes'}`;
  const w = revWait();
  return w === null ? 'Nenhum ainda' : `Em ${w} ${w === 1 ? 'dia' : 'dias'}`;
}

function startRev() {
  const due = revDue();
  if (!due.length) return false;
  isDaily = false; isSurv = false; isMil = false; isRev = true;
  diffKey = 'moderado';
  _seed = null; runSeed = null;
  /* the longest waiting first, then the rest in no order */
  const R = revFile();
  const pick = due.sort((a, b) => R[a][1] - R[b][1]).slice(0, REV_N);
  const qs = shuf(pick).map(t => { const { q, c } = revPool().get(t); return { ...q, _cat: c }; });
  cat = { id: 'revisar', name: 'Revisar erros', emoji: '📖', tag: 'Os que você errou', col: '#2F5D62', diff: 'Revisão', qs };
  qi = 0; sel.clear(); pts = 0; prevPts = 0; streak = 0;
  nCorrect = 0; nPartial = 0; bestStreak = 0; lastGain = 0; runLog = []; runNew = 0; runNewIds = []; runPulls = []; runSelos = []; runPackOpened = false; gameN++;
  resetLifes();
  sc = 'quiz'; tMax = qTime(); tLeft = tMax; lastMsg = '';
  disp = getDisp(cat.qs[0]);
  startTmr();
  go();
  return true;
}

/* ═══════════════════════════════════════════════════
   CRONOLOGIA — put each event in its place on the line of time
   The line starts with one event, its year shown. Each turn brings a new
   one, year hidden: the player taps the gap where it goes, before, between
   or after the ones already there. Right, and it takes its place with its
   year; wrong, and it still goes where it belongs, but a life goes with
   it. Three lives. The longer the line, the closer the years and the
   harder the gaps. Dealt from a seed, so a line can be sent to a friend.
   The Linha do dia is dealt from the day: the same line for everyone,
   scored once, kept tap by tap so it goes on where it was left.
   ANO_EVENTS (the Que ano? events) are above this line.
═══════════════════════════════════════════════════ */
const CRON_LIVES = 3;
let cron = null;           // { deck, line, cur, lives, score, phase: 'place'|'reveal'|'end', last, log, seed, daily?, replay? }

function buildCron() {
  const deck = shuf(ANO_EVENTS.slice());
  const first = deck.pop();
  return { deck, line: [first], cur: deck.pop(), lives: CRON_LIVES, score: 0, phase: 'place', last: null, log: [], picks: [] };
}
function startCron() {
  isDaily = false; isSurv = false; isMil = false; isRev = false;
  runSelos = [];
  /* dealt from a seed, so the game can be sent to a friend as a challenge (js/desafio.js) */
  const seed = chalSeed('c');
  seedFrom(seed); cron = buildCron(); _seed = null;
  cron.seed = seed;
  sc = 'cron';
  go();
}
/* ── A LINHA DO DIA ── the day's line, numbered like the Diário */
const cronDiaSeed = day => day * 104729 + 11;
/* today's line as kept: { day, ids: the events in the order dealt, picks: [[gap, event id], …], score, lives, done } */
const cronDiaKept = () => { const r = LS.get('cronDia', null); return r && r.day === dayIndex() && Array.isArray(r.picks) ? r : null; };
function startCronDia() {
  isDaily = false; isSurv = false; isMil = false; isRev = false;
  runSelos = [];
  const day = dayIndex();
  seedFrom(cronDiaSeed(day)); cron = buildCron(); _seed = null;
  cron.daily = { day };
  const kept = cronDiaKept();
  /* dealt again from the events kept with it: an app updated during the day still has the same line */
  if (kept && Array.isArray(kept.ids)) {
    const by = new Map(ANO_EVENTS.map(e => [e.id, e])), evs = kept.ids.map(id => by.get(id)).filter(Boolean);
    if (evs.length >= 2) { cron.line = [evs[0]]; cron.cur = evs[1]; cron.deck = evs.slice(2).reverse(); }
  }
  cron.ids = [cron.line[0].id, cron.cur.id].concat(cron.deck.slice().reverse().map(e => e.id));
  if (kept) {
    /* the taps already made are made again, quietly: no sound, no stamp, nothing counted twice */
    for (const [gap, id] of kept.picks) {
      if (!cron.cur || cron.cur.id !== id || cron.phase !== 'place') break;
      cronApply(gap);
      cron.picks.push([gap, id]);
      if (cron.lives > 0 && cron.deck.length) { cron.cur = cron.deck.pop(); cron.phase = 'place'; }
      else cron.phase = 'reveal';
    }
    /* what could not be laid again (an event gone from the app) keeps its count: no life comes back */
    if (cron.picks.length < kept.picks.length) {
      cron.picks = kept.picks.slice();
      if (kept.score != null) cron.score = kept.score;
      if (kept.lives != null) cron.lives = kept.lives;
      if (!kept.done && cron.lives <= 0) cron.phase = 'reveal';
    }
    /* a line already finished is shown as it was laid, and counts for nothing */
    if (kept.done) { cron.replay = true; cron.phase = 'end'; }
  }
  window._newMedals = [];
  sc = 'cron';
  go();
}

/* the gaps an event may go in: equal years fit either side of one another */
function cronFits(line, e, i) {
  return (i === 0 || line[i - 1].y <= e.y) && (i === line.length || e.y <= line[i].y);
}
const cronYear = e => (e.c ? 'c. ' : '') + anoYear(e.y);
const cronRow = (e, cls, id, li) => `<div class="cron-row${cls || ''}"${id ? ` id="${id}"` : ''}${li ? ' role="listitem"' : ''}>
      <b class="cron-y num${cronYear(e).length > 8 ? ' is-long' : ''}">${cronYear(e)}</b><span class="cron-t">${_esc(e.t)}</span></div>`;

function cronHtml() {
  if (!cron) cron = buildCron();
  if (cron.phase === 'end') return cronEndHtml();
  const rev = cron.phase === 'reveal', L = cron.last;
  const lives = Array.from({ length: CRON_LIVES }, (_, i) => `<i class="${i < cron.lives ? 'on' : ''}">${ICON.hourglass('currentColor', 15)}</i>`).join('');
  const rows = [];
  cron.line.forEach((e, i) => {
    if (!rev) rows.push(`<button class="cron-slot" data-slot="${i}" type="button" aria-label="${i ? `Entre ${cronYear(cron.line[i - 1])} e ${cronYear(e)}` : `Antes de ${cronYear(e)}`}"><span>${i ? 'aqui' : 'antes'}</span></button>`);
    const fresh = L && L.e === e;
    rows.push(cronRow(e, fresh && rev ? (L.ok ? ' is-good' : ' is-bad') : '', fresh ? 'cron-fresh' : '', rev));
  });
  if (!rev) rows.push(`<button class="cron-slot" data-slot="${cron.line.length}" type="button" aria-label="Depois de ${cronYear(cron.line[cron.line.length - 1])}"><span>depois</span></button>`);
  /* the first turn says the rules once, in the room the line has not yet taken */
  if (!rev && cron.line.length === 1) rows.push(`<p class="cron-hint">O ano de cada evento aparece quando ele entra na linha. Errou o lugar, perde uma das ${CRON_LIVES === 3 ? 'três' : CRON_LIVES} ampulhetas.</p>`);
  return `
  <div class="pg cron-pg${rev ? ' is-rev' : ''}">
    ${topbar(cron.daily ? 'Linha do dia · nº ' + cron.daily.day : 'Cronologia')}
    <div class="ano-head"><span class="cron-lives" role="img" aria-label="${cron.lives} de ${CRON_LIVES} vidas">${lives}</span>
      <span class="ano-score"><b class="num">${cron.score}</b> na linha</span></div>
    ${rev ? `<div class="cron-res ${L.ok ? 'good' : 'bad'}" id="cron-res" aria-live="polite">
        <p class="cron-res-h"><b>${L.ok ? 'Isso!' : 'Não era aí'}</b> <span class="num">${cronYear(L.e)}</span>${L.ok ? '' : ` <small>· ${cron.lives} ${cron.lives === 1 ? 'vida' : 'vidas'}</small>`}</p>
        ${L.selo ? seloWonLine(L.selo) : ''}${L.e.x ? `<p class="cron-res-x">${_esc(L.e.x)}</p>` : ''}
      </div>`
      : `<div class="onde-card cron-card">
      ${ondePic(cron.cur)}
      <div class="onde-tt"><p class="onde-t">${_esc(cron.cur.t)}</p><span class="onde-y">Toque onde entra na linha</span></div>
    </div>`}
    <div class="cron-line scroll-y" id="cron-line" ${rev ? 'role="list" tabindex="0"' : 'role="group"'} aria-label="A linha do tempo, do mais antigo ao mais recente">${rows.join('')}</div>
    ${rev ? `<button id="cron-next" class="btn btn-brass" aria-describedby="cron-res">${cron.lives <= 0 || !cron.deck.length ? 'Ver resultado' : 'Próximo'}</button>` : ''}
  </div>`;
}

function cronEndHtml() {
  const best = LS.get('cronBest', 0);
  const msg = cron.score >= 20 ? 'Um cronista de verdade!' : cron.score >= 12 ? 'Ótima memória do tempo!' : cron.score >= 6 ? 'Nada mau!' : 'O tempo é traiçoeiro…';
  const wrong = new Set(cron.log.filter(l => !l.ok).map(l => l.e)), D = cron.daily;
  return `
  <div class="pg pg-center ano-end cron-end" style="padding:22px 18px;gap:9px;">
    <div class="eyebrow${D ? ' eb-keep' : ''}">${D ? 'Linha do dia · nº ' + D.day : 'Cronologia · ' + cron.line.length + ' eventos'}</div>
    <div class="display" style="font-size:28px;"><em>${msg}</em></div>
    ${wreathed(cron.score >= 10, `<div class="display prize-pop brass" style="font-size:50px;letter-spacing:-.03em;">${cron.score}<span class="muted" style="font-size:18px;letter-spacing:0;"> na linha</span></div>`)}
    ${D ? `<p class="small muted">${cron.replay ? 'A sua linha de hoje' : cron.isBest ? 'Seu novo recorde!' : 'A mesma linha para todo mundo'} · <b>amanhã, outra</b></p>`
      : chalBanner() || `<p class="small muted">${cron.isBest ? 'Seu novo recorde!' : `Recorde: ${best}`}</p>`}
    <div class="cron-line cron-line-end scroll-y" role="list" tabindex="0" aria-label="A linha do tempo">${cron.line.map(e => cronRow(e, wrong.has(e) ? ' is-bad' : '', '', true)).join('')}</div>
    ${selosStrip()}
    ${medalChips()}
    <div class="foot-row" style="margin-top:8px;">
      <button id="cron-share" class="btn btn-ghost btn-sm">${chalMine() ? 'Desafiar' : 'Compartilhar'}</button>
      <button id="cron-again" class="btn btn-brass">${D ? 'Partida livre' : 'De novo'}</button>
      <button id="bhome" class="btn btn-ghost btn-sm">Início</button>
    </div>
  </div>`;
}

function cronShareText() {
  /* a long line is shared by its first thirty */
  const grid = cron.log.slice(0, 30).map(l => l.ok ? '🟩' : '⬛').join('') + (cron.log.length > 30 ? '…' : '');
  const n = `${cron.score} ${cron.score === 1 ? 'evento' : 'eventos'} na linha`;
  if (cron.daily) return `Linha do dia nº ${cron.daily.day} 📜 History Quiz\n${grid}\n${n}\n${CHAL_URL}`;
  return `Cronologia 📜 History Quiz\n${grid}\n${n}\n${chalShareTail(chalMine())}`;
}

/* the move itself, and nothing else: the event into the line, the score or a life */
function cronApply(i) {
  const e = cron.cur, ok = cronFits(cron.line, e, i);
  /* right or wrong, it goes where it belongs */
  let at = i;
  if (!ok) { at = cron.line.findIndex(x => x.y > e.y); if (at < 0) at = cron.line.length; }
  cron.line.splice(at, 0, e);
  cron.log.push({ e, ok });
  cron.last = { e, ok };
  if (ok) cron.score++; else cron.lives--;
  return ok;
}
function cronPlace(i) {
  if (!cron || cron.phase !== 'place') return;
  const e = cron.cur, ok = cronApply(i);
  cron.picks.push([i, e.id]);
  if (cron.daily && !cron.replay) LS.set('cronDia', { day: cron.daily.day, ids: cron.ids, picks: cron.picks, score: cron.score, lives: cron.lives, done: false });
  if (ok && !cron.replay) { stats.cronPlaced = (stats.cronPlaced || 0) + 1; LS.set('stats', stats); }
  if (ok) {
    /* a long line is hard to place in: from the sixth on, an event with a scene is cancelled into the stamp album */
    if (cron.line.length >= 6 && e.pic && e.pic.scene && awardSelo(e.pic.scene)) cron.last.selo = e.pic.scene;
    snd.correct(Math.min(cron.score, 8));
  } else snd.wrong();
  try { cron.medals = (cron.medals || []).concat(newMedals()); } catch (err) {}
  cron.phase = 'reveal';
  cron.fx = 'next';
  go();
  if (ok && cron.score % 5 === 0) try { burst(16); } catch (err) {}
}
function cronNext() {
  if (!cron || cron.phase !== 'reveal') return;
  if (cron.lives <= 0 || !cron.deck.length) {
    cron.phase = 'end';
    if (cron.replay) { go(); return; }
    stats.cronGames = (stats.cronGames || 0) + 1;
    stats.cronBest = Math.max(stats.cronBest || 0, cron.score);
    if (cron.daily) {
      stats.cronDiaGames = (stats.cronDiaGames || 0) + 1;
      LS.set('cronDia', { day: cron.daily.day, ids: cron.ids, picks: cron.picks, score: cron.score, lives: cron.lives, done: true });
    }
    LS.set('stats', stats);
    cron.isBest = cron.score > LS.get('cronBest', 0);
    if (cron.isBest) LS.set('cronBest', cron.score);
    window._newMedals = (cron.medals || []).concat(newMedals());
    setTimeout(() => snd.final(cron.score >= 8), 200);
  } else {
    cron.cur = cron.deck.pop();
    cron.phase = 'place';
    cron.fx = 'slot';
  }
  go();
}

/* ── the Cronologia's door: the day's line, or a free one ── */
function cronMenuHtml() {
  const k = cronDiaKept(), best = LS.get('cronBest', 0);
  const dia = !k ? ['Linha do dia · nº ' + dayIndex(), 'A mesma linha para todo mundo, hoje']
    : k.done ? ['Linha do dia · feita', `${k.score} na linha · ver a sua linha`]
    : ['Linha do dia · continuar', `${k.picks.length} ${k.picks.length === 1 ? 'evento posto' : 'eventos postos'}, de onde parou`];
  return `
  <div class="pg cron-menu">
    ${topbar('Cronologia')}
    <div class="cron-menu-in">
      <span class="chal-ic mode-disc mode-cron" aria-hidden="true">${ICON.timeline('currentColor', 28)}</span>
      <div class="display" style="font-size:30px;"><em>Ponha a História em ordem</em></div>
      <p class="small muted cron-menu-p">Cada evento chega sem o ano: toque onde ele entra na linha do tempo. Errou o lugar, perde uma das três ampulhetas.</p>
      <button id="cron-dia" class="cron-opt is-day${k && k.done ? ' is-done' : ''}" type="button">
        <span class="mode-disc mode-${k && k.done ? 'done' : 'daily'}">${ICON.calendar('currentColor', 18)}</span>
        <span><b>${dia[0]}</b><small>${dia[1]}</small></span></button>
      <button id="cron-free" class="cron-opt" type="button">
        <span class="mode-disc mode-cron">${ICON.timeline('currentColor', 18)}</span>
        <span><b>Partida livre</b><small>${best > 0 ? 'Recorde: ' + best + ' na linha' : 'Uma linha nova a cada partida'}</small></span></button>
      <button id="cron-aod" class="cron-opt" type="button">
        <span class="mode-disc mode-aod">${ICON.hourglass('currentColor', 18)}</span>
        <span><b>Antes ou depois?</b><small>${LS.get('aodBest', 0) > 0 ? 'Recorde: ' + LS.get('aodBest', 0) + ' seguidos' : 'Dois eventos: qual veio primeiro? Até errar um'}</small></span></button>
    </div>
  </div>`;
}
function wireCronMenu() {
  const ready = tapArmed();
  document.getElementById('cron-dia')?.addEventListener('click', () => { if (ready()) { snd.select(); startCronDia(); } });
  document.getElementById('cron-free')?.addEventListener('click', () => { if (ready()) { snd.select(); startCron(); } });
  document.getElementById('cron-aod')?.addEventListener('click', () => { if (ready()) { snd.select(); startAod(); } });
}

/* the line keeps the newest event in the middle of its window, so the gaps around it are in reach */
function cronScroll() {
  const line = document.getElementById('cron-line'), el = document.getElementById('cron-fresh');
  if (line && el) line.scrollTop = Math.max(0, el.offsetTop - (line.clientHeight - el.offsetHeight) / 2);
}

function wireCron() {
  const on = (id, fn) => document.getElementById(id)?.addEventListener('click', fn);
  const ready = tapArmed();
  document.querySelectorAll('.cron-slot').forEach(b => b.addEventListener('click', () => { if (ready()) cronPlace(+b.dataset.slot); }));
  on('cron-next', () => { if (ready()) { snd.swipe(); cronNext(); } });
  on('cron-again', () => { if (ready()) { snd.select(); startCron(); } });
  on('cron-share', () => {
    const txt = cronShareText();
    if (navigator.share) navigator.share({ text: txt }).catch(() => {});
    else if (navigator.clipboard) navigator.clipboard.writeText(txt).then(() => {
      const b = document.getElementById('cron-share'); if (b) { b.dataset.l = b.dataset.l || b.textContent; b.textContent = 'Copiado!'; setTimeout(() => { b.textContent = b.dataset.l; }, 1600); } }).catch(() => {});
  });
  if (cron && cron.phase !== 'end') cronScroll();
  /* the keyboard follows the game: to Próximo, which reads the verdict out, and back to the gaps beside the newest event */
  const fx = cron && cron.fx; if (cron) cron.fx = null;
  const to = fx === 'next' ? document.getElementById('cron-next')
    : fx === 'slot' && cron.last ? document.querySelector(`.cron-slot[data-slot="${cron.line.indexOf(cron.last.e) + 1}"]`) : null;
  if (to) try { to.focus({ preventScroll: true }); } catch (e) {}
}

/* ═══════════════════════════════════════════════════
   ANTES OU DEPOIS? — one event, its year shown; the next, its year hidden:
   did it happen before or after? Right, and it becomes the one to beat;
   wrong, or too slow, and the run is over. The further the run goes, the
   closer the two years are and the shorter the clock. The Que ano? events
   (ANO_EVENTS) are the deck; none comes up twice in a run.
═══════════════════════════════════════════════════ */
/* from this many right, the next year is this many years away, at least and at most */
const AOD_BANDS = [[0, 200, 6000], [3, 70, 800], [6, 30, 320], [10, 12, 150], [15, 4, 80]];
let aod = null;   // { a, b, score, used, phase: 'guess'|'reveal'|'end', pick, ok, t0, tMax, log, tok }

const aodYear = e => (e.c ? 'c. ' : '') + anoYear(e.y);
const aodClock = n => Math.max(6, 12 - Math.floor(n / 3));      // seconds to answer, by the run so far

/* the next event: one not seen in this run, a fair distance from the last (an event dated "c." needs more
   room: its year is a guess too), and closer as the run grows; any unseen one when nothing fits */
function aodPick(a) {
  const [, lo, hi] = AOD_BANDS.filter(b => aod.score >= b[0]).pop();
  const free = ANO_EVENTS.filter(e => !aod.used.has(e.id) && e.y !== a.y);
  const fair = e => anoGap(a.y, e.y) >= ((a.c || e.c) ? Math.max(lo, 80) : lo);
  let pool = free.filter(e => fair(e) && anoGap(a.y, e.y) <= hi);
  if (!pool.length) pool = free.filter(fair);
  if (!pool.length) pool = free;
  return pool.length ? pool[Math.floor(aodRnd() * pool.length)] : null;
}

/* The run is dealt from its own seed, on its own generator (nothing else drawing numbers in between can
   change it), so a friend sent the link gets the same events in the same order for as long as they keep
   answering right (js/desafio.js). */
function aodRnd() {
  let t = (aod.rs = (aod.rs + 0x6D2B79F5) | 0);
  t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
/* a new run: the first event is one with a sure year */
function aodNew(seed) {
  clearTimeout(aod && aod.adv);
  if (seed == null) seed = (Math.random() * CHAL_SEED_MAX) | 0;
  aod = { seed, rs: seed, a: null, b: null, score: 0, used: new Set(), phase: 'guess', pick: null, ok: null, log: [], tok: 0, best0: LS.get('aodBest', 0) };
  const deck = ANO_EVENTS.filter(e => !e.c);
  aod.a = deck[Math.floor(aodRnd() * deck.length)]; aod.used.add(aod.a.id);
  aod.b = aodPick(aod.a); aod.used.add(aod.b.id);
  aodArm();
}
function startAod() {
  isDaily = false; isSurv = false; isMil = false; isRev = false;
  runSelos = [];
  aodNew(chalSeed('d'));
  sc = 'aod';
  go();
}
/* a new guess: the clock starts again, shorter as the run grows */
function aodArm() { aod.tMax = aodClock(aod.score); aod.t0 = performance.now(); aod.tok++; }

function aodAnswer(dir) {
  if (!aod || aod.phase !== 'guess') return;
  const { a, b } = aod, truth = b.y < a.y ? 'antes' : 'depois';
  aod.pick = dir; aod.ok = dir === truth; aod.phase = 'reveal'; aod.rolled = false;
  aod.log.push({ a, b, dir, ok: aod.ok });
  aod.selo = null;
  if (aod.ok) {
    aod.score++;
    stats.aodRight = (stats.aodRight || 0) + 1; LS.set('stats', stats);
    /* every fifth in a row, the event's scene goes into the stamp album, if it has one not yet there */
    if (aod.score % 5 === 0 && b.pic && b.pic.scene && awardSelo(b.pic.scene)) aod.selo = b.pic.scene;
    try { snd.correct(Math.min(aod.score - 1, 8)); } catch (e) {}
  } else {
    try { snd.wrong(); } catch (e) {}
    try { haptic([28, 45, 28]); } catch (e) {}
  }
  go();
  if (aod.ok) requestAnimationFrame(() => {
    const el = document.querySelector('.aod-b');
    try { fx.splash(el, '#3A9C6E', 10); haptic(12); streakMark(aod.score); } catch (e) {}
  });
  else requestAnimationFrame(() => { try { fx.edge('#B3402F', false); } catch (e) {} });
}

function aodNext() {
  if (!aod || aod.phase !== 'reveal') return;
  clearTimeout(aod.adv);
  if (!aod.ok) return aodEnd();
  const nb = aodPick(aod.b);
  if (!nb) { aod.all = true; return aodEnd(); }      // every event seen: the deck is spent
  aod.a = aod.b; aod.b = nb; aod.used.add(nb.id);
  aod.phase = 'guess'; aod.pick = null; aod.ok = null; aod.shift = true;
  aodArm();
  go();
}

function aodEnd() {
  aod.phase = 'end';
  stats.aodGames = (stats.aodGames || 0) + 1;
  stats.aodBest = Math.max(stats.aodBest || 0, aod.score);
  aod.isBest = aod.score > aod.best0;
  if (aod.isBest) LS.set('aodBest', aod.score);
  LS.set('stats', stats);
  window._newMedals = newMedals();
  setTimeout(() => { try { snd.final(aod.score >= 5); } catch (e) {} }, 200);
  go();
  if (aod.isBest && aod.score >= 5) setTimeout(() => { try { fx.rain(aod.score >= 15 ? 80 : 34); } catch (e) {} }, 350);
}

function aodCard(e, which, rev) {
  const hid = which === 'b' && !rev;
  return `<div class="aod-card aod-${which}${which === 'b' && rev ? (aod.ok ? ' is-good' : ' is-bad') : ''}${which === 'a' && aod.shift ? ' is-shifted' : ''}">
    <span class="aod-pic">${anoPic(e)}</span>
    <span class="aod-tx"><span class="aod-t">${_esc(e.t)}</span>
      <b class="aod-y num${hid ? ' is-hid' : ''}" ${which === 'b' ? 'id="aod-yb"' : ''}${hid ? ' aria-label="ano escondido"' : ''}>${hid ? '????' : aodYear(e)}</b></span>
  </div>`;
}

function aodHtml() {
  if (!aod) aodNew();
  if (aod.phase === 'end') return aodEndHtml();
  const { a, b } = aod, rev = aod.phase === 'reveal';
  const best = Math.max(aod.best0, aod.score);
  const up = ICON.back('currentColor', 15).replace('<svg', '<svg style="transform:rotate(90deg)"');
  const down = ICON.back('currentColor', 15).replace('<svg', '<svg style="transform:rotate(-90deg)"');
  const gap = anoGap(a.y, b.y), when = b.y < a.y ? 'antes' : 'depois';
  const wait = b.x ? Math.min(7000, 2000 + b.x.length * 32) : 1500;
  const html = `
  <div class="pg aod-pg${rev ? ' is-rev' : ''}">
    ${topbar('Antes ou depois?')}
    <div class="aod-head">
      <span class="aod-run">${ICON.flame('currentColor', 13)} <b class="num">${aod.score}</b> ${aod.score === 1 ? 'acerto' : 'acertos'} seguidos</span>
      <span class="aod-best">Recorde <b class="num">${best}</b></span>
    </div>
    <div class="timer aod-timer"><i id="aod-tf" style="width:${rev ? 0 : 100}%"></i></div>
    ${aodCard(a, 'a', rev)}
    <div class="aod-q"><span>${rev ? (aod.ok ? 'Isso!' : aod.pick ? 'Não…' : 'O tempo acabou') : 'E este aconteceu…'}</span></div>
    ${aodCard(b, 'b', rev)}
    ${rev ? `<div class="aod-res" role="status">
        <p class="aod-verdict ${aod.ok ? 'good' : 'bad'}">${gap === 0 ? 'No mesmo ano' : `${gap} ${gap === 1 ? 'ano' : 'anos'} ${when}`}</p>
        ${aod.selo ? seloWonLine(aod.selo) : ''}
        ${b.x ? `<div class="story"><span class="story-k">${ICON.book('currentColor', 11)} Você sabia?</span><p>${_esc(b.x)}</p></div>` : ''}
        <button id="aod-next" class="btn ${aod.ok ? 'btn-ghost btn-sm btn-next' : 'btn-brass'}" style="--wait:${wait}ms">
          ${aod.ok ? `Próximo ${ICON.back('currentColor', 11).replace('<svg', '<svg style="transform:scaleX(-1)"')}<i class="next-fill"></i>` : 'Ver resultado'}</button>
      </div>`
    : `<div class="aod-btns">
        <button id="aod-antes" class="aod-btn" type="button">${up}<b>Antes</b><small>de ${aodYear(a)}</small></button>
        <button id="aod-depois" class="aod-btn" type="button">${down}<b>Depois</b><small>de ${aodYear(a)}</small></button>
      </div>`}
  </div>`;
  aod.wait = wait;
  return html;
}

function aodEndHtml() {
  const n = aod.score, last = aod.log[aod.log.length - 1];
  const msg = aod.all ? 'Você viu a História inteira!' : n >= 20 ? 'Senhor do tempo!' : n >= 12 ? 'Que memória!' : n >= 6 ? 'Muito bem!' : n >= 3 ? 'Nada mau!' : 'O tempo engana…';
  const miss = last && !last.ok ? last : null;
  return `
  <div class="pg pg-center aod-end" style="padding:22px 18px;gap:9px;">
    <div class="eyebrow">Antes ou depois?</div>
    <div class="display" style="font-size:28px;"><em>${msg}</em></div>
    ${wreathed(n >= 8, `<div class="display prize-pop brass aod-end-n">${n}</div>`)}
    <div class="aod-end-k">${n === 1 ? 'acerto seguido' : 'acertos seguidos'}</div>
    ${chalBanner() || `<p class="small muted">${aod.isBest ? 'Seu novo recorde!' : `Recorde: ${aod.best0}`}</p>`}
    ${miss ? `<div class="aod-miss">
        <span class="aod-miss-k">${miss.dir ? 'Onde a corrente quebrou' : 'O tempo acabou em'}</span>
        <span class="aod-miss-row"><b class="num">${aodYear(miss.b)}</b><span>${_esc(miss.b.t)}</span></span>
        <span class="aod-miss-vs">${miss.b.y < miss.a.y ? 'antes de' : 'depois de'}</span>
        <span class="aod-miss-row"><b class="num">${aodYear(miss.a)}</b><span>${_esc(miss.a.t)}</span></span>
      </div>` : ''}
    ${selosStrip()}
    ${medalChips()}
    <div class="foot-row" style="margin-top:8px;">
      <button id="aod-share" class="btn btn-ghost btn-sm">${chalMine() ? 'Desafiar' : 'Compartilhar'}</button>
      <button id="aod-again" class="btn btn-brass">De novo</button>
      <button id="bhome" class="btn btn-ghost btn-sm">Início</button>
    </div>
  </div>`;
}

const aodShareText = () => `Antes ou depois? ⏳ History Quiz\n${'🟩'.repeat(Math.min(aod.score, 20))}${aod.score > 20 ? '…' : ''}${aod.all ? '' : '🟥'}\n${aod.score} ${aod.score === 1 ? 'acerto' : 'acertos'} seguidos${aod.isBest ? ' · recorde!' : ''}\n${chalShareTail(chalMine())}`;

/* the clock: a bar that empties; at zero the guess is a miss */
let _aodTmr = null;
function aodTick() {
  clearInterval(_aodTmr);
  const tok = aod.tok;
  _aodTmr = setInterval(() => {
    if (sc !== 'aod' || !aod || aod.phase !== 'guess' || aod.tok !== tok) { clearInterval(_aodTmr); return; }
    if (document.hidden) return;
    const left = aod.tMax - (performance.now() - aod.t0) / 1000;
    const tf = document.getElementById('aod-tf');
    if (tf) {
      tf.style.width = Math.max(0, left / aod.tMax * 100).toFixed(1) + '%';
      tf.className = left <= 2.5 ? 't-bad timer-low' : left <= 5 ? 't-warn' : '';
    }
    if (left <= 3 && left > 0 && Math.ceil(left) !== aod.lastTick) { aod.lastTick = Math.ceil(left); try { snd.tick(aod.lastTick); } catch (e) {} }
    if (left <= 0) { clearInterval(_aodTmr); aodAnswer(null); }
  }, 100);
}

/* the hidden year, at the reveal, runs from the last year to its own, like the drum of a date stamp */
function aodRoll() {
  const el = document.getElementById('aod-yb');
  if (!el || aod.rolled) return;
  aod.rolled = true;
  const { a, b } = aod, txt = aodYear(b);
  if (FX_STILL) { el.textContent = txt; return; }
  const t0 = performance.now(), dur = 520;
  const land = setTimeout(() => { el.textContent = txt; }, dur + 80);
  let lastK = 0;
  const step = now => {
    if (!document.body.contains(el)) return clearTimeout(land);
    const k = Math.min(1, (now - t0) / dur), y = Math.round(a.y + (b.y - a.y) * (1 - Math.pow(1 - k, 3)));
    el.textContent = k >= 1 ? txt : anoYear(y === 0 ? (b.y < 0 ? -1 : 1) : y);
    if (k - lastK > .12) { lastK = k; try { snd.count(k); } catch (e) {} }
    if (k < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

function wireAod() {
  if (!aod) return;
  const on = (id, fn) => document.getElementById(id)?.addEventListener('click', fn);
  const ready = tapArmed();
  on('aod-antes', () => { if (ready()) aodAnswer('antes'); });
  on('aod-depois', () => { if (ready()) aodAnswer('depois'); });
  on('aod-next', () => { if (ready()) { snd.swipe(); aodNext(); } });
  on('aod-again', () => { snd.select(); startAod(); });
  on('aod-share', () => {
    const txt = aodShareText();
    if (navigator.share) navigator.share({ text: txt }).catch(() => {});
    else if (navigator.clipboard) navigator.clipboard.writeText(txt).then(() => {
      const b = document.getElementById('aod-share'); if (b) { b.dataset.l = b.dataset.l || b.textContent; b.textContent = 'Copiado!'; setTimeout(() => { b.textContent = b.dataset.l; }, 1600); } }).catch(() => {});
  });
  aod.shift = false;
  if (aod.phase === 'guess') aodTick();
  if (aod.phase === 'reveal') {
    aodRoll();
    /* a right answer moves on by itself (a tap is quicker); a miss waits to be read */
    if (aod.ok && !aod.adv) {
      const tok = aod.tok;
      aod.adv = setTimeout(() => { aod.adv = null; if (sc === 'aod' && aod.phase === 'reveal' && aod.tok === tok) aodNext(); }, aod.wait || 1500);
    }
  } else aod.adv = null;
}
/* the clock stops while the app is away (a call, another app) and goes on from where it was */
document.addEventListener('visibilitychange', () => {
  if (!aod || aod.phase !== 'guess') return;
  if (document.hidden) aod.hid = performance.now();
  else if (aod.hid) { aod.t0 += performance.now() - aod.hid; aod.hid = 0; }
});
/* the keyboard: up or left is before, down or right is after, Enter goes on */
document.addEventListener('keydown', ev => {
  if (sc !== 'aod' || !aod || ev.altKey || ev.ctrlKey || ev.metaKey) return;
  if (aod.phase === 'guess' && (ev.key === 'ArrowUp' || ev.key === 'ArrowLeft')) { ev.preventDefault(); aodAnswer('antes'); }
  else if (aod.phase === 'guess' && (ev.key === 'ArrowDown' || ev.key === 'ArrowRight')) { ev.preventDefault(); aodAnswer('depois'); }
  else if (aod.phase === 'reveal' && ev.key === 'Enter' && document.activeElement === document.body) { ev.preventDefault(); aodNext(); }
});

/* ═══════════════════════════════════════════════════
   JORNADA PELA HISTÓRIA — the history of the world as a road, stop by stop
   Six eras, three stops each, and at the end of the road the Arquivo Secreto.
   A stop is a round of its own part of history, eight questions from easy to
   hard: half of them right passes it and opens the next stop, more give more
   stars (three at most). The road is drawn as an old map, an era a page, the
   stops as medallions with their scene; an era with all its stops passed is
   sealed. The rounds are the game's own (its clock, its lifelines, its
   stickers), only kept apart from the difficulty records.
═══════════════════════════════════════════════════ */
const JOR_N = 8;
const JOR_ERAS = [
  { id: 'antiga', n: 'Antiguidade', roman: 'I', ic: 'pyramid', col: '#9E1B1B', stops: [
    { id: 'nilo', n: 'Às margens do Nilo', sub: 'Egito e Mesopotâmia', cats: ['egito_mesopotamia'], scene: 'piramides_gize' },
    { id: 'atenas', n: 'A Grécia dos filósofos', sub: 'Atenas, Esparta e Alexandre', cats: ['grecia'], scene: 'teatro_grego' },
    { id: 'roma', n: 'Todos os caminhos', sub: 'Da República ao Império Romano', cats: ['roma'], scene: 'forum_romano' } ] },
  { id: 'media', n: 'Idade Média', roman: 'II', ic: 'castle', col: '#6B4A2E', stops: [
    { id: 'castelos', n: 'Castelos e cruzadas', sub: 'A Europa medieval', cats: ['medieval'], scene: 'torre_branca' },
    { id: 'seda', n: 'A Rota da Seda', sub: 'China, Japão, Índia e as estepes', cats: ['oriente'], scene: 'samarcanda' },
    { id: 'mali', n: 'O ouro do Mali', sub: 'Reinos e impérios africanos', cats: ['africa'], scene: 'caravana_mali' } ] },
  { id: 'navegacoes', n: 'Navegações e Renascimento', roman: 'III', ic: 'ship', col: '#2E5E7E', stops: [
    { id: 'mar', n: 'Mares nunca dantes navegados', sub: 'As Grandes Navegações', cats: ['descobrimentos'], scene: 'adamastor' },
    { id: 'florenca', n: 'Florença e a Reforma', sub: 'Renascimento, Reforma e artes', cats: ['renascimento', 'artes'], scene: 'afresco_vaticano' },
    { id: 'novo_mundo', n: 'O Novo Mundo', sub: 'Maias, astecas, incas e independências', cats: ['americas'], scene: 'tenochtitlan' } ] },
  { id: 'revolucoes', n: 'Reis e revoluções', roman: 'IV', ic: 'crown', col: '#7B2D26', stops: [
    { id: 'versalhes', n: 'O Rei Sol', sub: 'Absolutismo e Luzes', cats: ['absolutismo', 'idade_moderna'], scene: 'versalhes_espelhos' },
    { id: 'bastilha', n: 'A queda da Bastilha', sub: 'A era das revoluções', cats: ['revolucoes'], scene: 'guilhotina' },
    { id: 'vapor', n: 'O século do vapor', sub: 'O século XIX, a ciência e as invenções', cats: ['seculo19', 'ciencia'], scene: 'locomotiva_vapor' } ] },
  { id: 'brasil', n: 'Brasil', roman: 'V', ic: 'flag', col: '#2E6B3F', stops: [
    { id: 'terra', n: 'Terra à vista', sub: 'O Brasil Colônia e Império', cats: ['brasil_colonia'], scene: 'chegada_cabral' },
    { id: 'republica', n: 'Viva a República', sub: 'O Brasil republicano', cats: ['brasil_republica'], scene: 'republica_1889' },
    { id: 'gente', n: 'Gente que fez o Brasil', sub: 'Brasileiros de todas as épocas', who: 'BRA', scene: 'abaporu' } ] },
  { id: 'seculo20', n: 'O século XX', roman: 'VI', ic: 'rocket', col: '#3A4A5C', stops: [
    { id: 'guerras', n: 'As grandes guerras', sub: 'A Primeira e a Segunda Guerra', cats: ['guerras_mundiais'], scene: 'ev_segunda_guerra' },
    { id: 'lua', n: 'Rumo à Lua', sub: 'A Guerra Fria e a corrida espacial', cats: ['guerra_fria'], scene: 'pouso_lua' },
    { id: 'seculo', n: 'Um século de mudanças', sub: 'Do voto das mulheres aos direitos civis', cats: ['seculo20', 'mulheres'], scene: 'onibus_montgomery' } ] },
  /* the end of the road: one stop, ten of the hardest questions from anywhere */
  { id: 'arquivo', n: 'O Arquivo Secreto', roman: 'VII', ic: 'book', col: '#5A3E1B', fin: true, stops: [
    { id: 'arquivo', n: 'O Arquivo Secreto', sub: 'As perguntas mais difíceis, de todas as épocas', all: true, size: 10, scene: 'biblioteca_alexandria' } ] },
];
const JOR_STOPS = JOR_ERAS.flatMap(e => e.stops.map(s => Object.assign(s, { era: e })));
/* where the stops of a page stand on its map, in per cent of it */
const JOR_AT = { 3: [[27, 17], [71, 45], [31, 74]], 1: [[50, 44]] };
let jorPage = null, jorSel = null;

const jorProg = () => { const p = LS.get('jornada', null); return p && p.st ? p : { st: {}, pts: {} }; };
const jorStars = id => jorProg().st[id] || 0;
/* the first stop not yet passed (or none: the road is done) */
const jorNextIdx = () => { const p = jorProg(); const i = JOR_STOPS.findIndex(s => !(p.st[s.id] > 0)); return i; };
const jorOpen = i => i === 0 || jorStars(JOR_STOPS[i - 1].id) > 0;
const jorTotal = () => JOR_STOPS.reduce((n, s) => n + jorStars(s.id), 0);
/* how many right for one, two and three stars, out of n */
const jorNeed = n => [Math.ceil(n / 2), Math.ceil(n * .65), Math.ceil(n * .875)];
const jorStarsFor = (right, n) => jorNeed(n).filter(k => right >= k).length;
const jorEraDone = (e, p) => e.stops.every(s => (p.st[s.id] || 0) > 0);
const isJorRun = () => !!(cat && cat.themed && cat.themed.jor != null);

/* a stop's questions: its categories (or its people, or the hardest of all), dealt easy to hard */
function jorPool(stop) {
  const all = CATS.flatMap(c => c.qs.map(q => ({ ...q, _cat: c })));
  if (stop.all) return all.filter(q => q.d >= 3);
  if (stop.who) return all.filter(q => {
    const id = q.type === 'player' && !q.order ? q.a[0] : q.detail ? q.detail.who : null;
    const p = id && PL.find(x => x.id === id);
    return p && p.ctry === stop.who;
  });
  return all.filter(q => stop.cats.includes(q._cat.id));
}
function jorDeal(stop) {
  const n = stop.size || JOR_N, pool = shuf(jorPool(stop)), took = new Set(), ans = new Set(), out = [];
  const take = (f, k) => { for (const q of pool) {
    if (out.length >= n || k <= 0) return;
    if (took.has(q) || ans.has(ansKey(q)) || !f(q)) continue;
    took.add(q); ans.add(ansKey(q)); out.push(q); k--;
  } };
  const third = Math.round(n * 3 / 8);
  take(q => q.d <= 2, third);
  take(q => q.d >= 2 && q.d <= 3, third);
  take(q => q.d >= 3, n - 2 * third);
  take(() => true, n);
  return out.sort((a, b) => a.d - b.d);
}
/* a themed round on the game's own board: Novidades and the Jornada's stops */
function startThemed(c) {
  isDaily = false; isSurv = false; isMil = false; isRev = false;
  diffKey = 'moderado';
  runSeed = null;
  cat = c;
  qi = 0; sel.clear(); pts = 0; prevPts = 0; streak = 0;
  nCorrect = 0; nPartial = 0; bestStreak = 0; lastGain = 0; runLog = []; runNew = 0; runNewIds = []; runPulls = []; runSelos = []; runPackOpened = false; gameN++;
  resetLifes();
  sc = 'quiz'; tMax = qTime(); tLeft = tMax; lastMsg = '';
  disp = dealDisp(0);
  startTmr();
  go();
}
function startJor(i) {
  const s = JOR_STOPS[i];
  if (!s || !jorOpen(i)) return;
  window._jorRes = null;
  startThemed({ id: 'jor', name: s.n, emoji: '🗺️', tag: s.sub, col: s.era.col, diff: 'Jornada', qs: jorDeal(s),
    themed: { label: 'Jornada · ' + s.n, again: () => startJor(i), jor: i } });
}
/* the round is over: its stars kept (the best of them), what it opened said on the results */
function jorFinish(i) {
  const s = JOR_STOPS[i], n = cat.qs.length, st = jorStarsFor(nCorrect, n), p = jorProg();
  const prev = p.st[s.id] || 0, eraWas = jorEraDone(s.era, p);
  if (st > prev) p.st[s.id] = st;
  p.pts[s.id] = Math.max(p.pts[s.id] || 0, pts);
  LS.set('jornada', p);
  const need = jorNeed(n);
  stats.jorRounds = (stats.jorRounds || 0) + 1;
  stats.jorStars = jorTotal();
  stats.jorDone = JOR_STOPS.filter(x => (p.st[x.id] || 0) > 0).length;
  stats.jorEras = JOR_ERAS.filter(e => jorEraDone(e, p)).length;
  window._jorRes = { i, st, prev, best: Math.max(st, prev), more: st < 3 ? need[st] - nCorrect : 0,
    next: st > 0 && i + 1 < JOR_STOPS.length ? i + 1 : null, opened: st > 0 && prev === 0 && i + 1 < JOR_STOPS.length,
    eraNew: !eraWas && jorEraDone(s.era, p) ? s.era : null, end: st > 0 && prev === 0 && i === JOR_STOPS.length - 1 };
}

/* ── the pictures ── */
const JOR_STAR = (on, s) => `<svg viewBox="0 0 24 24" width="${s}" height="${s}" aria-hidden="true"><path d="M12 2.6l2.9 6 6.5.8-4.8 4.5 1.2 6.5L12 17.2l-5.8 3.2 1.2-6.5L2.6 9.4l6.5-.8Z"
  fill="${on ? '#E0B04A' : 'none'}" stroke="${on ? '#8A5A14' : 'currentColor'}" stroke-width="1.4" stroke-linejoin="round"/></svg>`;
const jorStarRow = (n, s, cls) => `<span class="jor-stars${cls ? ' ' + cls : ''}" aria-label="${n} de 3 estrelas">${[0, 1, 2].map(k => JOR_STAR(k < n, s)).join('')}</span>`;
const jorScene = (id, w) => (sceneSvg({ id }, w) || ART.hourglass(w))
  .replace('<svg ', '<svg preserveAspectRatio="xMidYMid slice" ').replace('style="display:block;max-width:100%;height:auto;"', 'style="display:block;width:100%;height:100%"');
const JOR_ROSE = `<svg class="jor-rose" viewBox="0 0 60 60" aria-hidden="true"><g fill="none" stroke="#6B4A22" stroke-width=".8"><circle cx="30" cy="30" r="21"/><circle cx="30" cy="30" r="17" stroke-dasharray="1.2 1.6"/></g>
  <path d="M30 4 34 26 56 30 34 34 30 56 26 34 4 30 26 26Z" fill="#B8862F" stroke="#6B4A22" stroke-width=".8" stroke-linejoin="round"/>
  <path d="M30 4 34 26 30 30ZM56 30 34 34 30 30ZM30 56 26 34 30 30ZM4 30 26 26 30 30Z" fill="#7A5420"/>
  <text x="30" y="3.2" text-anchor="middle" font-family="Fraunces, Georgia, serif" font-weight="700" font-size="5" fill="#6B4A22">N</text></svg>`;
const JOR_PIN = `<svg viewBox="0 0 30 40" aria-hidden="true"><path d="M15 38C6 24 3 19 3 13a12 12 0 0 1 24 0c0 6-3 11-12 25Z" fill="#9B2226" stroke="#4A0E10" stroke-width="1.2"/>
  <circle cx="15" cy="13" r="5" fill="#F4E4C0" stroke="#4A0E10" stroke-width="1"/></svg>`;
const JOR_LOCK = `<svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true"><rect x="5" y="10.5" width="14" height="10" rx="2" fill="#5C4A36"/><path d="M8 10.5V8a4 4 0 0 1 8 0v2.5" fill="none" stroke="#5C4A36" stroke-width="2.2"/><circle cx="12" cy="15.3" r="1.6" fill="#E8DCC4"/></svg>`;

/* the road through a page's stops: in from the top, out at the bottom (a smooth line through them) */
function jorRoad(pts, fin) {
  const P = [[9, -6]].concat(pts).concat(fin ? [] : [[90, 106]]);
  let d = `M${P[0][0]} ${P[0][1]}`;
  for (let i = 0; i < P.length - 1; i++) {
    const p0 = P[i - 1] || P[i], p1 = P[i], p2 = P[i + 1], p3 = P[i + 2] || p2;
    const c1 = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6], c2 = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
    d += `C${c1.map(v => v.toFixed(1)).join(' ')} ${c2.map(v => v.toFixed(1)).join(' ')} ${p2.join(' ')}`;
  }
  return d;
}

function jorHtml() {
  const p = jorProg(), nx = jorNextIdx();
  if (jorPage == null) jorPage = Math.max(0, JOR_ERAS.indexOf((JOR_STOPS[nx] || JOR_STOPS[JOR_STOPS.length - 1]).era));
  const e = JOR_ERAS[jorPage], at = JOR_AT[e.stops.length] || JOR_AT[3];
  const base = JOR_STOPS.indexOf(e.stops[0]), done = jorEraDone(e, p);
  const total = jorTotal(), max = JOR_STOPS.length * 3, passed = JOR_STOPS.filter(s => (p.st[s.id] || 0) > 0).length;
  const eraOpen = jorOpen(base);
  const stops = e.stops.map((s, k) => {
    const i = base + k, open = jorOpen(i), st = p.st[s.id] || 0, here = i === nx;
    const [x, y] = at[k];
    return `<button class="jor-stop${open ? '' : ' is-locked'}${here ? ' is-here' : ''}${st === 3 ? ' is-gold' : st ? ' is-done' : ''}" data-i="${i}" type="button"
        style="left:${x}%;top:${y}%" aria-label="Parada ${i + 1}: ${_esc(s.n)}. ${open ? st + ' de 3 estrelas' : 'bloqueada'}">
      ${here ? `<span class="jor-pin">${JOR_PIN}</span>` : ''}
      <span class="jor-medal">${jorScene(s.scene, 120)}${open ? '' : `<span class="jor-lock">${JOR_LOCK}</span>`}</span>
      <span class="jor-name"><i>${i + 1}</i>${s.n}</span>
      ${open ? jorStarRow(st, 15) : ''}
    </button>`;
  }).join('');
  const go = nx >= 0 ? JOR_STOPS[nx] : null;
  return `
  <div class="pg jor-pg">
    ${topbar('Jornada pela História')}
    <div class="jor-head">
      <button id="jor-prev" class="jor-arrow" type="button" aria-label="Era anterior"${jorPage === 0 ? ' disabled' : ''}>${ICON.back('currentColor', 14)}</button>
      <div class="jor-cart"><small>${e.fin ? 'O fim da estrada' : 'Era ' + e.roman}</small><b>${e.n}</b></div>
      <button id="jor-next" class="jor-arrow" type="button" aria-label="Próxima era"${jorPage === JOR_ERAS.length - 1 ? ' disabled' : ''}>${ICON.back('currentColor', 14).replace('<svg', '<svg style="transform:scaleX(-1)"')}</button>
    </div>
    <div class="jor-sum"><span>${JOR_STAR(true, 13)} <b class="num">${total}</b>/${max}</span><span>${passed} de ${JOR_STOPS.length} paradas</span>
      <span class="jor-dots" aria-hidden="true">${JOR_ERAS.map((x, k) => `<i class="${k === jorPage ? 'on' : ''}${jorEraDone(x, p) ? ' ok' : ''}"></i>`).join('')}</span></div>
    <div class="jor-map${eraOpen ? '' : ' is-fog'}${e.fin ? ' is-fin' : ''}" id="jor-map" style="--era:${e.col}">
      <span class="jor-mark" aria-hidden="true">${(QICON[e.ic] || QICON.scroll)(220)}</span>
      <svg class="jor-road" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">
        <path d="${jorRoad(at, e.fin)}" fill="none" stroke="#6B4A22" stroke-width="2.4" stroke-dasharray="2 7" stroke-linecap="round" vector-effect="non-scaling-stroke"/></svg>
      ${JOR_ROSE}
      ${stops}
      ${done ? `<span class="jor-sealed" aria-hidden="true"><small>Era</small>${e.roman}<small>${e.fin ? 'vencida' : 'concluída'}</small></span>` : ''}
      ${!eraOpen ? '<span class="jor-fog-t">Terra incógnita</span>' : ''}
    </div>
    <div class="jor-foot">
      ${go ? `<button id="jor-go" class="btn btn-brass btn-lg" type="button">${ICON.play('currentColor', 13)} Parada ${nx + 1}: ${go.n}</button>`
        : `<p class="jor-endline">${JOR_STAR(true, 16)} A Jornada inteira, percorrida. Volte às paradas para mais estrelas.</p>`}
    </div>
    ${jorSel != null ? jorSheet(jorSel) : ''}
  </div>`;
}

/* a stop, close up: what it is, what it takes, what it has given */
function jorSheet(i) {
  const s = JOR_STOPS[i], open = jorOpen(i), st = jorStars(s.id), n = s.size || JOR_N, need = jorNeed(n);
  return `<div class="jor-veil" id="jor-veil"></div>
  <div class="jor-sheet" role="dialog" aria-label="Parada ${i + 1}: ${_esc(s.n)}" style="--era:${s.era.col}">
    <span class="jor-sheet-pic">${jorScene(s.scene, 240)}</span>
    <span class="jor-sheet-k">Parada ${i + 1} · ${s.era.fin ? 'o fim da estrada' : 'Era ' + s.era.roman}</span>
    <b class="jor-sheet-n">${s.n}</b>
    <span class="jor-sheet-sub">${s.sub}</span>
    ${open ? `<span class="jor-sheet-need">${n} perguntas, do fácil ao difícil ·
        ${need.map((k, j) => `<span>${JOR_STAR(true, 11).repeat(j + 1)} ${k}</span>`).join('')}</span>
      ${jorStarRow(st, 22, 'jor-sheet-st')}
      <button id="jor-start" class="btn btn-brass" type="button" data-i="${i}">${ICON.play('currentColor', 12)} ${st ? 'Jogar de novo' : 'Partir'}</button>`
    : `<span class="jor-sheet-lock">${JOR_LOCK} Passe pela parada ${i} para chegar aqui.</span>`}
    <button id="jor-close" class="btn btn-ghost btn-sm" type="button">Voltar ao mapa</button>
  </div>`;
}

function wireJor() {
  const on = (id, fn) => document.getElementById(id)?.addEventListener('click', fn);
  const ready = tapArmed();
  const page = d => { const k = Math.max(0, Math.min(JOR_ERAS.length - 1, jorPage + d)); if (k !== jorPage) { jorPage = k; jorSel = null; snd.page(); go(); } };
  on('jor-prev', () => page(-1));
  on('jor-next', () => page(1));
  document.querySelectorAll('.jor-stop').forEach(b => b.addEventListener('click', () => { if (!ready()) return; jorSel = +b.dataset.i; snd.select(); go(); }));
  on('jor-go', () => { if (!ready()) return; const i = jorNextIdx(); if (i >= 0) { jorSel = i; jorPage = JOR_ERAS.indexOf(JOR_STOPS[i].era); snd.select(); go(); } });
  on('jor-start', () => { if (!ready()) return; const i = +document.getElementById('jor-start').dataset.i; jorSel = null; snd.rung(); startJor(i); });
  const close = () => { jorSel = null; snd.swipe(); go(); };
  on('jor-close', close);
  on('jor-veil', close);
  /* a swipe across the map turns the page */
  const map = document.getElementById('jor-map');
  if (map) {
    let x0 = null;
    map.addEventListener('pointerdown', ev => { x0 = ev.clientX; }, { passive: true });
    map.addEventListener('pointerup', ev => { if (x0 == null) return; const dx = ev.clientX - x0; x0 = null; if (Math.abs(dx) > 60 && jorSel == null) page(dx < 0 ? 1 : -1); }, { passive: true });
  }
}
document.addEventListener('keydown', ev => {
  if (sc !== 'jornada' || ev.altKey || ev.ctrlKey || ev.metaKey) return;
  if (jorSel != null && ev.key === 'Escape') { jorSel = null; go(); return; }
  if (jorSel == null && (ev.key === 'ArrowLeft' || ev.key === 'ArrowRight')) {
    const k = Math.max(0, Math.min(JOR_ERAS.length - 1, jorPage + (ev.key === 'ArrowRight' ? 1 : -1)));
    if (k !== jorPage) { jorPage = k; go(); }
  }
});

/* the round's results, for a stop: its stars instead of a title, and the way on */
function jorEndHtml() {
  const r = window._jorRes;
  if (!r) return '';
  const s = JOR_STOPS[r.i];
  const say = r.st === 3 ? 'Três estrelas!' : r.st === 0 ? `Acerte ${jorNeed(cat.qs.length)[0]} para seguir viagem`
    : `Faltou ${r.more} ${r.more === 1 ? 'acerto' : 'acertos'} para ${r.st + 1} estrelas`;
  return `<div class="jor-end">
    <span class="jor-end-k">Parada ${r.i + 1} · ${s.n}</span>
    ${jorStarRow(r.st, 30, 'jor-end-st')}
    <small>${say}${r.best > r.st ? ` · sua melhor: ${r.best}` : ''}</small>
    ${r.eraNew ? `<span class="chip chip-brass jor-era-chip">${ICON.flag('currentColor', 11)} ${r.eraNew.fin ? 'A Jornada inteira, vencida!' : 'Era ' + r.eraNew.roman + ' concluída: ' + r.eraNew.n}</span>`
      : r.opened ? `<span class="chip chip-soft jor-open-chip">${ICON.play('currentColor', 10)} Parada ${r.next + 1} aberta: ${JOR_STOPS[r.next].n}</span>` : ''}
  </div>`;
}

